window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-07-09"]={"date":"2026-07-09","dateKR":"2026년 7월 9일","dateEN":"9 July 2026","total":249,"sections":[{"code":"TOP","type":"news","kTitle":"Section 1. 주요 뉴스","eTitle":"Section 1. Top News","items":[{"code":"TOP","title":"트럼프 \"이란과 휴전 끝났다\" 선언, 호르무즈 긴장 고조","src":"gCaptain","date":"2026-07-08","kSum":"트럼프 대통령이 이란과의 휴전이 끝났다고 밝히며 미군의 추가 공습 가능성을 시사했다. 호르무즈 해협 일대 상선 공격이 이어지며 해운업계의 안전 우려가 커지고 있다.","eSum":"President Trump declared the ceasefire with Iran is over after renewed strikes, raising fears of fresh military escalation. Attacks on merchant vessels in the Strait of Hormuz have continued to rattle shipowners.","kImp":"호르무즈 통항 리스크가 재차 확대되며 유조선 운임과 전쟁보험료 상승이 불가피해질 전망이다.","eImp":"Renewed Hormuz risk is likely to push tanker freight rates and war-risk insurance premiums higher.","url":"https://gcaptain.com/trump-says-us-ceasefire-with-iran-is-over-after-strikes/"},{"code":"TOP","title":"美 컨테이너 수입, 관세 시한 앞두고 사상 최대치 전망","src":"gCaptain","date":"2026-07-08","kSum":"미국 소매업체들이 8월 관세 발효를 앞두고 수입을 서두르면서 7월 미국 항만 물동량이 247만 TEU로 역대 최고치를 기록할 전망이다. 이는 2022년 5월 세운 종전 기록을 넘어서는 수치다.","eSum":"U.S. container imports are set to hit an all-time monthly record in July as retailers rush shipments ahead of an August tariff deadline, with ports forecast to handle 2.47 million TEU, surpassing the prior record.","kImp":"관세 시한 이후 급격한 물동량 조정과 항만 혼잡 재발 가능성에 대비해야 한다.","eImp":"Ports should brace for a sharp volume pullback and possible congestion once the tariff deadline passes.","url":"https://gcaptain.com/u-s-container-imports-set-to-break-pandemic-era-record-ahead-of-tariff-deadline/"},{"code":"TOP","title":"美 항소법원, FMC의 부당 디텐션료 규제 권한 인정","src":"gCaptain","date":"2026-07-08","kSum":"미국 연방항소법원이 선사들이 화물 이동을 촉진하지 않는 디텐션료를 부과할 수 없다는 연방해사위원회(FMC)의 결정을 지지했다. 화주 업계의 오랜 요구가 법적으로 확인된 판결이다.","eSum":"A U.S. federal appeals court upheld the FMC's authority to strike down container detention fees that fail to serve their intended purpose, a landmark win for cargo owners against ocean carriers.","kImp":"선사들의 디텐션·디머리지 청구 관행에 대한 규제 압박이 한층 강화될 것으로 보인다.","eImp":"Carriers face intensified regulatory scrutiny over detention and demurrage billing practices.","url":"https://gcaptain.com/appeals-court-upholds-fmcs-authority-to-strike-down-unreasonable-container-detention-fees/"},{"code":"TOP","title":"Maersk·Hapag-Lloyd, 수에즈·홍해 항로 재개 시도","src":"The Maritime Executive","date":"2026-07-08","kSum":"Maersk와 Hapag-Lloyd가 Gemini 협력체제 하에 수에즈 운하·홍해 항로 재진입을 다시 시도한다. 말레이시아를 출발한 선박이 7월 24일경 수에즈 운하에 도착할 예정이다.","eSum":"Maersk and Hapag-Lloyd have agreed to again attempt a return to Suez Canal and Red Sea transit for one route under the Gemini Cooperation, with a vessel departing Malaysia expected to reach Suez around July 24.","kImp":"홍해 항로 정상화가 현실화되면 희망봉 우회 운임 프리미엄이 점차 축소될 수 있다.","eImp":"A successful Red Sea return could gradually erode the freight premium tied to Cape of Good Hope diversions.","url":"https://maritime-executive.com/article/maersk-and-hapag-to-shift-one-route-to-suez-red-sea-transit"},{"code":"TOP","title":"CMA CGM, FedEx Supply Chain 14억달러에 인수","src":"The Maritime Executive","date":"2026-07-01","kSum":"CMA CGM이 FedEx의 물류 자회사 FedEx Supply Chain을 기업가치 14억 달러에 인수하기로 합의했다. 이번 인수로 CEVA Logistics의 북미 계약물류 사업 규모가 3배 가까이 커진다.","eSum":"CMA CGM agreed to acquire FedEx Supply Chain for $1.4 billion enterprise value, nearly tripling the North American contract logistics operations of its subsidiary CEVA Logistics.","kImp":"해운사들의 종합물류기업 전환 경쟁이 가속화되며 항공·육상 물류와의 통합이 더욱 심화될 전망이다.","eImp":"The deal accelerates carriers' shift into integrated logistics, deepening convergence with air and inland freight.","url":"https://maritime-executive.com/article/cma-cgm-grows-north-american-logistics-buying-fedex-supply-chain-for-1-4b"},{"code":"TOP","title":"관세發 컨테이너 운임 30% 폭등, 시장 혼란 가중","src":"TradeWinds","date":"2026-07-07","kSum":"미국의 관세 불확실성으로 컨테이너 스팟 운임이 근래 최대 폭인 30%가량 급등했다. 태평양 및 아시아-유럽 항로에서 피크시즌 할증료까지 겹치며 화주 부담이 커지고 있다.","eSum":"U.S. tariff turmoil has driven container spot freight rates up nearly 30% in a near-record surge, compounded by peak-season surcharges on transpacific and Asia-Europe routes.","kImp":"운임 변동성 확대로 화주들의 장기계약 선호 현상이 강화될 것으로 예상된다.","eImp":"Rate volatility is likely to push shippers toward longer-term contract coverage.","url":"https://www.tradewindsnews.com/containers/us-tariff-turmoil-spurs-near-record-30-jump-in-container-freight-rates/2-1-1826778"},{"code":"TOP","title":"Bruton, 12척 VLCC 프로젝트 두 개 상장사로 분할","src":"Splash247","date":"2026-07-08","kSum":"Tor Olav Troim 계열의 Bruton이 첫 초대형원유운반선(VLCC) 인도를 계기로 12척 규모 VLCC 프로그램을 두 개의 상장 법인으로 분할한다. 탱커 시장 호황 속 자본조달 전략의 일환이다.","eSum":"Tor Olav Troim-backed Bruton is splitting its 12-ship VLCC programme into two listed vehicles as its first supertanker enters service, part of a capital-raising strategy amid a strong tanker market.","kImp":"탱커 발주 붐 속에서 상장을 통한 자금조달 모델이 다른 선주사로 확산될 가능성이 있다.","eImp":"The listing-based financing model could spread to other owners amid the tanker newbuilding boom.","url":"https://splash247.com/bruton-to-split-12-ship-vlcc-play/"},{"code":"TOP","title":"HD현대, Schneider Electric과 해상 부유식 데이터센터 진출","src":"Splash247","date":"2026-07-08","kSum":"HD현대가 Schneider Electric과 협약을 맺고 해상 부유식 데이터센터 기술 개발에 나선다. AI 연산 수요 급증에 대응해 해양 인프라 신사업을 확대하는 행보다.","eSum":"HD Hyundai is entering the floating data centre market, signing an agreement with Schneider Electric to develop offshore digital infrastructure technology to meet surging AI computing demand.","kImp":"조선업계가 전통적 선박 건조를 넘어 해양 디지털 인프라로 사업영역을 넓히는 신호탄이 될 수 있다.","eImp":"This could signal shipbuilders expanding beyond traditional vessel construction into offshore digital infrastructure.","url":"https://splash247.com/hd-hyundai-and-schneider-electric-target-floating-data-centres/"},{"code":"TOP","title":"Heidmar, 네덜란드 선박관리사 Q-Shipping 인수","src":"Splash247","date":"2026-07-08","kSum":"나스닥 상장사 Heidmar Maritime이 네덜란드 선박관리·크루잉 업체 Q-Shipping을 인수했다. 선박관리 부문으로 사업영역을 확장하려는 전략적 행보다.","eSum":"Nasdaq-listed Heidmar Maritime has acquired Dutch shipmanagement and crewing outfit Q-Shipping, extending its reach into the ship management sector.","kImp":"상업관리 중심 기업의 기술관리 진출은 선박관리 시장 재편 신호로 읽힌다.","eImp":"A commercial manager's move into technical management signals further consolidation in the ship management market.","url":"https://splash247.com/heidmar-buys-dutch-ship-manager-q-shipping/"},{"code":"TOP","title":"MSC, Hengli重工에 LNG추진 2만TEU급 10척 추가발주","src":"Lloyd's List","date":"2026-07-07","kSum":"MSC가 중국 Hengli Heavy Industries에 LNG추진 2만TEU급 컨테이너선 10척을 추가 발주했다. 이로써 Hengli 조선소 발주잔량은 166척, 총 300만TEU에 육박하게 됐다.","eSum":"MSC has ordered 10 more LNG-fuelled, 20,000 TEU containerships at China's Hengli Heavy Industries, expanding its newbuilding pipeline there to 166 ships with capacity approaching 3 million TEU.","kImp":"중국 신흥 조선소의 초대형 컨테이너선 수주 경쟁력이 한국·일본 조선업계에 위협 요인으로 부상하고 있다.","eImp":"China's emerging yards' growing competitiveness in ultra-large boxship orders poses a rising threat to Korean and Japanese shipbuilders.","url":"https://www.lloydslist.com/LL1157712/MSC-boosts-record-orderbook-with-more-LNG-fuelled-boxships-at-Hengli-HI"},{"code":"TOP","title":"Fincantieri, 해저드론 등 수중기술 4개사 6.87억달러 인수","src":"MarineLink","date":"2026-07-08","kSum":"이탈리아 조선사 Fincantieri가 해저 드론, 수중통신 등 4개 기술기업 지분을 약 6억8700만달러에 인수하기로 합의했다. 상업·국방 양쪽에서 수중 인프라 보호 역량을 강화하려는 전략이다.","eSum":"Italian shipbuilder Fincantieri agreed to acquire majority stakes in four underwater technology companies for about $687 million, expanding capabilities in marine drones and underwater communications for both commercial and defense markets.","kImp":"해저 케이블·인프라 보호 수요가 커지며 조선업계의 방산·수중기술 투자가 확대될 전망이다.","eImp":"Rising demand for subsea infrastructure protection is likely to spur more shipbuilder investment in defense and underwater tech.","url":"https://www.marinelink.com/news/fincantieri-strikes-four-deals-m-540937"},{"code":"TOP","title":"이란-카타르 해상무역, 5개월만에 재개","src":"MarineLink","date":"2026-07-07","kSum":"이란과 카타르 간 해상무역이 약 5개월간의 중단 끝에 재개됐다. 이란 Dayyer항과 카타르 Al Ruwais항을 오가는 선박 운항이 양국 조율을 거쳐 다시 시작됐다.","eSum":"Maritime trade between Iran and Qatar has resumed after a roughly five-month suspension, with shipping between Iran's Dayyer port and Qatar's Al Ruwais port restarting following bilateral coordination.","kImp":"걸프 지역 교역 정상화의 신호이나 호르무즈 통항 안전 문제는 여전히 불씨로 남아있다.","eImp":"This signals gradual normalization of Gulf trade, though Hormuz transit safety remains an unresolved risk.","url":"https://www.marinelink.com/news/iranqatar-maritime-trade-resumes-540922"}]},{"code":"ACC","type":"accident","kTitle":"Section 2. 해상 사고·사상","eTitle":"Section 2. Accidents & Casualties","items":[{"code":"ACC","title":"카타르 LNG선 Al Rekayyat, 호르무즈서 피격 후 화재","src":"gCaptain","date":"2026-07-07","kSum":"카타르 LNG운반선 Al Rekayyat호가 호르무즈 해협 인근에서 발사체에 피격돼 기관실에 화재가 발생했다. 선원 전원은 안전하게 대피했으나 폭발 위험이 우려되는 상황이다.","eSum":"The Qatari LNG carrier Al Rekayyat was struck by a projectile near the Strait of Hormuz, sparking an engine room fire. All crew evacuated safely, but the vessel remained at risk of explosion.","kCause":"이란군 관련 세력의 의도적 공격으로 추정","eCause":"Suspected deliberate strike linked to Iranian forces","kLes":"고위험 해역 통항 시 LNG선의 화재 대응 및 신속 대피 프로토콜 점검이 필요하다.","eLes":"Fire response and rapid evacuation protocols for LNG carriers need review before transiting high-risk waters.","url":"https://gcaptain.com/lng-tanker-al-rekayyat-at-risk-of-exploding-after-attack-near-hormuz/"},{"code":"ACC","title":"파나마적 VLCC 'KIKU', 호르무즈서 두번째 피격","src":"gCaptain","date":"2026-06-26","kSum":"Qatar Energy 원유를 실은 파나마 국적 VLCC KIKU호가 호르무즈 해협 통과 중 미상 발사체에 브릿지를 피격당했다. 선원은 전원 무사했고 오염 피해는 없었다.","eSum":"The Panama-flagged VLCC KIKU, carrying Qatar Energy crude, was struck by an unidentified projectile while transiting the Strait of Hormuz, sustaining bridge damage. All crew were reported safe with no pollution.","kCause":"이란 측의 미승인 통항 선박에 대한 무력 대응 추정","eCause":"Suspected Iranian force response against unauthorized transit","kLes":"호르무즈 통항 허가 분쟁 지역에서는 사전 리스크 평가와 항로 대안 마련이 필수적이다.","eLes":"Advance risk assessment and route contingency planning are essential in contested Hormuz transit zones.","url":"https://gcaptain.com/second-tanker-struck-in-strait-of-hormuz-as-u-s-iran-shipping-crisis-deepens/"},{"code":"ACC","title":"컨테이너선 Ever Lovely, 호르무즈서 드론 피격","src":"gCaptain","date":"2026-06-25","kSum":"Evergreen 소속 싱가포르적 컨테이너선 Ever Lovely호가 호르무즈 해협 남쪽 항로를 빠져나가던 중 우현에 미상 발사체 피격을 당했다. 브릿지 구조물이 손상됐으나 인명피해는 없었다.","eSum":"The Singapore-flagged containership Ever Lovely, operated by Evergreen, was struck on her starboard side by an unknown projectile while exiting the Strait of Hormuz's southern corridor, damaging the bridge with no casualties.","kCause":"미국은 이란혁명수비대(IRGC-N) 드론 공격으로 추정","eCause":"U.S. attributed the strike to an Iranian IRGC-N drone","kLes":"'안전 항로'로 알려진 남부 회랑에서도 공격 위험이 상존함을 보여주는 사례로, 실시간 위협정보 공유가 중요하다.","eLes":"The incident shows even the 'safe' southern corridor carries risk, underscoring the need for real-time threat intelligence sharing.","url":"https://gcaptain.com/drone-strike-on-ever-lovely-exposes-the-fiction-of-a-free-strait/"},{"code":"ACC","title":"파라과이강 탱크바지 폭발, 근로자 5명 사망","src":"The Maritime Executive","date":"2026-07-05","kSum":"파라과이강 Asuncion 인근 정박지에서 정비 중이던 탱크바지 화물창에서 폭발이 발생해 작업자 5명이 숨졌다. 사고 바지선은 Lineas Panchita G 소속으로 알려졌다.","eSum":"A blast tore through a cargo tank of a barge undergoing maintenance on the Paraguay River near Asuncion, killing five workers. The barge belonged to Lineas Panchita G.","kCause":"정비 작업 중 화물창 내 가연성 증기 폭발 추정","eCause":"Suspected flammable vapor explosion inside the cargo tank during maintenance","kLes":"탱크 정비 전 가스프리 검사와 밀폐구역 안전절차 준수가 필수적이다.","eLes":"Gas-free certification and confined-space safety procedures must be strictly followed before tank maintenance.","url":"https://maritime-executive.com/article/tank-barge-explosion-kills-five-workers-on-paraguay-river"},{"code":"ACC","title":"이란, 상선 공격 재개…LNG선 겨냥 발포","src":"The Maritime Executive","date":"2026-07-06","kSum":"이란군이 호르무즈 해협 통항 지배권을 다시 장악하려는 시도로 상선에 대한 공격을 재개했다. Musandam 반도 인근에서 LNG선이 미상 발사체에 피격돼 화재가 발생했다.","eSum":"Iranian forces resumed attacks on merchant shipping in a renewed push to control the Strait of Hormuz, with an LNG carrier struck by an unknown projectile near the Musandam Peninsula, sparking a fire.","kCause":"이란군의 의도적 상선 공격으로 판단","eCause":"Assessed as a deliberate attack by Iranian forces","kLes":"공격 재개 국면에서는 민간 선사의 항로 재조정과 호송 체계 강화가 요구된다.","eLes":"Renewed attacks call for rerouting and stronger convoy escort arrangements for commercial shipping.","url":"https://maritime-executive.com/article/iran-resumes-attacks-on-merchant-shipping-with-strike-on-a-tanker"},{"code":"ACC","title":"베트남 앞바다 어선-화물선 충돌, 1명 사망","src":"Marine Insight","date":"2026-07-06","kSum":"베트남 중남부 해안에서 화물선 Viet Thuan 11-07호와 충돌한 어선이 침몰해 승선원 1명이 사망했다. 인근 어선들이 신속히 대응해 나머지 17명은 모두 구조됐다.","eSum":"A fishing boat sank after colliding with the cargo ship Viet Thuan 11-07 off Vietnam's south-central coast, killing one crew member. Nearby fishing boats quickly rescued the remaining 17 crew.","kCause":"소형 어선과 대형 화물선 간 견시 소홀 및 항법 오류 추정","eCause":"Suspected lookout failure and navigational error between the small fishing vessel and larger cargo ship","kLes":"연안 어로구역을 통과하는 대형선은 속력 제한과 강화된 견시가 필요하다.","eLes":"Large vessels transiting coastal fishing grounds need speed restrictions and enhanced lookout.","url":"https://www.marineinsight.com/fishing-boat-sinks-after-collision-with-cargo-ship-off-vietnam-one-dead/"},{"code":"ACC","title":"예멘 인근 벌크선 RPG 피격, 선원 2명 실종","src":"Seatrade Maritime News","date":"2026-07-08","kSum":"예멘 Al Hudaydah 서쪽 51해리 해상에서 벌크선이 로켓추진유탄(RPG) 5발 공격을 받아 선원 2명이 실종되고 2명이 부상했다. 소형 보트들의 접근도 함께 보고됐다.","eSum":"A bulker was attacked with five rocket-propelled grenades 51nm west of Al Hudaydah, Yemen, leaving two crew missing and two wounded, with multiple small craft also approaching the vessel.","kCause":"Houthi 계열 무장세력의 공격으로 추정","eCause":"Suspected armed attack linked to Houthi forces","kLes":"예멘 인근 항로 통과 시 소형정 접근에 대한 조기경보 체계와 시타델 대피훈련이 중요하다.","eLes":"Early-warning systems for small-craft approach and citadel drills are critical when transiting waters off Yemen.","url":"https://www.seatrade-maritime.com/security/two-seafarers-missing-two-wounded-in-second-red-sea-attack"},{"code":"ACC","title":"우크라이나, 72시간새 러시아 선박 21척 드론 공격","src":"Seatrade Maritime News","date":"2026-07-08","kSum":"우크라이나 무인체계군이 아조프해에서 활동 중인 러시아 국적 선박 21척을 72시간 동안 드론으로 공격했다. 크림반도 향 연료 공급을 차단하려는 작전의 일환이다.","eSum":"Ukraine's Unmanned Systems Forces struck 21 Russian-flagged vessels in the Sea of Azov within 72 hours using drones, part of an effort to choke off fuel supplies to Russian-occupied Crimea.","kCause":"우크라이나군의 의도적 표적 공격으로 확인","eCause":"Confirmed as a deliberate targeted campaign by Ukrainian forces","kLes":"교전해역 인근 상선은 브릿지·거주구 피격 위험 증가에 대비해 장갑 보강과 대피 동선을 재점검해야 한다.","eLes":"Ships near conflict zones should reinforce bridge/accommodation protection and review evacuation routes given rising strike risk.","url":"https://www.seatrade-maritime.com/security/ukraine-hits-21-russian-ships-within-72-hours"},{"code":"ACC","title":"러시아 드론 공격으로 벌크선 Victress 조리사 사망","src":"Seatrade Maritime News","date":"2026-06-22","kSum":"파나마 국적 2,300dwt 벌크선 Victress호가 드론 공격을 받아 대형 화재가 발생, 이집트 국적 조리사가 사망했다. 나머지 선원 8명은 우크라이나 해군에 의해 구조됐다.","eSum":"The Panama-flagged 2,300 dwt bulker Victress was struck by a drone causing a large fire; the ship's Egyptian cook was killed, while the remaining eight crew were rescued by Ukrainian naval forces.","kCause":"러시아-우크라이나 분쟁 관련 드론 공격으로 추정","eCause":"Suspected drone strike linked to the Russia-Ukraine conflict","kLes":"분쟁해역 항해 선사는 대체항로 검토와 선원 안전교육을 우선해야 한다.","eLes":"Operators transiting conflict waters should prioritize alternative routing and crew safety training.","url":"https://www.seatrade-maritime.com/security/seafarer-killed-in-russian-drone-strike-on-bulker"},{"code":"ACC","title":"싱가포르서 보급선 충돌 침몰, 선원 3명 사망","src":"SAFETY4SEA","date":"2026-06-12","kSum":"싱가포르 Pasir Panjang 터미널 인근에서 보급선이 상륙정과 충돌해 침몰, 승선원 3명이 사망했다. 경찰해안경비대가 수색 끝에 시신 3구를 수습했다.","eSum":"A supply boat sank off Pasir Panjang Terminal, Singapore, after colliding with a landing craft, killing three crew members whose bodies were recovered by the Police Coast Guard.","kCause":"소형선 간 항법 부주의로 인한 충돌 추정","eCause":"Suspected navigational lapse leading to collision between small vessels","kLes":"항만 근접해역에서는 소형선 간 VHF 교신과 항법등 점검이 특히 중요하다.","eLes":"VHF communication and navigation-light checks between small craft are especially critical in congested port approaches.","url":"https://safety4sea.com/supply-vessel-sinks-after-collision-in-singapore-three-crew-dead/"},{"code":"ACC","title":"뭄바이 앞바다 탱커 3척 표류, 1척 좌초","src":"SAFETY4SEA","date":"2026-07-07","kSum":"강풍과 악천후로 뭄바이 인근에 정박 중이던 탱커 3척이 닻줄이 끌리며 표류, 그 중 1척이 좌초했다. 인도 해안경비대가 출동해 나머지 선박들을 안전 확보했다.","eSum":"Strong winds caused three tankers anchored off Mumbai to drag anchor and drift, with one running aground, prompting the Indian Coast Guard to secure the remaining vessels.","kCause":"악천후 속 닻줄 끌림 및 부적절한 정박 간격 추정","eCause":"Suspected anchor dragging in severe weather combined with inadequate anchorage spacing","kLes":"악천후 예보 시 정박지 선박 간 안전거리 확보와 기관 대기상태 유지가 요구된다.","eLes":"Vessels at anchor should maintain adequate spacing and keep engines on standby ahead of forecast severe weather.","url":"https://safety4sea.com/indian-coast-guard-secures-drifting-tankers-off-mumbai-coast/"},{"code":"ACC","title":"오만 Limah 인근 탱커 피격, 화재 발생","src":"SAFETY4SEA","date":"2026-07-06","kSum":"오만 Limah 동쪽 약 8해리 해상에서 탱커가 미상 발사체에 피격돼 좌현에 화재가 발생했다. 인명피해와 오염 피해는 보고되지 않았다.","eSum":"A tanker was struck by an unknown projectile about 8nm east of Limah, Oman, causing a fire on the port side, with no casualties or pollution reported.","kCause":"호르무즈 인근 무력분쟁과 관련된 공격으로 추정","eCause":"Suspected attack linked to the ongoing conflict near the Strait of Hormuz","kLes":"고위험구역 통항선은 소화 장비 즉응태세와 UKMTO 경보 실시간 확인이 필수다.","eLes":"Vessels transiting high-risk zones must keep firefighting equipment ready and monitor UKMTO alerts in real time.","url":"https://safety4sea.com/ukmto-reports-attack-on-tanker-vessel-off-oman/"}]},{"code":"PSC","type":"news","kTitle":"Section 3. 항만국통제(PSC)","eTitle":"Section 3. Port State Control","items":[{"code":"PSC","title":"Panama 선적 억류 증가, 美 중국계 선사 집중 감시","src":"Splash247","date":"2026-07-08","kSum":"미국이 Panama 선적 선박에 대한 억류 건수 증가를 근거로 중국계 선사들을 집중 감시 대상으로 지목하고 있다. 최근 PSC 통계에서 Panama 기국 선박의 결함 적발과 억류가 늘면서 미 당국의 압박이 커지고 있다.","eSum":"The US is placing Chinese-linked shipowners under closer scrutiny after a rise in Port State Control detentions of Panama-flagged vessels. Washington argues the increased deficiencies point to compliance problems concentrated among Chinese-operated tonnage.","kImp":"Panama 기국 선박에 대한 미국의 감시 강화는 중국계 선사의 PSC 리스크 관리 필요성을 높인다.","eImp":"Heightened US scrutiny raises PSC compliance risk for Chinese-linked owners operating under the Panama flag.","url":"https://splash247.com/panama-flag-detentions-put-chinese-carriers-in-us-crosshairs/"},{"code":"PSC","title":"보고서: 예방 가능했던 PSC 억류 건수 증가","src":"The Maritime Executive","date":"2026-06-06","kSum":"최근 보고서에 따르면 전 세계 선단에서 사전에 예방 가능했던 PSC 억류 건수가 증가하고 있는 것으로 나타났다. 안전관리시스템 미비와 반복적 결함이 주요 원인으로 지적됐다.","eSum":"A new report finds that preventable Port State Control detentions are rising across the global fleet. Recurring deficiencies and weak safety management practices were identified as leading causes.","kImp":"선사들은 반복되는 결함을 줄이기 위한 예방 정비와 안전관리 강화가 시급하다.","eImp":"Owners need to strengthen preventive maintenance and safety management to curb recurring PSC deficiencies.","url":"https://maritime-executive.com/article/report-preventable-psc-detentions-are-increasing-across-the-fleet"},{"code":"PSC","title":"Panama, Paris MoU 화이트리스트 재등재","src":"MarineLink","date":"2026-07-02","kSum":"Panama 기국이 Paris MoU 화이트리스트에 재등재됐다. 이는 최근 억류 건수 증가에도 불구하고 전반적인 안전 이행 실적이 개선된 결과로 평가된다.","eSum":"Panama has been reinstated to the Paris MoU white list, reflecting improved overall safety performance despite a recent uptick in detentions. The move affects how Panama-flagged ships are targeted for future PSC inspections.","kImp":"화이트리스트 복귀로 Panama 선적 선박의 PSC 검사 대상 선정 위험이 낮아질 전망이다.","eImp":"White-list reinstatement should reduce the PSC inspection targeting risk for Panama-flagged tonnage.","url":"https://www.marinelink.com/news/panama-reinstated-paris-mou-white-list-540883"},{"code":"PSC","title":"프랑스 해군, 러시아 그림자 선단 연계 유조선 나포","src":"MarineLink","date":"2026-06-25","kSum":"프랑스 해군이 러시아 그림자 선단과 연계된 것으로 의심되는 유조선을 나포했다. 이번 조치는 프랑스가 추진 중인 대러 제재 이행 단속의 일환이다.","eSum":"The French Navy seized a tanker suspected of belonging to Russia's shadow fleet as part of Paris's expanding sanctions-enforcement campaign. The vessel was intercepted while transiting waters under French jurisdiction.","kImp":"유럽 해군의 그림자 선단 단속 강화는 관련 선박의 항해 및 보험 리스크를 높인다.","eImp":"Stepped-up European naval enforcement raises navigational and insurance risk for shadow-fleet-linked tankers.","url":"https://www.marinelink.com/news/french-navy-seizes-tanker-linked-russian-540663"},{"code":"PSC","title":"영국, 러시아 그림자 선단 유조선 인도인 선장 기소","src":"gCaptain","date":"2026-06-15","kSum":"영국 당국이 러시아 그림자 선단 소속 유조선의 인도 국적 선장을 기소했다. 해당 사건은 제재 회피 및 불법 운항 혐의와 관련이 있다.","eSum":"UK authorities have filed charges against the Indian captain of a tanker linked to Russia's shadow fleet. The case centers on allegations tied to sanctions evasion and unsafe operation.","kImp":"선장 개인에 대한 형사 기소는 그림자 선단 승선을 꺼리게 하는 억지 효과를 낼 수 있다.","eImp":"Criminal charges against individual masters could deter seafarers from crewing shadow-fleet tankers.","url":"https://gcaptain.com/uk-charges-indian-captain-of-russian-shadow-fleet-tanker/"},{"code":"PSC","title":"FMC 위원장, 중국의 Panama 선적 선박 검사 무기화 우려","src":"The Maritime Executive","date":"2026-07-08","kSum":"미 연방해사위원회(FMC) 위원장이 중국이 Panama 선적 선박에 대한 검사를 정치적 도구로 활용하고 있다는 우려를 제기했다. 이는 미중 해운 갈등이 규제 영역으로 확산되고 있음을 보여준다.","eSum":"The FMC chair voiced concern that China is using inspections of Panama-flagged vessels as a political tool amid rising US-China maritime tensions. The remarks add a regulatory dimension to the broader trade dispute.","kImp":"미중 갈등이 PSC 검사 관행에까지 번지면서 관련 선사들의 불확실성이 커지고 있다.","eImp":"The spillover of US-China tensions into PSC inspection practice adds regulatory uncertainty for affected carriers.","url":"https://maritime-executive.com/article/fmc-chair-concerned-china-is-weaponizing-inspections-of-panama-flag-ships"},{"code":"PSC","title":"중국, Panama 선적 선박 표적 검사 의혹 부인","src":"The Maritime Executive","date":"2026-06-24","kSum":"중국 당국은 Panama 선적 선박을 표적으로 검사를 강화했다는 주장을 부인했다. 중국측은 통상적인 항만국통제 절차에 따른 것이라고 해명했다.","eSum":"Chinese officials denied allegations that they are singling out Panama-flagged vessels for stepped-up inspections, insisting the checks follow routine Port State Control procedures.","kImp":"양측의 공방은 국제 PSC 체제의 정치적 중립성에 대한 신뢰 문제로 이어질 수 있다.","eImp":"The dispute risks undermining confidence in the political neutrality of the international PSC regime.","url":"https://maritime-executive.com/article/china-denies-targeting-panama-flagged-ships-for-increased-inspections"},{"code":"PSC","title":"Paris MoU 2025 보고서, 억류율 상승은 광범위한 컴플라이언스 압박","src":"SAFETY4SEA","date":"2026-07-02","kSum":"Paris MoU 2025년 연례 보고서에 따르면 억류율 상승은 개별 선박의 결함을 넘어 광범위한 컴플라이언스 압박을 반영한다는 분석이 나왔다. 안전관리 체계 전반의 구조적 문제가 지적됐다.","eSum":"Paris MoU's 2025 annual report shows higher detention rates that analysts say reflect broader compliance pressures rather than isolated vessel deficiencies. The findings point to systemic weaknesses in safety management across the fleet.","kImp":"선사들은 개별 결함 대응을 넘어 시스템 차원의 컴플라이언스 개선이 필요하다.","eImp":"Owners must address compliance at a systemic level, not just fix individual deficiencies, to curb rising detention rates.","url":"https://safety4sea.com/cm-paris-mou-2025-higher-detention-rates-point-to-broader-compliance-pressures-beyond-individual-psc-deficiencies/"},{"code":"PSC","title":"프랑스, 러시아 그림자 선단 유조선 추가 나포","src":"gCaptain","date":"2026-06-01","kSum":"프랑스가 Macron 대통령의 제재 확대 기조 속에서 또 다른 러시아 그림자 선단 유조선을 나포했다. 이는 프랑스 해역 내 그림자 선단 단속이 계속되고 있음을 보여준다.","eSum":"France intercepted another tanker believed to belong to Russia's shadow fleet, part of President Macron's expanding sanctions crackdown. The seizure underscores continued enforcement action in French waters.","kImp":"반복되는 나포 조치는 그림자 선단의 유럽 해역 통항 리스크를 계속 높이고 있다.","eImp":"Repeated seizures continue to raise transit risk for shadow-fleet tankers moving through European waters.","url":"https://gcaptain.com/france-intercepts-another-russian-shadow-fleet-tanker-as-macron-expands-sanctions-crackdown/"}]},{"code":"PCTC","type":"news","kTitle":"Section 4. 자동차운반선(PCTC)","eTitle":"Section 4. Car Carriers (PCTC)","items":[{"code":"PCTC","title":"Seaspan, 첫 10,800CEU급 LNG 이중연료 자동차운반선 인도","src":"Baird Maritime","date":"2026-07-01","kSum":"캐나다 Seaspan이 CSSC 산하 Guangzhou Shipyard International에서 건조한 10,800CEU급 LNG 이중연료 자동차운반선 'Glovis Lander'를 인도받았다. 현대글로비스에 장기 용선돼 한국-동남아·북미·유럽 노선에 투입된다.","eSum":"Canada's Seaspan Corporation took delivery of Glovis Lander, its first 10,800-CEU LNG dual-fuel PCTC built by CSSC's Guangzhou Shipyard International, chartered long-term to Hyundai Glovis for Korea-Southeast Asia, North America and Europe routes.","kImp":"컨테이너선 중심이던 Seaspan이 자동차운반선 시장까지 사업을 넓히고 있다.","eImp":"Seaspan, traditionally a container ship lessor, is expanding into the car carrier segment.","url":"https://www.bairdmaritime.com/shipping/dry-cargo/dry-cargo-vessel-news-roundup-july-1-china-built-car-carriers-uk-owners-new-shortsea-ship-and-more"},{"code":"PCTC","title":"Grimaldi, 12번째 암모니아 대응 자동차운반선 인도","src":"Baird Maritime","date":"2026-07-01","kSum":"Grimaldi Group이 암모니아 대응 설계를 적용한 12번째 자동차운반선을 인도받았다. 이는 그룹의 친환경 선대 전환 프로그램이 순조롭게 진행되고 있음을 보여준다.","eSum":"Grimaldi Group has taken delivery of its 12th ammonia-ready pure car and truck carrier, marking steady progress in the Italian group's green newbuilding programme.","kImp":"암모니아 대응 선박의 잇단 인도는 PCTC 시장의 탈탄소 경쟁을 가속화하고 있다.","eImp":"The steady stream of ammonia-ready deliveries is intensifying the decarbonisation race within the PCTC sector.","url":"https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/grimaldi-takes-delivery-of-12th-ammonia-ready-car-carrier"},{"code":"PCTC","title":"COSCO Shipping, LNG 자동차운반선 시리즈 마지막 선박 인도","src":"Baird Maritime","date":"2026-06-22","kSum":"COSCO Shipping이 LNG 이중연료 자동차운반선 시리즈의 마지막 선박을 인도받으며 해당 뉴빌딩 프로그램을 마무리했다. 이번 인도로 COSCO의 친환경 PCTC 선단이 확충됐다.","eSum":"COSCO Shipping has taken delivery of the final vessel in its LNG dual-fuel car carrier newbuilding series, completing the programme and expanding the group's green PCTC fleet.","kImp":"COSCO의 LNG PCTC 시리즈 완결은 중국계 선사의 완성차 수송 경쟁력 강화로 이어질 전망이다.","eImp":"Completion of COSCO's LNG PCTC series should strengthen the competitiveness of Chinese carriers in finished-vehicle transport.","url":"https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/cosco-shipping-takes-delivery-of-final-lng-fuelled-car-carrier-in-series"},{"code":"PCTC","title":"Polaris, Global Car Carriers로부터 용선 선박 추가","src":"Splash247","date":"2026-07-07","kSum":"Polaris Shipping이 Global Car Carriers로부터 용선한 선박을 추가하며 자동차운반선 사업을 확장하고 있다. 이는 PCTC 수요 강세에 대응한 선복 확보 움직임으로 풀이된다.","eSum":"Polaris Shipping is expanding its car-carrier operations by adding chartered-in tonnage from Global Car Carriers, a move seen as securing capacity amid strong PCTC demand.","kImp":"선사들의 용선 확대는 여전히 타이트한 PCTC 시장 상황을 반영한다.","eImp":"The chartering move reflects still-tight conditions in the PCTC market as owners scramble to secure tonnage.","url":"https://splash247.com/polaris-adds-tonnage-from-global-car-carriers/"},{"code":"PCTC","title":"HD현대, 원자력 추진 자동차운반선 개념설계 AiP 획득","src":"Splash247","date":"2026-06-05","kSum":"HD현대중공업·한국조선해양이 소형모듈원자로(SMR) 추진 대형 자동차운반선(PCTC) 개념설계에 대해 Lloyd's Register로부터 기본승인(AiP)을 받았다. 현대글로비스가 운항 계획을, 한국원자력연구원이 기술 검토를 맡았다.","eSum":"HD Hyundai's shipbuilding affiliates received approval in principle from Lloyd's Register for a large PCTC concept design applying a molten salt small modular reactor, with Hyundai Glovis providing operational input and KAERI reviewing the technology.","kImp":"원자력 추진 기술이 컨테이너선을 넘어 자동차운반선까지 확대되고 있다.","eImp":"Nuclear propulsion technology is expanding beyond container ships into the car carrier segment.","url":"https://splash247.com/hd-hyundai-takes-nuclear-ship-ambitions-into-car-carrier-sector/"},{"code":"PCTC","title":"中 자동차 수출 폭증에 컨테이너선까지 車 수송 동원","src":"Splash247","date":"2026-06-11","kSum":"중국의 5월 승용차 수출이 전년 대비 73% 급증하며 자동차운반선 용선료가 사상 최고치로 치솟았다. 로로 선복 부족으로 중국 완성차업체들이 컨테이너선으로 차량을 운송하는 사례가 늘고 있다.","eSum":"China's passenger car exports surged 73% year-on-year in May, driving car carrier charter rates to fresh highs and forcing Chinese OEMs to increasingly divert vehicle volumes onto containerships as ro-ro capacity fails to keep pace.","kImp":"자동차운반선 부족 현상이 컨테이너선 시장까지 파급되고 있다.","eImp":"The PCTC capacity crunch is spilling over into the container shipping market.","url":"https://splash247.com/containerlines-cash-in-on-chinese-car-export-boom/"},{"code":"PCTC","title":"K Line, LNG 이중연료 자동차운반선 4척 발주","src":"Container News","date":"2026-06-05","kSum":"Kawasaki Kisen Kaisha(K Line)가 유럽 쇼트시 사업 강화를 위해 LNG 이중연료 자동차운반선 4척의 건조 계약을 체결했다. China Merchants Jinling 조선소에서 건조되며 각 선박은 약 1,380대의 차량을 실을 수 있다.","eSum":"Kawasaki Kisen Kaisha (K Line) has signed shipbuilding contracts for four LNG dual-fuel car carriers to strengthen its European short-sea operations, to be built by China Merchants Jinling Shipyard with a capacity of about 1,380 vehicles each.","kImp":"유럽 역내 단거리 자동차 운송에서도 LNG 이중연료 선박 도입이 확산하고 있다.","eImp":"LNG dual-fuel propulsion is spreading even into short-sea European car carrier operations.","url":"https://container-news.com/k-line-orders-four-lng-fuelled-car-carriers/"},{"code":"PCTC","title":"Grimaldi, 암모니아 대응 PCTC 'Grande Istanbul' 공개","src":"Container News","date":"2026-07-06","kSum":"Grimaldi Group이 튀르키예 Kocaeli Autoport에서 열린 기념식에서 최신 자동차운반선 'Grande Istanbul'을 공개했다. 최대 9,241CEU를 적재할 수 있으며 이전 세대 대비 화물 단위당 이산화탄소 배출을 최대 50% 줄일 수 있다.","eSum":"The Grimaldi Group presented its latest PCTC, Grande Istanbul, in a ceremony at Autoport in Kocaeli, Turkiye, one of 17 next-generation ammonia-ready carriers with a capacity of up to 9,241 CEUs that can cut CO2 emissions per cargo unit by up to 50%.","kImp":"튀르키예를 거점으로 한 유럽-지중해 자동차 물류망이 계속 강화되고 있다.","eImp":"Grimaldi continues to reinforce its Turkiye-based Europe-Mediterranean automotive logistics network.","url":"https://container-news.com/grimaldi-presents-ammonia-ready-car-carrier-grande-istanbul/"},{"code":"PCTC","title":"Sallaum Lines, Xiamen조선에 8,600CEU급 신형 PCTC 2+2척 발주","src":"The Maritime Executive","date":"2026-06-17","kSum":"Sallaum Lines가 Xiamen Shipbuilding Industry와 8,600CEU급 차세대 PCTC 2+2척 건조 계약을 체결했다. 이는 회사 역사상 최대 규모 선박으로, 이중연료 엔진과 암모니아 대응 설계를 갖췄다.","eSum":"Sallaum Lines has ordered the two largest vessels in its history, signing a contract with Xiamen Shipbuilding Industry for 2+2 next-generation 8,600-CEU PCTCs featuring dual-fuel engines and an ammonia-ready design.","kImp":"중견 로로 선사들도 초대형·차세대 친환경 PCTC 확보 경쟁에 뛰어들고 있다.","eImp":"Mid-sized ro-ro operators are also racing to secure larger, next-generation eco-friendly PCTCs.","url":"https://maritime-executive.com/corporate/sallaum-lines-orders-two-next-generation-8-600-ceu-car-carriers"},{"code":"PCTC","title":"Höegh Sunrise, Port Freeport 첫 기항…Mitsubishi 물류망 확대","src":"Automotive Logistics","date":"2026-07-01","kSum":"Höegh Autoliners의 Aurora급 PCTC 'Höegh Sunrise'가 미국 텍사스 Port Freeport에 첫 기항하며 Mitsubishi 차량을 하역했다. Mitsubishi Motors North America와 Amports, Port Freeport 간 협력을 공식화하는 행사와 시기가 맞물렸다.","eSum":"Hoegh Autoliners' Aurora-class PCTC Hoegh Sunrise made its inaugural call at Port Freeport, Texas, carrying Mitsubishi vehicles, coinciding with a ribbon-cutting marking Mitsubishi Motors North America's new collaboration with Amports and the port.","kImp":"완성차업체들이 미국 내 신규 항만 거점을 통해 물류망을 다변화하고 있다.","eImp":"Automakers are diversifying their US distribution networks through new port gateways.","url":"https://www.automotivelogistics.media/vehicle-logistics/mitsubishi-adds-texas-port-freeport-to-its-expanding-us-distribution-networknbsp/2696261"}]},{"code":"WW","type":"news","kTitle":"Section 5. Wallenius Wilhelmsen","eTitle":"Section 5. Wallenius Wilhelmsen","items":[{"code":"WW","title":"Wallenius Wilhelmsen, 유럽 완성차업체와 4.2억달러 계약 조기 3년 연장","src":"Splash247","date":"2026-07-03","kSum":"Wallenius Wilhelmsen이 유럽 대형 완성차업체와의 해상운송 계약을 조기에 3년 연장했다. 2028년 중반부터 2031년 중반까지 약 4억 2천만 달러 규모의 신규 계약이 추가된다.","eSum":"Wallenius Wilhelmsen agreed an early three-year extension of its shipping contract with a major European automotive manufacturer, adding an estimated USD 420m in value from mid-2028 to mid-2031.","kImp":"자동차 해상운송 계약 백로그를 선제적으로 확보해 향후 매출 안정성을 강화한다.","eImp":"The early renewal locks in long-term revenue visibility for the vehicle shipping business.","url":"https://splash247.com/wallenius-wilhelmsen-adds-420m-to-car-shipping-contract/"},{"code":"WW","title":"WW 선박 MS Toledo, Galveston항 신규 화물 부두 첫 기항","src":"Baird Maritime","date":"2026-07-02","kSum":"미국 텍사스 Galveston항이 1억 600만 달러를 투입한 신규 화물부두를 개장했고, Wallenius Wilhelmsen의 656피트급 선박 MS Toledo가 첫 기항 선박이 됐다. 브라질·극동산 중장비를 하역하고 브라질·호주행 화물을 선적했다.","eSum":"Port of Galveston's new USD 106m cargo berth opened July 2 with Wallenius Wilhelmsen's 656-foot MS Toledo as the first caller, discharging construction equipment from Brazil and the Far East and loading outbound cargo to Brazil and Australia.","kImp":"미국 걸프만 항만 인프라 확충으로 하이앤헤비 화물 처리 능력이 확대된다.","eImp":"Expanded US Gulf port infrastructure boosts High & Heavy cargo handling capacity.","url":"https://www.bairdmaritime.com/shipping/ports/port-of-galveston-opens-new-cargo-berth-with-first-vessel-arrival"},{"code":"WW","title":"WW 선박 'Morning Concert', 호르무즈 해협 안전 탈출","src":"MarketScreener","date":"2026-06-30","kSum":"Wallenius Wilhelmsen 소속 PCTC 'Morning Concert'(6,515 CEU)가 2월 중동 분쟁 발발 이후 페르시아만에 머물다 6월 30일 오만 해역을 통해 호르무즈 해협을 안전하게 빠져나왔다.","eSum":"Wallenius Wilhelmsen's PCTC Morning Concert (6,515 CEU), stranded in the Persian Gulf since the Middle East conflict began in February, safely exited the Strait of Hormuz through Omani waters on 30 June.","kImp":"장기간 발이 묶였던 선박의 안전한 탈출로 중동 항로 리스크가 부분적으로 완화됐다.","eImp":"The vessel's safe exit partially eases risk on the Middle East trade route after a prolonged standoff.","url":"https://www.marketscreener.com/news/wallenius-wilhelmsen-s-morning-concert-safely-exits-the-strait-of-hormuz-ce7f5fdfd08ff62c"},{"code":"WW","title":"WW, 1분기 순이익 소폭 증가…High & Heavy 전망은 혼조","src":"Project Cargo Journal","date":"2026-05-06","kSum":"Wallenius Wilhelmsen의 2026년 1분기 순이익이 1억 7,700만 달러로 소폭 늘었고 조정 EBITDA는 3억 8,900만 달러를 기록했다. 중동 분쟁과 금리 리스크로 High & Heavy 부문 전망은 여전히 불투명하다.","eSum":"Wallenius Wilhelmsen's Q1 2026 net profit edged up to USD 177m with adjusted EBITDA of USD 389m, while the High & Heavy segment outlook remains mixed amid Middle East tensions and interest-rate risk.","kImp":"해운 부문 견조한 수요가 High & Heavy 부진을 상쇄하는 구조가 지속되고 있다.","eImp":"Resilient shipping demand continues to offset softness in the High & Heavy segment.","url":"https://www.projectcargojournal.com/business/2026/05/06/wallenius-wilhelmsen-net-profit-edges-up-high-and-heavy-outlook-remains-mixed-in-q1/"},{"code":"WW","title":"WW, 2026년 완전 디지털 정기주주총회서 모든 안건 승인","src":"TipRanks","date":"2026-04-29","kSum":"Wallenius Wilhelmsen이 4월 29일 완전 디지털 방식으로 진행한 2026년 정기주주총회에서 상정된 모든 안건이 주주 승인을 받았다.","eSum":"Shareholders approved all agenda items at Wallenius Wilhelmsen's fully digital 2026 Annual General Meeting held on 29 April.","kImp":"이사회 및 보수 정책 등 지배구조 안건이 안정적으로 통과돼 경영 연속성이 확인됐다.","eImp":"Smooth approval of governance items confirms management continuity.","url":"https://www.tipranks.com/news/company-announcements/wallenius-wilhelmsen-shareholders-approve-all-proposals-at-2026-virtual-agm"},{"code":"WW","title":"WW, 현대차그룹과 EUKOR 옵션 조건 개정해 부채 부담 완화","src":"MarketScreener","date":"2026-04-07","kSum":"Wallenius Wilhelmsen과 현대차그룹(HMG)이 HMG가 보유한 EUKOR 지분 20%에 대한 풋·콜옵션 행사 조건을 개정했다. 2029년까지 이어지는 해상운송계약(OCC)의 물량 약정이 유지되는 한 옵션을 행사할 수 없도록 해 8억 9,700만 달러 규모 부채 부담을 낮췄다.","eSum":"Wallenius Wilhelmsen and Hyundai Motor Group revised the put/call option terms on HMG's 20% EUKOR stake, linking exercisability to volume commitments under their Ocean Carrier Contract through 2029, reducing the near-term USD 897m liability.","kImp":"회계상 부채가 유동에서 비유동으로 재분류되며 단기 재무 부담이 완화된다.","eImp":"Reclassifying the liability from current to non-current eases near-term balance-sheet pressure.","url":"https://www.marketscreener.com/news/wallenius-wilhelmsen-flags-liability-reduction-linked-to-eukor-ownership-ce7e51d3db81f721"},{"code":"WW","title":"WW 2025년 실적 후속 분석…High & Heavy 물동량 부진 지속","src":"Heavy Lift & Project Forwarding International","date":"2026-03-23","kSum":"2025년 연간 실적 발표 후속 분석에서 High & Heavy(중장비) 물동량이 건설경기 부진으로 전년 대비 감소한 것으로 나타났다. 다만 데이터센터·국방·에너지 인프라 투자 확대가 향후 반등 요인으로 지목됐다.","eSum":"A follow-up review of 2025 results showed High & Heavy equipment volumes declined year-on-year amid weak construction activity, though rising data-centre, defence and energy infrastructure investment could drive a rebound.","kImp":"건설경기 회복 지연이 High & Heavy 부문의 최대 리스크로 지목된다.","eImp":"A delayed construction recovery remains the key risk for the High & Heavy segment.","url":"https://www.heavyliftpfi.com/shipping/2026/03/23/wallenius-wilhelmsen-reports-steady-2025-high-and-heavy-volumes-lag/"},{"code":"WW","title":"WW, '견조한 실적·강화된 입지' 2025년 연차보고서 발표","src":"Wallenius Wilhelmsen","date":"2026-03-19","kSum":"Wallenius Wilhelmsen이 2025년 연차보고서를 발표했다. 매출 52억 4천만 달러, 조정 EBITDA 18억 1,100만 달러, 순이익 11억 400만 달러를 기록했으며 계약 잔고는 100억 달러를 넘어섰다.","eSum":"Wallenius Wilhelmsen published its 2025 annual report, reporting revenue of USD 5,240m, adjusted EBITDA of USD 1,811m, net profit of USD 1,104m, and a contract backlog exceeding USD 10bn.","kImp":"대규모 계약 잔고 확보로 향후 실적 가시성이 높아졌다.","eImp":"The large contract backlog improves earnings visibility going forward.","url":"https://www.walleniuswilhelmsen.com/news/wallenius-wilhelmsen-2025-annual-report-steady-delivery-stronger-position"},{"code":"WW","title":"Equinor, WW에 2년간 바이오메탄올 연료 공급","src":"MarineLink","date":"2026-03-11","kSum":"Equinor가 Wallenius Wilhelmsen과 2년 기간의 바이오메탄올 벙커 공급 계약을 체결했다. Zeebrugge·Antwerp항에서 공급되며 2026년 하반기부터 신규 이중연료 메탄올 선박에 사용된다. ISCC EU 인증을 받아 CO2를 95% 감축한다.","eSum":"Equinor signed a two-year bio-methanol bunker fuel supply agreement with Wallenius Wilhelmsen, with deliveries at Zeebrugge and Antwerp from late 2026 for its dual-fuel methanol newbuilds, cutting CO2 emissions by 95% under ISCC EU certification.","kImp":"2027년 넷제로 파일럿 서비스 실현을 위한 핵심 연료 조달 기반이 마련됐다.","eImp":"Secures a key fuel supply pillar for the planned 2027 net-zero pilot service.","url":"https://www.marinelink.com/news/equinor-supply-biomethanol-wallenius-536826"},{"code":"WW","title":"WW, 중동 전쟁으로 해당 지역 운항 잠정 중단","src":"Wallenius Wilhelmsen","date":"2026-03-04","kSum":"Wallenius Wilhelmsen이 중동 지역 전쟁으로 인해 해당 지역으로의 모든 운항을 잠정 중단한다고 발표했다. 선원과 선박, 화물의 안전을 최우선으로 하며 상황을 지속적으로 평가하고 있다고 밝혔다.","eSum":"Wallenius Wilhelmsen announced it has temporarily suspended all sailings to the Middle East due to the war in the region, prioritising the safety of crew, vessels and cargo while continuously assessing the situation.","kImp":"중동 항로 중단으로 대체 항로 확보 및 운임 비용 상승 압력이 커진다.","eImp":"The route suspension increases pressure to secure alternative routings and raises cost exposure.","url":"https://www.walleniuswilhelmsen.com/news/wallenius-wilhelmsen-suspends-operations-in-the-middle-east"},{"code":"WW","title":"WW, 글로벌 자동차 유통사와 1.9억달러 계약 갱신","src":"Splash247","date":"2026-03-03","kSum":"Wallenius Wilhelmsen이 글로벌 자동차 유통업체와 2년 기간의 계약을 갱신했다. 순운임 기준 약 1억 9천만 달러 규모이며 1년 상호 연장 옵션과 복수연료 할증료가 포함됐다.","eSum":"Wallenius Wilhelmsen renewed a two-year contract with a global automotive distributor worth an estimated USD 190m in net freight value, including a one-year mutual extension option and a multi-fuel surcharge.","kImp":"연이은 계약 갱신으로 2026년 초 견조한 수주 모멘텀이 이어지고 있다.","eImp":"The renewal extends a string of strong contract wins early in 2026.","url":"https://splash247.com/wallenius-wilhelmsen-seals-190m-contract-renewal/"},{"code":"WW","title":"Oceanbird, 윙세일 첫 상업 주문 확보","src":"Ship & Bunker","date":"2026-02-25","kSum":"Alfa Laval과 Wallenius Lines의 합작사 Oceanbird가 Wing 560 윙세일 2기에 대한 첫 상업 주문을 수주했다. 2027년 초 유럽에서 기존 선박에 개조 설치될 예정이며 최대 10%의 연료 절감이 기대된다.","eSum":"Oceanbird, the Alfa Laval-Wallenius Lines joint venture, secured its first commercial order for two Wing 560 wind-propulsion sails, to be retrofitted on an existing vessel in Europe in early 2027, offering up to 10% fuel savings.","kImp":"풍력 추진 기술의 상업화 단계 진입으로 탈탄소 솔루션 사업이 본궤도에 올랐다.","eImp":"The first commercial order marks wind propulsion tech entering commercial-scale deployment.","url":"https://shipandbunker.com/news/world/527518-oceanbird-secures-first-commercial-wind-propulsion-system-order"},{"code":"WW","title":"WW, 2025년 견조한 실적 발표…High & Heavy 시장은 위축","src":"WorldCargo News","date":"2026-02-11","kSum":"Wallenius Wilhelmsen이 2025년 연간 매출 52억 4천만 달러, 조정 EBITDA 18억 1,100만 달러, 순이익 11억 400만 달러의 견조한 실적을 발표했다. 다만 High & Heavy(중장비) 시장 활동은 위축됐다고 밝혔다.","eSum":"Wallenius Wilhelmsen posted steady 2025 results with revenue of USD 5,240m, adjusted EBITDA of USD 1,811m and net profit of USD 1,104m, while High & Heavy market activity declined.","kImp":"해운 부문의 견조한 실적이 High & Heavy 부진에도 전체 그룹 실적을 지탱했다.","eImp":"Solid shipping results offset High & Heavy weakness to sustain overall group performance.","url":"https://www.worldcargonews.com/business/2026/02/wallenius-wilhelmsen-posts-steady-2025-results/"},{"code":"WW","title":"WW, 예테보리 로로 터미널(GIART) 운영 개시","src":"Project Cargo Journal","date":"2026-02-02","kSum":"Wallenius Wilhelmsen이 스웨덴 Gothenburg International Auto & RoRo Terminal(GIART) 운영을 12년 계약으로 공식 개시했다. 터미널 현대화에 610만 유로를 투자한다.","eSum":"Wallenius Wilhelmsen officially began operating the Gothenburg International Auto & RoRo Terminal (GIART) in Sweden under a 12-year concession, investing EUR 6.1m to modernise the facility.","kImp":"북유럽 최대 자동차 처리항 운영권 확보로 유럽 물류 네트워크가 강화된다.","eImp":"Operating Scandinavia's largest vehicle port strengthens the European logistics network.","url":"https://www.projectcargojournal.com/ports-and-terminals/2026/02/02/wallenius-wilhelmsen-begins-operations-at-gothenburg-roro-terminal/"},{"code":"WW","title":"WW, 자본시장의날서 '두 자릿수 물류 성장·넷제로 해운' 전략 발표","src":"GuruFocus","date":"2026-01-20","kSum":"Wallenius Wilhelmsen이 1월 20일 자본시장의날(CMD)을 열고 두 자릿수 물류 성장과 2040년 넷제로 해운을 핵심 전략으로 제시했다. Shaper급 신조선 14척 투입과 터미널 M&A를 통한 성장을 강조했다.","eSum":"Wallenius Wilhelmsen held its Capital Markets Day on 20 January, outlining double-digit logistics growth and net-zero shipping by 2040 as core strategy, backed by 14 Shaper-class newbuilds and terminal M&A.","kImp":"물류 사업 확장과 탈탄소 투자를 병행하는 중장기 성장 전략이 구체화됐다.","eImp":"The strategy concretises parallel investment in logistics expansion and decarbonisation.","url":"https://www.gurufocus.com/news/2348901/wallenius-wilhelmsen-asa-capital-markets-day-transcript"},{"code":"WW","title":"WW, 아시아 완성차·중장비업체와 1.3억달러 계약 체결","src":"MarketScreener","date":"2026-01-07","kSum":"Wallenius Wilhelmsen이 아시아 주요 자동차·중장비 제조업체와 1년 기간의 해상운송 계약을 새로 체결했다. 예상 매출 규모는 약 1억 3천만 달러다.","eSum":"Wallenius Wilhelmsen entered a new one-year shipping contract with a major Asian vehicle and heavy-equipment manufacturer, expected to generate roughly USD 130m in revenue.","kImp":"아시아 지역 성장 전략에 따른 신규 고객 기반 확대가 확인됐다.","eImp":"The deal confirms expanding customer reach as part of the company's Asia growth ambitions.","url":"https://www.marketscreener.com/news/wallenius-wilhelmsen-enters-new-contract-with-major-asian-vehicle-and-heavy-equipment-manufacturer-ce7e59dfd08bf321"}]},{"code":"EE","type":"news","kTitle":"Section 6. 에너지효율·탈탄소","eTitle":"Section 6. Energy Efficiency & Decarbonization","items":[{"code":"EE","title":"Peninsula-Itochu, 유럽 암모니아 벙커링 합작사 출범","src":"Splash247","date":"2026-07-08","kSum":"해상연료 공급업체 Peninsula와 일본 Itochu상사가 유럽 및 지중해 주요 항만에서 암모니아 벙커링 사업을 전개하기 위한 합작법인을 설립했다. 양사는 암모니아 연료 공급망 구축을 통해 탈탄소 선박 확산에 대응한다는 계획이다.","eSum":"Marine fuel supplier Peninsula and Japan's Itochu have launched a joint venture to develop ammonia bunkering infrastructure across key European and Mediterranean ports, building fuel supply chains to serve the growing dual-fuel fleet.","kImp":"암모니아 벙커링 인프라가 유럽으로 확장되며 대체연료 공급망 경쟁이 본격화되고 있다.","eImp":"The move signals accelerating build-out of ammonia bunkering infrastructure as fuel suppliers race to serve the dual-fuel fleet.","url":"https://splash247.com/peninsula-and-itochu-launch-ammonia-bunkering-venture/"},{"code":"EE","title":"상하이, 친환경 해상연료 인증센터 출범","src":"Splash247","date":"2026-06-30","kSum":"상하이가 친환경 해상연료 인증센터를 출범시켜 메탄올, 바이오연료 등 대체연료의 추적성과 지속가능성 검증을 지원한다. 위조 인증서와 부실 감독에 대한 업계 우려가 커지는 가운데 나온 조치다.","eSum":"Shanghai launched a green marine fuel certification centre aimed at supporting traceability and sustainability verification for alternative fuels such as green methanol and biofuels, amid growing concern over fuel fraud and weak oversight.","kImp":"연료 인증 신뢰성 확보는 바이오연료 확산의 핵심 과제로 부상하고 있다.","eImp":"Robust fuel certification is becoming a critical bottleneck as biofuel adoption scales up globally.","url":"https://splash247.com/shanghai-launches-green-marine-fuel-certification-centre/"},{"code":"EE","title":"저장성 조선소서 첫 STS 메탄올 벙커링, Maersk Flinders에 공급","src":"Manifold Times","date":"2026-07-02","kSum":"중국 저장성 조선소에서 최초로 선박 대 선박(STS) 메탄올 벙커링이 이뤄졌다. 벙커선 Jia Chen 17호가 신조 5,900TEU 메탄올 이중연료 컨테이너선 Maersk Flinders에 메탄올 795톤을 공급했다.","eSum":"China's Zhejiang province completed its first ship-to-ship methanol bunkering operation at a shipyard, with bunker tanker Jia Chen 17 supplying 795 tonnes of methanol to newly built 5,900 TEU dual-fuel boxship Maersk Flinders.","kImp":"조선소 인도 단계에서의 메탄올 벙커링 표준화는 신조 이중연료선의 상업 운항 준비를 앞당긴다.","eImp":"Standardizing STS methanol bunkering at shipyards speeds up commercial readiness for newly delivered dual-fuel vessels.","url":"https://www.manifoldtimes.com/news/china-zhejiang-completes-first-ship-to-ship-methanol-bunkering-operation-at-shipyard"},{"code":"EE","title":"Grimaldi, 암모니아 대응 PCTC 'Grande Istanbul' 튀르키예서 공개","src":"Manifold Times","date":"2026-07-07","kSum":"Grimaldi Group이 튀르키예 Kocaeli Autoport에서 암모니아 대응 차량운반선(PCTC) 'Grande Istanbul'을 공개했다. 이 선박은 최대 9,241CEU를 적재하며 기존 세대 대비 단위 화물당 탄소배출을 최대 50% 줄인다.","eSum":"Grimaldi Group unveiled its ammonia-ready PCTC Grande Istanbul at a ceremony in Kocaeli, Turkiye. The 9,241 CEU vessel cuts CO2 emissions per cargo unit by up to 50% compared with previous-generation car carriers.","kImp":"암모니아 대응 설계가 자동차 운반선 시장의 표준으로 자리잡고 있음을 보여준다.","eImp":"The unveiling underscores how ammonia-ready design is becoming the norm for new PCTC newbuildings.","url":"https://www.manifoldtimes.com/news/grimaldi-group-unveils-ammonia-ready-pctc-in-turkiye/"},{"code":"EE","title":"Verde Marine Energy, ARA 지역 첫 B100 바이오연료 벙커링","src":"Manifold Times","date":"2026-06-23","kSum":"네덜란드 Verde Marine Energy가 Amsterdam-Rotterdam-Antwerp(ARA) 지역에서 첫 B100 바이오연료 실물 벙커링을 완료했다. Vertom 소유 선박에 B100 FAME 바이오연료를 공급했으며 최대 90%의 온실가스 감축 효과를 낸다.","eSum":"Verde Marine Energy completed its first physical B100 biofuel bunkering in the Amsterdam-Rotterdam-Antwerp region, delivering B100 FAME biofuel to a Vertom-owned vessel with up to 90% greenhouse gas reduction potential.","kImp":"ARA 지역의 B100 공급 개시는 유럽 주요 벙커링 허브의 바이오연료 상용화를 가속한다.","eImp":"The ARA region's first B100 supply marks a step toward commercial-scale biofuel bunkering at Europe's key hub.","url":"https://www.manifoldtimes.com/news/verde-marine-energy-completes-first-b100-bunkering-operation-in-ara-region"},{"code":"EE","title":"Anemoi, MR탱커용 방폭 로터세일 DNV AiP 획득","src":"Offshore Energy","date":"2026-06-10","kSum":"Anemoi Marine Technologies가 Hafnia, Guangzhou Shipyard International(GSI), DNV와 공동으로 접이식 방폭형 로터세일을 MR 탱커에 통합하는 설계에 대한 원칙승인(AiP)을 획득했다.","eSum":"Anemoi Marine Technologies secured DNV approval in principle for integrating folding, explosion-rated rotor sails into an MR tanker design, in a joint project with Hafnia and Guangzhou Shipyard International.","kImp":"탱커 부문까지 로터세일 적용이 확대되며 풍력보조추진 기술의 시장 저변이 넓어지고 있다.","eImp":"Extending rotor sails to the tanker segment broadens the addressable market for wind-assisted propulsion technology.","url":"https://www.offshore-energy.biz/anemoi-dnv-approval-rotor-sail-wind-assisted-propulsion/"},{"code":"EE","title":"OOCL, 첫 메탄올 이중연료선 'OOCL Wisdom' 칭다오서 첫 벙커링","src":"SAFETY4SEA","date":"2026-07-03","kSum":"OOCL이 자사 첫 메탄올 이중연료 컨테이너선 'OOCL Wisdom'의 첫 그린메탄올 벙커링을 칭다오항에서 완료했다. 이 선박은 OOCL이 도입하는 7척의 메탄올 이중연료선 중 첫번째다.","eSum":"OOCL completed the first green methanol bunkering of its first methanol dual-fuel containership, OOCL Wisdom, at Qingdao Port. The vessel is the first of seven methanol dual-fuel boxships being introduced by the carrier.","kImp":"대형 컨테이너선사의 메탄올 벙커링 실적이 쌓이면서 아시아 항만의 연료 인프라 확충 압박이 커지고 있다.","eImp":"As major container lines rack up methanol bunkering milestones, pressure builds on Asian ports to expand fuel infrastructure.","url":"https://safety4sea.com/oocl-conducts-fist-methanol-bunkering-of-its-new-dual-fuel-container-ship/"},{"code":"EE","title":"Exmar, 세계 최초 원양 암모니아 이중연료선 'Antwerpen' 인도","src":"gCaptain","date":"2026-06-10","kSum":"벨기에 Exmar가 세계 최초의 원양 암모니아 이중연료 신조선 'Antwerpen'을 인도받았다. WinGD의 X52DF-A 암모니아 엔진을 탑재했으며 기존 선박 대비 최대 90%의 온실가스 감축이 가능하다.","eSum":"Belgium's Exmar took delivery of Antwerpen, described as the world's first oceangoing dual-fuel ammonia newbuild, powered by WinGD's X52DF-A ammonia engine and capable of cutting greenhouse gases by up to 90%.","kImp":"상업 운항용 암모니아 추진선의 첫 인도는 암모니아 연료의 실용화 단계 진입을 알리는 이정표다.","eImp":"The delivery marks a milestone in ammonia fuel's transition from concept to commercial reality.","url":"https://gcaptain.com/shippings-ammonia-era-begins-as-exmar-receives-landmark-newbuild/"},{"code":"EE","title":"DNV, 2026년 상반기 대체연료 선박 발주 137척으로 감소","src":"MarineLink","date":"2026-07-02","kSum":"DNV에 따르면 2026년 상반기 대체연료 선박 발주량이 137척으로 전년 동기 155척 대비 감소했다. LNG가 73척으로 여전히 우위를 차지했고 LPG/에탄 운반선도 55척으로 크게 늘었다.","eSum":"DNV data shows alternative-fuelled vessel orders fell to 137 in H1 2026 from 155 a year earlier, with LNG-fuelled vessels still leading at 73 orders, while LPG/ethane carrier orders jumped sharply to 55.","kImp":"발주 둔화는 규제 불확실성 속에서도 LNG 중심의 연료 전환 흐름이 지속되고 있음을 시사한다.","eImp":"The order slowdown suggests LNG-centric fuel transition continues even as regulatory uncertainty weighs on newbuild decisions.","url":"https://www.marinelink.com/news/alternativefuel-vessel-orders-slow-down-540882"},{"code":"EE","title":"Wartsila, Grimaldi 신조 페리 9척에 연료유연 추진시스템 공급","src":"The Maritime Executive","date":"2026-07-07","kSum":"Wartsila가 Grimaldi Group의 신조 페리 9척에 추진 솔루션을 공급하기로 했다. 메탄올 등 지속가능 연료 사용이 가능한 46F 엔진이 탑재되며 2026~2028년 순차 인도된다.","eSum":"Wartsila will supply propulsion solutions for nine newbuild ferries under Grimaldi Group's fleet renewal programme, fitted with fuel-flexible 46F engines capable of running on sustainable fuels such as methanol, delivering 2026-2028.","kImp":"페리 부문의 연료유연 엔진 채택 확대는 근해 운항선의 탈탄소 전환에도 속도가 붙고 있음을 보여준다.","eImp":"The ferry sector's adoption of fuel-flexible engines shows decarbonization momentum extending beyond deep-sea shipping.","url":"https://maritime-executive.com/corporate/wartsila-propulsion-solutions-chosen-for-grimaldi-group-s-newbuild-program"},{"code":"EE","title":"Port Freeport, 암모니아·메탄올 대응 PCTC 'Höegh Sunrise' 첫 입항","src":"Container News","date":"2026-07-01","kSum":"미국 Port Freeport가 Höegh Autoliners의 Aurora급 차량운반선 'Höegh Sunrise'의 첫 입항을 맞이했다. 이 선박은 암모니아 및 메탄올 대응 인증을 받았으며 최대 9,100CEU를 적재한다.","eSum":"Port Freeport in Texas welcomed the inaugural call of Hoegh Autoliners' Aurora Class PCTC Hoegh Sunrise, certified as both ammonia-ready and methanol-ready and capable of carrying up to 9,100 car equivalent units.","kImp":"북미 항만에 대체연료 대응 차량운반선 취항이 늘며 자동차 물류망의 저탄소 전환이 확산되고 있다.","eImp":"The call highlights growing deployment of alternative-fuel-ready PCTCs across North American automotive logistics networks.","url":"https://container-news.com/port-freeport-welcomes-hoegh-sunrise-on-inaugural-call/"},{"code":"EE","title":"선주들, 규제 불확실성에 메탄올·암모니아 신조 발주 급감","src":"Riviera Maritime Media","date":"2026-07-08","kSum":"Riviera에 따르면 2026년 상반기 메탄올·암모니아·수소 대응 신조 발주는 단 9척에 그쳤다. IMO 넷제로프레임워크 채택 연기와 청정연료 고비용이 선주들의 투자 관망을 부추기고 있다.","eSum":"Only nine methanol-, ammonia- and hydrogen-capable newbuilds were ordered in H1 2026 as owners pump the brakes amid the postponed IMO Net-Zero Framework and high costs for clean fuels like biomethanol and e-methanol.","kImp":"규제 불확실성이 지속되는 한 차세대 연료 신조 발주 위축은 당분간 이어질 전망이다.","eImp":"Newbuild caution for next-generation fuels is likely to persist while Net-Zero Framework uncertainty remains unresolved.","url":"https://www.rivieramm.com/news-content-hub/owners-pump-the-brakes-on-methanol--ammonia--and-hydrogen-capable-vessels-89310"}]},{"code":"DIG","type":"news","kTitle":"Section 7. 디지털라이제이션","eTitle":"Section 7. Digitalization","items":[{"code":"DIG","title":"부산시, 해양AI소재연구센터 설립 추진","src":"Smart Maritime Network","date":"2026-07-08","kSum":"부산광역시가 부경대, 한국재료연구원(KIMS)과 손잡고 해양AI소재연구센터를 설립한다고 발표했다. 조선, 수산 등 전통 해양산업에 AI를 접목해 친환경 소재 설계부터 로봇 제조공정, 디지털트윈 검증까지 지원한다.","eSum":"Busan Metropolitan City announced a partnership with Pukyong National University and the Korea Institute of Materials Science to establish a Marine AI Materials Research Center, integrating AI from eco-material design to robotic manufacturing and digital-twin verification.","kImp":"지방정부 주도의 해양AI 연구거점 조성은 한국 조선업의 디지털 경쟁력 강화로 이어질 수 있다.","eImp":"The city-led AI research hub could bolster the digital competitiveness of Korea's shipbuilding industry.","url":"https://smartmaritimenetwork.com/2026/07/08/busan-to-establish-marine-ai-materials-research-centre/"},{"code":"DIG","title":"Optimal Transit, 자체발전 방식 선박형 AI 데이터센터 공개","src":"Smart Maritime Network","date":"2026-07-08","kSum":"Optimal Transit이 자체 발전 방식의 선박 기반 AI 데이터센터를 공개했다. 해상에 데이터센터를 배치해 전력·냉각 제약을 우회하고 AI 연산 수요 급증에 대응한다는 구상이다.","eSum":"Optimal Transit unveiled a self-powered, vessel-based AI data centre concept, aiming to deploy computing infrastructure at sea to bypass onshore power and cooling constraints amid surging AI compute demand.","kImp":"해상 부유식 데이터센터 구상은 AI 인프라와 해양산업의 융합 가능성을 보여주는 사례다.","eImp":"The floating data centre concept illustrates a novel convergence between AI infrastructure demand and maritime assets.","url":"https://smartmaritimenetwork.com/2026/07/08/optimal-transit-unveils-self-powered-vessel-based-ai-data-centre/"},{"code":"DIG","title":"Syroco 항해최적화 방법론, DNV 검증 획득","src":"Smart Maritime Network","date":"2026-07-01","kSum":"프랑스 스타트업 Syroco의 항해최적화 방법론이 DNV의 검증을 받았다. 기상·해상 데이터를 활용한 항로 최적화로 연료 절감과 탄소배출 감축 효과를 객관적으로 입증받았다.","eSum":"French startup Syroco had its voyage optimisation methodology verified by DNV, providing independent validation of fuel and emissions savings achieved through weather- and ocean-data-driven route optimisation.","kImp":"제3자 검증을 통한 항로최적화 신뢰성 확보는 관련 솔루션의 시장 채택을 촉진할 것으로 보인다.","eImp":"Third-party verification of voyage optimisation claims should accelerate market adoption of such digital efficiency tools.","url":"https://smartmaritimenetwork.com/2026/07/01/syroco-voyage-optimisation-methodology-verified-by-dnv/"},{"code":"DIG","title":"Angelicoussis, 140척 선단에 Starlink 도입","src":"Riviera Maritime Media","date":"2026-07-03","kSum":"그리스 Angelicoussis Group이 탱커, 가스운반선, 벌크선 등 약 140척 선단에 Starlink 위성통신을 도입해 데이터 사용량이 두 배로 늘었다. 저궤도 위성을 활용해 고화질 영상 전송 등 첨단 운항 서비스가 가능해졌다.","eSum":"Greek shipowner Angelicoussis Group has deployed Starlink connectivity across some 140 tankers, gas carriers and bulkers, doubling data usage and enabling advanced applications like HD video transmission and real-time operational data.","kImp":"대형 선단의 Starlink 전환은 해상 위성통신 시장의 판도를 근본적으로 바꾸고 있다.","eImp":"Large-scale Starlink rollouts are fundamentally reshaping the maritime satellite connectivity market.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/angelicoussis-deploys-starlink-on-140-ship-fleet-89268"},{"code":"DIG","title":"Oldendorff, 벌크선단 80척 이상에 Starlink 확대","src":"Riviera Maritime Media","date":"2026-06-23","kSum":"벌크선사 Oldendorff Carriers가 Marlink를 통해 80척 이상의 자사 벌크선단에 Starlink 연결을 확대했다. 선단 전체가 공유하는 데이터풀 방식으로 탄력적인 대역폭 배분이 가능해졌다.","eSum":"Bulk carrier operator Oldendorff Carriers has extended Starlink connectivity to more than 80 owned vessels via Marlink, using a shared fleet-wide data pool for dynamic bandwidth allocation.","kImp":"벌크선 부문까지 Starlink 도입이 확산되며 저궤도 위성통신이 해운업 표준으로 자리잡고 있다.","eImp":"Starlink's spread into the bulk carrier segment signals LEO satellite connectivity is becoming an industry standard.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/oldendorff-installs-starlink-across-bulk-carrier-fleet-89165"},{"code":"DIG","title":"美 해안경비대, 해양 사이버사고 17% 증가 보고","src":"SAFETY4SEA","date":"2026-07-08","kSum":"미국 해안경비대 사이버사령부 보고서에 따르면 해양 사이버 사고가 전년 대비 17% 증가했으며, 사고의 62%에서 운영기술(OT) 시스템이 관련된 것으로 나타났다. 피싱이 여전히 주요 침투 경로로 지목됐다.","eSum":"A U.S. Coast Guard Cyber Command report found maritime cyber incidents rose 17% year-on-year, with operational technology systems involved in 62% of incidents, while phishing remained the primary entry point.","kImp":"OT 시스템을 겨냥한 사이버 위협 증가는 해운업계의 방어체계 강화 필요성을 부각시킨다.","eImp":"Rising OT-targeted threats underscore the urgent need for stronger cyber defenses across the shipping industry.","url":"https://safety4sea.com/uscg-maritime-cyber-incidents-rise-17-as-phishing-ai-and-ot-risks-reshape-the-threat-landscape/"},{"code":"DIG","title":"'FortiBleed' 사고로 해양기업 250여곳 로그인정보 유출","src":"SAFETY4SEA","date":"2026-07-03","kSum":"사이버보안업체 Cydome에 따르면 'FortiBleed' 사고로 194개국 수천개 조직의 관리자 로그인 정보 8만6000여건이 유출됐으며, 해양업계에서만 250개 이상 기업이 영향을 받았다.","eSum":"Cybersecurity firm Cydome reports the 'FortiBleed' incident exposed over 86,000 administrator logins tied to Fortinet devices across thousands of organizations in 194 countries, with more than 250 maritime firms affected.","kImp":"방화벽 자격증명 관리 소홀이 해양업계 전반의 심각한 보안 취약점으로 드러났다.","eImp":"Poor firewall credential hygiene has emerged as a critical security vulnerability across the maritime sector.","url":"https://safety4sea.com/thousands-of-leaked-logins-put-maritime-networks-at-risk/"},{"code":"DIG","title":"Gulftainer, 'AI 기반 글로벌 무역인프라 기업'으로 전환 선언","src":"Container News","date":"2026-07-08","kSum":"Gulftainer가 항만, 해운, 내륙물류, 산업생태계와 AI 기반 공급망을 하나로 통합하는 '글로벌 무역 인프라 기업'으로의 전환을 선언했다.","eSum":"Gulftainer announced its transformation into a global trade infrastructure company, integrating ports, shipping, inland logistics, industrial ecosystems and AI-powered supply chains into a single connected platform.","kImp":"항만운영사의 AI 기반 사업모델 전환은 물류산업 전반의 디지털화 경쟁을 촉진하고 있다.","eImp":"The port operator's AI-driven business model shift is intensifying digitalization competition across the logistics sector.","url":"https://container-news.com/gulftainer-unveils-transformation-into-global-trade-infrastructure-company/"},{"code":"DIG","title":"Felixstowe항, 자율주행 트럭 100대로 확대","src":"Container News","date":"2026-07-07","kSum":"영국 Felixstowe항이 상하이 Westwell Technology로부터 자율주행 트럭을 추가로 도입해 보유 대수를 100대로 늘렸다. 유럽 항만 중 자율주행 트럭을 가장 큰 규모로 실전 배치한 사례로 꼽힌다.","eSum":"The Port of Felixstowe confirmed a third order of autonomous trucks from Shanghai Westwell Technology, bringing its fleet to 100 units and cementing its position as Europe's leading live deployment of autonomous vehicles at terminal scale.","kImp":"유럽 최대 규모의 자율주행 트럭 실전 운영은 항만 자동화의 실현 가능성을 입증하고 있다.","eImp":"Europe's largest live autonomous truck deployment demonstrates the practical viability of port automation at scale.","url":"https://container-news.com/port-of-felixstowe-expands-autonomous-truck-fleet/"},{"code":"DIG","title":"Adani Ports, Kaleris와 15개 터미널 AI 전면 도입","src":"Container News","date":"2026-06-16","kSum":"인도 Adani Ports(APSEZ)가 미국 Kaleris와의 협력을 확대해 9개 항만 15개 컨테이너터미널 전체에 AI 기반 터미널운영시스템을 도입한다. 최대 1억달러를 투입해 갠트리크레인 생산성을 20%까지 끌어올릴 계획이다.","eSum":"India's Adani Ports (APSEZ) expanded its partnership with US-based Kaleris to deploy AI-driven terminal operating systems across all 15 container terminals spanning nine ports, investing up to $100 million to boost crane productivity by up to 20%.","kImp":"인도 최대 항만운영사의 AI 전면 도입은 아시아 항만 자동화 경쟁을 가속화할 전망이다.","eImp":"India's largest port operator going all-in on AI is set to accelerate the automation race among Asian ports.","url":"https://container-news.com/apsez-scale-ai-driven-terminal-operations-across-15-ports/"},{"code":"DIG","title":"Rotterdam항, 무인 내륙선 터미널간 자율운항 성공","src":"Splash247","date":"2026-06-16","kSum":"Rotterdam항에서 내륙 컨테이너선 'Letitia'가 사람의 직접 조작 없이 Maasvlakte의 Amaliahaven에서 Waalhaven까지 항해하는 데 성공했다. 45개 기관이 참여하는 MAGPIE 프로젝트의 실증사업 중 하나다.","eSum":"The Port of Rotterdam completed a demonstration in which inland container vessel Letitia sailed autonomously from Amaliahaven on Maasvlakte to Waalhaven without active human control, part of the 45-partner MAGPIE initiative.","kImp":"상업 항만 내 자율운항 실증 성공은 자율선박 상용화의 실질적 진전을 보여준다.","eImp":"The successful in-port autonomous trial marks tangible progress toward commercial deployment of autonomous vessels.","url":"https://splash247.com/autonomous-barge-completes-terminal-to-terminal-voyage-in-rotterdam/"},{"code":"DIG","title":"K Line, 전 선단에 디지털 기관실 점검 시스템 도입","src":"Splash247","date":"2026-06-10","kSum":"Kawasaki Kisen Kaisha가 스마트폰 기반 앱을 통해 약 1,000개 항목의 엔진룸 점검을 전자화하는 시스템을 전 선단에 도입했다. 기존 종이 기반 점검 방식의 안전 문제를 해소하고 데이터를 디지털로 축적한다.","eSum":"K Line has rolled out a smartphone-based application across its fleet to digitize roughly 1,000 engine room inspection items, replacing paper-based checks to improve crew safety and build a digital vessel data platform.","kImp":"기관실 점검의 디지털 전환은 선박관리 데이터 축적과 안전관리 고도화에 기여할 것이다.","eImp":"Digitizing engine room inspections will help build richer vessel data platforms and strengthen safety management.","url":"https://splash247.com/k-line-deploys-digital-engine-room-inspection-system-across-fleet/"}]},{"code":"TECH","type":"news","kTitle":"Section 8. 선박기술","eTitle":"Section 8. Ship Technology","items":[{"code":"TECH","title":"WinGD, Dynacom VLCC 12척에 주기관 공급 계약","src":"MarineLink","date":"2026-07-01","kSum":"스위스 엔진 설계사 WinGD가 그리스 탱커선사 Dynacom을 위해 중국 Hudong-Zhonghua 조선소에서 건조 중인 VLCC 12척에 주력 엔진을 공급하는 계약을 체결했다. 각 선박에는 스크러버와 고압 SCR을 갖춘 6X82-2.0 저속 엔진이 탑재된다.","eSum":"Swiss engine designer WinGD has secured a contract to supply main engines for 12 VLCCs being built at Hudong-Zhonghua Shipbuilding for Greek owner Dynacom. Each vessel will carry a WinGD 6X82-2.0 low-speed engine with scrubbers and high-pressure SCR.","kImp":"탱커 선대 갱신 수요가 저속엔진 및 배기정화 기술의 표준화를 가속화하고 있다.","eImp":"The order underscores tanker fleet renewal driving standardization of low-speed engines and exhaust cleaning technology.","url":"https://www.marinelink.com/news/wingd-books-engine-order-dynacoms-vlcc-540828"},{"code":"TECH","title":"Subsea Global Solutions, Antwerp서 C-ROV 선체청소 서비스 출범","src":"MarineLink","date":"2026-06-15","kSum":"Subsea Global Solutions가 벨기에 Antwerp를 거점으로 C-ROV 선체 청소 서비스를 7월부터 공식 출범한다. 수중 선체청소, 생물부착 관리, 프로펠러 연마, 수중 검사·수리를 제공한다.","eSum":"Subsea Global Solutions announced the launch of its C-ROV hull cleaning services in Antwerp, effective July 2026, offering underwater hull cleaning, biofouling management, propeller polishing and in-water repairs.","kImp":"항구 대기와 저속운항 증가로 생물부착 관리 수요가 유럽 전역에서 확대되고 있다.","eImp":"The expansion reflects growing European demand for biofouling management as vessels idle and slow-steam more.","url":"https://www.marinelink.com/news/subsea-global-solutions-launches-new-crov-540319"},{"code":"TECH","title":"유럽 19개사, FIT-HORIZONS 개조 설계 프로젝트 출범","src":"MarineLink","date":"2026-06-11","kSum":"유럽 19개 해운·기술 기업이 참여하는 FIT-HORIZONS 프로젝트가 기존 선대의 저탄소 개조를 가속화하는 AI 지원 설계 환경을 구축한다. SINTEF Ocean이 주관하며 EU가 약 461만 달러를 지원한다.","eSum":"A European consortium of 19 companies has launched FIT-HORIZONS, coordinated by SINTEF Ocean and EU-funded with $4.61m, to build an AI-supported retrofit design environment for decarbonizing the existing fleet.","kImp":"노후 선대의 개조 의사결정을 가속화할 시뮬레이션·AI 도구 개발이 본격화된다.","eImp":"The project aims to speed up retrofit decisions across six vessel segments using AI-supported simulation tools.","url":"https://www.marinelink.com/news/european-fithorizons-project-aims-540202"},{"code":"TECH","title":"Seaspan·Maersk, 18척 컨테이너선 성능개선 프로그램 확대","src":"Splash247","date":"2026-07-08","kSum":"Seaspan과 Maersk가 장기 용선 중인 18척 컨테이너선 개선 프로그램에 최소 7,500만 달러를 투자한다. 1만3000TEU급 4척에는 축발전기, 주기관 최적화, 고효율 프로펠러가 설치된다.","eSum":"Seaspan and Maersk are expanding a vessel efficiency programme across 18 chartered containerships with at least $75m invested, including shaft generators, main engine optimization and high-efficiency propellers on four 13,000 TEU ships.","kImp":"개조로 슬롯당 비용을 10~13% 낮춰 규제 대응과 수익성을 동시에 개선할 전망이다.","eImp":"The retrofits are expected to cut slot costs 10-13%, combining regulatory readiness with commercial gains.","url":"https://splash247.com/seaspan-and-maersk-deepen-retrofit-push/"},{"code":"TECH","title":"GasLog LNG선, 스마트 예방정비 인증 획득","src":"Smart Maritime Network","date":"2026-06-29","kSum":"GasLog 소속 LNG선이 열역학 디지털 트윈과 고빈도 텔레메트리를 결합한 스마트·예방정비 인증을 획득했다. 윤활유·화학·진동·계획정비 데이터를 통합해 상태기반 정비를 구현한다.","eSum":"A GasLog LNG carrier has received smart and preventative maintenance approval combining thermodynamic digital twins with lubrication, chemical, vibration and PMS data for condition-based maintenance.","kImp":"LNG선단에 상태기반 정비가 본격 도입되며 예방정비 신뢰성이 높아질 전망이다.","eImp":"The approval signals wider adoption of condition-based maintenance across LNG fleets.","url":"https://smartmaritimenetwork.com/2026/06/29/gaslog-vessel-gets-smart-and-preventative-maintenance-approval/"},{"code":"TECH","title":"Everllence, 이중연료 메탄엔진 첫 수주","src":"Seatrade Maritime News","date":"2026-06-16","kSum":"노르웨이 선사 Global Car Carriers가 중국에서 건조 중인 8,600CEU급 자동차운반선 4척에 Everllence의 이중연료 메탄엔진을 최초로 발주했다. Mk10.7 ME-GI 엔진이 CSSC 칭다오에서 제작된다.","eSum":"Norway's Global Car Carriers has placed the first order for Everllence's dual-fuel methane engine for four 8,600-ceu car carriers built in China, with Mk10.7 ME-GI engines built at CSSC Qingdao.","kImp":"규제 지연에도 선주들이 자발적으로 탈탄소 추진 기술을 채택하는 흐름이 이어지고 있다.","eImp":"The order shows proactive shipowners pursuing decarbonization technology despite regulatory delay.","url":"https://www.seatrade-maritime.com/shipyards/everllence-wins-its-first-order-for-new-dual-fuel-methane-engine"},{"code":"TECH","title":"팬오션, CSSC에 암모니아 대응 VLCC 2척 추가 발주","src":"Seatrade Maritime News","date":"2026-07-07","kSum":"팬오션이 CSSC 칭다오 Beihai 조선소에 암모니아 대응 VLCC 2척을 추가 발주했다. 척당 약 1억2,200만 달러로 2030년 인도 예정이다.","eSum":"Pan Ocean has ordered an ammonia-ready VLCC pair at CSSC Qingdao Beihai, worth about $121.8m each, due for delivery by 2030.","kImp":"대형 탱커 발주에서도 미래연료 대응 설계가 표준으로 자리잡고 있다.","eImp":"The order reflects future-fuel-ready design becoming standard even in conventional VLCC newbuilding.","url":"https://www.seatrade-maritime.com/shipyards/pan-ocean-orders-ammonia-ready-vlcc-pair-at-cssc"},{"code":"TECH","title":"Hapag-Lloyd, Everllence 메탄올 개조 1호선 재취항","src":"Seatrade Maritime News","date":"2026-06-24","kSum":"Hapag-Lloyd 소속 1만100TEU급 Seaspan Yangtze호가 Everllence PrimeServ의 메탄올 이중연료 엔진 개조를 완료해 5척 개조 프로그램 중 첫 번째로 재취항했다. 상하이 COSCO 조선소에서 3개월간 진행됐다.","eSum":"The 10,100 TEU Seaspan Yangtze, chartered to Hapag-Lloyd, has returned to service as the first of five vessels converted to methanol dual-fuel under Everllence PrimeServ's programme, completed in a three-month retrofit at COSCO Shanghai.","kImp":"대형 2행정 엔진의 메탄올 개조가 반복 가능한 상용 솔루션으로 자리잡았음을 보여준다.","eImp":"The retrofit shows large two-stroke methanol conversions becoming a repeatable, commercial solution.","url":"https://www.seatrade-maritime.com/shipyards/first-of-five-hapag-lloyd-dual-fuel-retrofits-completed-by-everllence"},{"code":"TECH","title":"파나마운하청, 하이브리드 예인선 20척 투입","src":"Riviera Maritime Media","date":"2026-07-03","kSum":"파나마운하청이 2050년 넷제로 목표를 위해 하이브리드 예인선 20척에 투자하며 탈탄소 여정을 시작했다. 각 예인선은 Wabtec 디젤엔진 2기와 Corvus 배터리를 탑재한다.","eSum":"The Panama Canal Authority is investing in 20 hybrid tugs, each fitted with two Wabtec diesel engines and Corvus batteries, as it begins its journey toward net-zero emissions by 2050.","kImp":"세계 최대 운하 운영기관의 예인선단 전동화가 항만 예인 탈탄소의 이정표가 될 전망이다.","eImp":"The fleet electrification marks a milestone for decarbonization in port towage led by the world's busiest canal operator.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/panama-canals-journey-to-net-zero-starts-with-hybrid-tugs-89226"},{"code":"TECH","title":"BW Epic Kosan, GIT Coatings 그래핀 선체도장 확대","src":"The Maritime Executive","date":"2026-06-11","kSum":"LPG 운항사 BW Epic Kosan이 GIT Coatings와 협력해 5척의 LPG선에 무독성 그래핀 기반 선체 도장을 적용, 능동적 선체관리로 출항 시 약 6%의 출력 향상을 달성했다.","eSum":"LPG operator BW Epic Kosan has partnered with GIT Coatings to apply biocide-free graphene-based hull coatings across five LPG carriers, achieving an out-of-dock power gain of about 6% through proactive hull management.","kImp":"선체 성능 데이터 기반 관리가 연료비 절감과 CII 대응의 핵심 수단으로 확산되고 있다.","eImp":"Data-driven proactive hull management is spreading as a key tool for fuel savings and CII compliance.","url":"https://maritime-executive.com/corporate/bw-epic-kosan-expands-use-of-git-coatings-for-fuel-savings"},{"code":"TECH","title":"Smart Ship Hub, 600달러대 저가형 선내 데이터 로거 출시","src":"Smart Maritime Network","date":"2026-06-22","kSum":"Smart Ship Hub이 약 600달러의 저비용 선내 데이터 로거를 출시해 선박 디지털화 비용 장벽을 낮췄다. 엣지 지능형 분석 기능으로 연료, 선체, 엔진, 화물 성능 데이터를 통합 제공한다.","eSum":"Smart Ship Hub has launched an onboard data logger priced at about $600, aiming to lower the cost of vessel digitalization, with edge intelligence supporting fuel, hull, engine and cargo performance analytics.","kImp":"저가형 데이터로거가 중소 선사의 디지털 전환 진입장벽을 크게 낮출 것으로 기대된다.","eImp":"The low-cost logger is expected to significantly lower the barrier to digital adoption for smaller operators.","url":"https://smartmaritimenetwork.com/2026/06/22/smart-ship-hub-launches-600-vessel-data-logger/"}]},{"code":"HR","type":"news","kTitle":"Section 9. 해사 인사(Marine HR)","eTitle":"Section 9. Marine HR","items":[{"code":"HR","title":"내일의 선원은 어디서 올까","src":"Splash247","date":"2026-06-09","kSum":"절반에 가까운 현직 선원이 5년 내 이직을 고려한다는 연구 결과가 나온 가운데, 업계가 아프리카 등 새로운 지역에서 승선 인력을 확충하려는 움직임을 보이고 있다.","eSum":"Splash247 reports the industry is looking to new regions such as Africa to build future crewing pipelines, following a study warning nearly half of today's seafarers plan to quit within five years.","kImp":"선원 공급망 다변화가 장기적 인력난 해소의 핵심 전략으로 부상하고 있다.","eImp":"Diversifying the seafarer supply pipeline is emerging as a key strategy to address the crewing shortage.","url":"https://splash247.com/where-will-tomorrows-seafarers-come-from/"},{"code":"HR","title":"해운업계, 불법 채용수수료 근절 안간힘","src":"Splash247","date":"2026-06-25","kSum":"선원 3명 중 1명이 승선을 위해 불법 채용 수수료를 요구받은 것으로 나타나 IHRB와 TURTLE이 근절을 위한 새 온라인 툴킷을 출범시켰다. CMA CGM, Wilhelmsen Ship Management 등 30여개 기관이 지지했다.","eSum":"Nearly one in three seafarers have been asked to pay illegal recruitment fees, prompting IHRB and TURTLE to launch an online toolkit backed by 30+ organisations including CMA CGM and Wilhelmsen Ship Management.","kImp":"불법 채용 수수료 근절이 선원 인력난 해소를 위한 업계 최우선 과제로 부상했다.","eImp":"Eliminating illegal recruitment fees is becoming an industry priority to address the seafarer talent shortage.","url":"https://splash247.com/shipping-struggles-to-stamp-out-illegal-recruitment-fees/"},{"code":"HR","title":"NorthStandard-Sailors' Society, 선원 정신건강 지원 협력","src":"SAFETY4SEA","date":"2026-06-25","kSum":"NorthStandard가 항해자 자선단체 Sailors' Society와 협력해 선내 정서적 지원 프로그램 'Sea Mate'를 통해 선원들이 웰빙 담당자로 훈련받도록 지원한다.","eSum":"NorthStandard has partnered with Sailors' Society to deliver Sea Mate, an onboard mental health awareness programme training seafarers to become Wellbeing Officers.","kImp":"P&I 클럽이 정신건강 지원을 손실예방 서비스의 핵심 영역으로 확대하고 있다.","eImp":"P&I clubs are expanding mental health support as a core loss-prevention service.","url":"https://safety4sea.com/northstandard-partners-up-with-sailors-society-on-seafarer-wellbeing/"},{"code":"HR","title":"2026 세계 해운의 날, 선원의 위험을 조명하다","src":"SAFETY4SEA","date":"2026-06-25","kSum":"세계 해운의 날을 맞아 SAFETY4SEA가 세계 무역을 지탱하는 선원들이 감당하는 위험과 희생을 조명하는 'Carrying world trade. Carrying the risks.' 캠페인을 소개했다.","eSum":"To mark Day of the Seafarer 2026, SAFETY4SEA highlighted the campaign theme 'Carrying world trade. Carrying the risks,' recognizing the hardship seafarers endure to keep trade moving.","kImp":"지정학적 갈등 속 선원 위험 노출이 커지며 업계 전반의 인식 제고가 시급해졌다.","eImp":"Rising seafarer risk exposure amid geopolitical conflict is heightening the urgency of industrywide awareness.","url":"https://safety4sea.com/cm-day-of-the-seafarer-2026-recognizing-those-carrying-world-trade-and-the-risks-behind-it/"},{"code":"HR","title":"그리스, 선원 자격증 전자발급 시스템 도입","src":"SAFETY4SEA","date":"2026-06-18","kSum":"그리스 해양도서정책부가 선원 자격증명서와 유효확인서 발급을 위한 새 전자 신청 시스템을 도입해 행정 절차를 간소화하고 발급 속도를 높인다.","eSum":"Greece has launched a digital platform to streamline issuance and validation of seafarer certificates of competency, reducing in-person visits and accelerating processing.","kImp":"선원 자격 행정의 디지털 전환이 그리스를 시작으로 유럽 전역으로 확산될 조짐을 보인다.","eImp":"Digitalization of seafarer certification administration signals a broader shift likely to spread across Europe.","url":"https://safety4sea.com/greece-introduces-new-digital-system-for-seafarer-certificates/"},{"code":"HR","title":"영국, 영불해협 선원 보호 확대 계획 발표","src":"Nautilus International","date":"2026-06-05","kSum":"Nautilus International이 영불해협을 오가는 선원들에게 최저임금 수준의 급여와 최소 휴식시간을 보장하는 영국 정부의 새 보호 방안을 환영했다.","eSum":"Nautilus International has welcomed UK proposals to extend pay and working condition protections to seafarers on cross-Channel routes, guaranteeing minimum wage-equivalent pay and enforced rest periods.","kImp":"페리 선원 보호 강화가 유럽 역내 노동기준 상향의 시금석이 될 전망이다.","eImp":"Stronger ferry seafarer protections could set a benchmark for raising labour standards across European routes.","url":"https://www.nautilusint.org/en/news-insight/news/nautilus-welcomes-uk-government-plans-for-new-cross-channel-seafarer-protections/"},{"code":"HR","title":"선원 웰빙 이러닝 설문, 고용주 참여 독려","src":"Nautilus International","date":"2026-07-07","kSum":"Nautilus International이 선원 정신·신체 건강 및 피로관리를 위한 향후 웰빙 지원과 이러닝 자료 개발을 돕기 위해 해운사 참여를 독려하는 설문조사를 실시한다고 밝혔다.","eSum":"Nautilus International is urging maritime employers to take part in a survey to help shape future wellbeing support and e-learning resources for seafarer mental and physical health and fatigue management.","kImp":"피로관리 데이터 확보가 향후 훈련 콘텐츠 설계의 근거자료로 활용될 전망이다.","eImp":"The survey data is expected to inform the design of future fatigue-management training content.","url":"https://www.nautilusint.org/en/news-insight/news/seafarer-employers-urged-to-take-part-in-e-learning-survey-to-aid-maritime-wellbeing/"},{"code":"HR","title":"호르무즈 해협, 발 묶인 선원 8,000명 구출 사투","src":"gCaptain","date":"2026-07-05","kSum":"호르무즈 해협 인근에 8,000명에 달하는 선원이 여전히 발이 묶여 있으며, 일부는 정전 이후 5개월 가까이 대피하지 못한 채 대기 중인 것으로 나타났다.","eSum":"gCaptain, citing Bloomberg, reports roughly 8,000 sailors remain stranded near the Strait of Hormuz, with some crews waiting nearly five months since the conflict began without evacuation.","kImp":"지정학적 갈등이 장기화되며 선원 인도주의 위기가 해운업계의 최우선 현안으로 부상했다.","eImp":"The prolonged geopolitical crisis has pushed seafarer humanitarian conditions to the top of the industry's agenda.","url":"https://gcaptain.com/the-race-to-rescue-8000-sailors-still-stranded-behind-hormuz/"},{"code":"HR","title":"2030년까지 사관 11만4,000명 추가 필요","src":"gCaptain","date":"2026-06-26","kSum":"BIMCO·ICS 선원인력보고서에 따르면 2030년까지 해운업계는 추가로 11만4,000명의 STCW 자격 사관이 필요하며, 올해에만 3만9,100명의 사관 부족이 예상된다.","eSum":"The BIMCO/ICS Seafarer Workforce Report 2026 warns global shipping will need 114,000 additional STCW-certified officers by 2030, with a shortage of 39,100 already projected for this year.","kImp":"사관 부족 심화가 해상 안전과 운항 효율성에 구조적 위협이 되고 있다.","eImp":"The deepening officer shortage poses a structural threat to maritime safety and operational efficiency.","url":"https://gcaptain.com/global-shipping-needs-114000-more-officers-by-2030-new-report-warns/"},{"code":"HR","title":"Mayuree Naree호 희생 선원 유해, 태국 송환","src":"Seatrade Maritime News","date":"2026-07-03","kSum":"지난 3월 호르무즈 해협에서 발생한 태국적 벌크선 Mayuree Naree호 공격으로 숨진 선원 3명의 유해가 3개월 반 만에 태국으로 송환됐다.","eSum":"More than three and a half months after the attack on the bulker Mayuree Naree in the Strait of Hormuz, the remains of three seafarers who died have been repatriated to Thailand.","kImp":"분쟁지역 항해 위험이 실제 인명피해로 이어지고 있음을 재확인하는 사례다.","eImp":"The repatriation underscores the real human cost of navigating conflict-affected waters.","url":"https://www.seatrade-maritime.com/security/remains-seafarers-killed-in-mayuree-naree-attack-repatriated"},{"code":"HR","title":"FrontM, 선원용 통합 플랫폼 'onship' 업그레이드","src":"Seatrade Maritime News","date":"2026-06-29","kSum":"FrontM이 세계 해운의 날을 맞아 선원과 해사 전문가를 위한 통합 디지털 플랫폼 'onship'의 업그레이드 버전을 출시했다. 산업 정보, 경력개발, 웰빙 자료를 무료로 제공한다.","eSum":"FrontM has launched an upgraded onship platform on Day of the Seafarer, offering a free digital hub for seafarers combining industry insights, career development and wellbeing resources.","kImp":"선원 대상 통합 디지털 플랫폼 경쟁이 웰빙과 경력관리 영역까지 확대되고 있다.","eImp":"Competition among seafarer-focused digital platforms is expanding beyond connectivity into wellbeing and career management.","url":"https://www.seatrade-maritime.com/crewing/frontm-upgrades-onship-app-for-seafarers-and-maritime-professionals"},{"code":"HR","title":"JobMarineMan, 선사-선원 직접연결 채용 플랫폼 출시","src":"The Maritime Executive","date":"2026-06-16","kSum":"Marine MAN이 개발한 JobMarineMan.com이 선사와 선원을 직접 연결하는 디지털 채용 플랫폼을 선보이며 대행수수료 절감과 채용 파이프라인 현대화를 추진하고 있다.","eSum":"JobMarineMan.com, developed by Marine MAN, is a next-generation digital recruitment ecosystem connecting shipowners directly with seafarers, cutting manning fees and modernizing crew hiring.","kImp":"전통적 대행사 중심 채용구조에 디지털 직접채용 모델이 도전장을 던지고 있다.","eImp":"The platform challenges the traditional manning-agent model with a direct digital hiring approach.","url":"https://maritime-executive.com/features/new-digital-platform-connects-shipowners-directly-with-seafarers"}]},{"code":"HSEQ","type":"news","kTitle":"Section 10. HSEQ·손실예방","eTitle":"Section 10. HSEQ & Loss Prevention","items":[{"code":"HSEQ","title":"Gard, 한국 해역 어업 관련 클레임 급증 경고","src":"Gard","date":"2026-07-06","kSum":"Gard가 한국 해역에서 어망 접촉으로 인한 항해사고가 2024년 대비 125% 급증했다고 밝히며, VDR·ECDIS 항적 데이터 백업 등 손실예방 권고안을 제시했다.","eSum":"Gard reports a 125% increase in navigation incidents involving fishing nets in Korean waters versus 2024, recommending crews back up VDR and ECDIS track data and assume hazards may extend beyond visible markers.","kImp":"어업활동 밀집 해역에서의 항해 리스크 관리가 P&I 클럽의 새로운 손실예방 초점으로 떠올랐다.","eImp":"Navigation risk management in fishery-dense waters has become a fresh loss-prevention focus for P&I clubs.","url":"https://gard.no/en/insights/fishery-claims-rise-south-korea-waters/"},{"code":"HSEQ","title":"화물 화재, 갈수록 빈발하고 심각해진다","src":"UK P&I Club","date":"2026-06-17","kSum":"UK P&I Club이 컨테이너 화물 화재가 2020년 2주에 한 번에서 2023년 9일에 한 번꼴로 빈발해지고 있다며, 오격신고 화물과 리튬이온배터리 확산에 따른 구조적 위험 증가를 경고했다.","eSum":"UK P&I Club warns cargo fires are becoming more frequent and severe, now occurring roughly every nine days versus every two weeks in 2020, driven by misdeclared cargo and lithium-ion battery growth.","kImp":"규제 정비 속도가 실제 리스크 증가 속도를 따라가지 못해 사전예방과 승선원 훈련 강화가 시급하다.","eImp":"Regulation is lagging risk escalation, making prevention and crew training increasingly urgent.","url":"https://www.ukpandi.com/news-and-resources/news/article/tackling-the-evolving-challenge-of-cargo-fires-at-sea"},{"code":"HSEQ","title":"Steamship Mutual, 액체화물 오염사고 리스크얼럿 발행","src":"Steamship Mutual","date":"2026-07-07","kSum":"Steamship Mutual이 액체화물 오염 사고 예방을 위한 Risk Alert 140을 발행, 탱크 세정 미흡과 샘플링 분쟁 등 주요 원인을 분석하고 문서화 및 증거보전의 중요성을 강조했다.","eSum":"Steamship Mutual has issued Risk Alert 140 on preventing liquid cargo contamination, examining causes like inadequate tank cleaning and sampling disputes, stressing documentation and evidence preservation.","kImp":"액체화물 클레임 급증에 대응해 사전 문서화 체계 정비가 필수 과제로 떠올랐다.","eImp":"Robust documentation practices are becoming essential as liquid cargo contamination claims rise.","url":"https://www.steamshipmutual.com/publications/articles/liquid-cargoes-challenges-and-prevention-cargo-contamination"},{"code":"HSEQ","title":"PSC 검사, 단순 점검 넘어 리스크관리 도구로","src":"Steamship Mutual","date":"2026-06-30","kSum":"Steamship Mutual이 항만국통제(PSC) 검사를 단순 규정준수 확인을 넘어 능동적 리스크관리 도구로 활용해야 한다는 Risk Alert 139를 발행했다.","eSum":"Steamship Mutual's Risk Alert 139 argues PSC inspections should be used as a proactive risk management tool rather than solely a compliance exercise, by analysing deficiency trends.","kImp":"PSC 데이터 분석이 사고 예방과 함대 성과 개선의 전략적 자산으로 재조명되고 있다.","eImp":"PSC inspection data is being reframed as a strategic asset for incident prevention and fleet performance.","url":"https://www.steamshipmutual.com/publications/articles/beyond-inspection-rethinking-port-state-control"},{"code":"HSEQ","title":"Britannia, 벙커 연료품질 분쟁 웨비나 개최","src":"Britannia P&I","date":"2026-06-30","kSum":"Britannia P&I Club이 연료 품질 분쟁 관리를 주제로 손실예방 웨비나를 개최해 기술적 판단과 상업적 현실의 균형, 리스크 지표 식별 방안을 논의한다.","eSum":"Britannia P&I Club is hosting a loss prevention webinar on managing bunker fuel quality disputes, covering risk indicators and balancing technical and commercial decision-making.","kImp":"연료품질 분쟁이 소규모 편차에서도 운항 차질로 확대될 수 있어 선제적 판단력이 요구된다.","eImp":"Even minor fuel quality deviations can escalate into major disruptions, underscoring proactive assessment.","url":"https://britanniapandi.com/2026/06/britannia-loss-prevention-webinar-choose-your-bunker-battles-wisely/"},{"code":"HSEQ","title":"영국 해양안전주간, '바인더를 넘어서' SMS 개혁 촉구","src":"IIMS","date":"2026-07-06","kSum":"영국 해양안전주간(7월 6~10일)을 맞아 MAIB 수석조사관 Rob Loder가 'Beyond the binder: making safety management systems work at sea'라는 기고문을 IIMS에 게재했다.","eSum":"During UK Maritime Safety Week (6-10 July), MAIB Chief Inspector Rob Loder wrote 'Beyond the binder: making safety management systems work at sea' for IIMS, addressing SMS effectiveness.","kImp":"서류상 안전관리체계와 실제 현장 관행 간 간극 해소가 핵심 과제로 제시됐다.","eImp":"Closing the gap between paper-based SMS compliance and real onboard practice is highlighted as key.","url":"https://www.iims.org.uk/maritime-safety-week-2026/"},{"code":"HSEQ","title":"2026년 해운 사고 16% 감소했지만 기계고장은 여전히 최대 리스크","src":"MarineLink","date":"2026-06-24","kSum":"Allianz Commercial의 'Safety and Shipping Review 2026'을 인용한 MarineLink 분석에 따르면 2025년 전체 사고는 16% 감소했으나 기계고장이 전체 사고의 53%를 차지하며 여전히 최대 리스크로 남아있다.","eSum":"MarineLink's analysis of Allianz's Safety and Shipping Review 2026 shows total incidents fell 16% in 2025, yet machinery damage and failure still accounted for 53% of all casualties, the top operational risk.","kImp":"손실 건수는 줄었지만 지정학적 갈등과 노후선대로 리스크의 질이 더 복잡해지고 있다.","eImp":"While loss numbers decline, the nature of risk is becoming more complex amid conflict and an aging fleet.","url":"https://www.marinelink.com/news/numbers-maritime-safety-fewer-losses-540599"},{"code":"HSEQ","title":"IACS, IMO 이행소위(III 12)에 기술 제안 제출","src":"SAFETY4SEA","date":"2026-07-06","kSum":"국제선급연합회(IACS)가 7월 20~24일 열리는 IMO 이행소위(III 12)에 참가해 기국·항만국 감사 및 인증체계 이행 강화를 위한 기술 제안을 제출한다.","eSum":"IACS will take part in the IMO's 12th Sub-Committee on Implementation of IMO Instruments (III 12), 20-24 July, submitting proposals to strengthen flag and port State audit and certification enforcement.","kImp":"규정 이행의 실효성 확보가 국제 해사규제 논의의 핵심 축으로 자리잡고 있다.","eImp":"Ensuring effective implementation of existing rules is becoming central to international maritime regulatory discussions.","url":"https://safety4sea.com/iacs-submissions-at-imos-iii-12/"},{"code":"HSEQ","title":"컨테이너선 화재, 17일에 한 번꼴로 발생","src":"gCaptain","date":"2026-06-26","kSum":"Allianz 2026 해운안전보고서에 따르면 세계 어딘가에서 17일에 한 번꼴로 컨테이너선 화재가 발생하고 있으며, 오격신고 화물이 화재 원인의 약 4분의 1을 차지한다.","eSum":"According to Allianz's Safety and Shipping Review 2026, a containership fire now breaks out somewhere in the world roughly every 17 days, with misdeclared cargo causing about a quarter of incidents.","kImp":"리튬이온배터리 물동량 급증이 컨테이너선 화재 위험을 구조적으로 끌어올리고 있다.","eImp":"Surging lithium-ion battery volumes are structurally elevating containership fire risk.","url":"https://gcaptain.com/containership-fire-breaks-out-every-17-days-as-misdeclared-cargo-remains-major-threat/"},{"code":"HSEQ","title":"기계고장, 여전히 해운업계 최대 리스크로 지속","src":"gCaptain","date":"2026-07-06","kSum":"2025년 전 세계 해양사고의 절반 이상이 기계고장으로 인한 것으로 나타나며 노후 선대, 정비능력 제약, 이중연료 전환 난제가 복합적으로 작용하고 있다.","eSum":"gCaptain reports machinery damage or failure caused more than half of all reported shipping incidents in 2025, driven by fleet aging, repair capacity constraints and dual-fuel transition challenges.","kImp":"기계고장이 수년째 부동의 1위 사고 원인으로 남아 정비체계 혁신의 필요성이 커지고 있다.","eImp":"With machinery failure remaining the leading cause of incidents for years, maintenance system innovation is increasingly needed.","url":"https://gcaptain.com/the-engine-room-problem-and-why-machinery-failure-remains-shippings-dominant-risk/"},{"code":"HSEQ","title":"Skuld, 보조기관 이로전플러그 손상發 기관실 화재 경고","src":"Skuld","date":"2026-07-03","kSum":"Skuld가 보조기관 이로전 플러그 손상으로 인한 기관실 화재 사례를 경고하며 정비 관리 강화, 재조립 후 운전점검, 열화상 점검 등 구체적 손실예방 조치를 권고했다.","eSum":"Skuld has flagged recent cases of engine room fires caused by erosion plug failure in fuel pumps, recommending stricter maintenance controls, post-reassembly checks and thermal imaging inspections.","kImp":"사소해 보이는 부품 결함이 대형 화재로 이어질 수 있어 정비 절차 준수가 핵심 손실예방 수단으로 강조됐다.","eImp":"Seemingly minor component defects can trigger major fires, reinforcing strict maintenance procedure compliance.","url":"https://www.skuld.com/topics/ship/safety/fire-in-the-engine-room-due-to-auxiliary-engine-erosion-plug-failure/"},{"code":"HSEQ","title":"Skuld, 남서태평양 니켈광 화물 안전운송 가이드 발표","src":"Skuld","date":"2026-06-24","kSum":"Skuld가 남서태평양산 니켈광 화물의 안전 운송에 관한 가이드라인을 발표해 액화 위험과 선적 전 검사 절차를 강조했다.","eSum":"Skuld has issued guidance on the safe carriage of nickel ore cargoes from the south-western Pacific Ocean, emphasizing liquefaction risks and pre-loading inspection procedures.","kImp":"니켈광 액화사고가 반복되는 가운데 선적 전 검증 절차 강화가 재차 요구되고 있다.","eImp":"Amid recurring nickel ore liquefaction incidents, stronger pre-loading verification procedures are being urged again.","url":"https://www.skuld.com/topics/cargo/solid-bulk/cargo-liquefaction/safe-carriage-of-nickel-ore-cargoes-in-the-south-western-pacific-ocean/"}]},{"code":"KR","type":"news","kTitle":"Section 11. 한국 해운","eTitle":"Section 11. Korean Shipping","items":[{"code":"KR","title":"日 LNG선사, 기술협력 파트너로 국내 조선·해운업계 지목","src":"해사신문","date":"2026-07-09","kSum":"일본 대형 해운사가 LNG 운반선 및 추진 기술 협력 파트너로 한국 조선·해운업계를 지목한 것으로 알려졌다. 호르무즈해협 정세 불안으로 LNG 조달 안정성이 부각되면서 한일 간 선박 기술 협력 논의가 활발해지고 있다.","eSum":"A major Japanese shipping company has reportedly named Korean shipbuilders and carriers as technology cooperation partners for LNG carrier and propulsion technology. Discussions have intensified amid Strait of Hormuz volatility highlighting the importance of stable LNG supply chains.","kImp":"중동 정세 불안 속 한일 해운·조선 기술협력이 강화되는 흐름을 보여준다.","eImp":"Signals deepening Korea-Japan shipbuilding cooperation amid Middle East supply uncertainty.","url":"https://haesanews.com/news/articleView.html?idxno=149161"},{"code":"KR","title":"HMM, 벌크·탱커 선대 확충에 1.7조원 투자","src":"해사신문","date":"2026-07-01","kSum":"HMM이 비컨테이너 사업 강화를 위해 벌크선과 탱커 선대 확충에 총 1조7000억원을 투자한다고 밝혔다. 컨테이너 시황 변동성에 대비해 사업 포트폴리오를 다각화하려는 전략으로 풀이된다.","eSum":"HMM announced a 1.7 trillion won investment to expand its bulk carrier and tanker fleets as part of a non-container business diversification push. The move aims to hedge against container market volatility.","kImp":"국내 최대 선사의 사업다각화 전략이 본격화되고 있음을 보여준다.","eImp":"Shows Korea's top carrier accelerating diversification beyond container shipping.","url":"https://haesanews.com/news/articleView.html?idxno=148979"},{"code":"KR","title":"BPA, 김호영 신임 건설본부장 임명","src":"코리아쉬핑가제트","date":"2026-07-03","kSum":"부산항만공사(BPA)가 신임 건설본부장에 김호영 전 흥우산업 상무이사를 임명했다. 울산 출신인 김 본부장은 부산외국어대 회계학과를 졸업하고 한국마사회 등에서 경력을 쌓았다.","eSum":"Busan Port Authority (BPA) has appointed Kim Ho-young, former managing director of Heungwoo Industries, as its new head of construction. Kim previously worked at the Korea Racing Authority among other roles.","kImp":"부산항 인프라 확충 사업의 실무 책임자 교체로 항만 개발 속도에 영향을 줄 수 있다.","eImp":"Leadership change at BPA's construction division could affect the pace of Busan port infrastructure expansion.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147551"},{"code":"KR","title":"삼성중공업, 연간 수주액 5년 만에 100억달러 돌파","src":"코리아쉬핑가제트","date":"2026-07-08","kSum":"삼성중공업이 버뮤다 선사로부터 원유운반선 2척을 2849억원에 추가 수주하며 2021년 이후 5년 만에 연간 수주 100억달러를 돌파했다. 고부가가치 선박 수주 호조가 이어지고 있다.","eSum":"Samsung Heavy Industries surpassed $10 billion in annual orders for the first time since 2021 after winning a contract for two crude oil tankers worth 284.9 billion won from a Bermuda-based owner.","kImp":"국내 조선업 슈퍼사이클이 지속되고 있음을 보여주는 지표다.","eImp":"Reflects the continued shipbuilding supercycle benefiting Korean yards.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147581"},{"code":"KR","title":"대한해운 신임 대표이사에 민상기 전 건국대 총장 선임","src":"코리아쉬핑가제트","date":"2026-07-07","kSum":"SM그룹 해운부문 자회사 대한해운이 민상기 전 건국대학교 총장을 신임 대표이사로 선임했다. 대한해운은 7월6일 임시주주총회와 이사회를 열고 이 같이 결정했다.","eSum":"Korea Line Corporation, the shipping arm of SM Group, has appointed Min Sang-ki, former president of Konkuk University, as its new CEO, following an extraordinary shareholders' meeting and board meeting on July 6.","kImp":"국내 주요 벌크선사의 리더십 교체가 향후 경영전략 변화로 이어질지 주목된다.","eImp":"Leadership change at a major Korean bulk carrier could signal shifts in strategic direction.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147569"},{"code":"KR","title":"부산항만공사-산둥성항만그룹, 항만물류 협력 논의","src":"코리아쉬핑가제트","date":"2026-07-06","kSum":"부산항만공사(BPA)와 중국 산둥성항만그룹이 항만물류 협력 방안을 논의했다. HMM 부산사무소 관계자도 참석해 한중 항로 물동량 확대 방안을 협의했다.","eSum":"Busan Port Authority and China's Shandong Port Group discussed port logistics cooperation, with HMM's Busan office also participating in talks on expanding cargo volumes on Korea-China routes.","kImp":"한중 항만·물류 네트워크 강화가 부산항 경쟁력에 영향을 줄 수 있다.","eImp":"Strengthened Korea-China port logistics ties could bolster Busan's competitiveness.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147564"},{"code":"KR","title":"한국해운조합, 저탄소 선박연료 공급망 ISCC EU 인증 획득","src":"코리아쉬핑가제트","date":"2026-07-08","kSum":"한국해운조합(KSA)이 국제 지속가능성·탄소 인증(ISCC EU) 트레이더 부문 인증을 획득하고 국적 선사에 친환경 바이오선박유 정기 공급을 시작했다. 탄소중립 규제 대응이 목적이다.","eSum":"The Korea Shipping Association (KSA) has obtained ISCC EU trader certification and begun regular supply of eco-friendly bio-marine fuel to national flag carriers, aimed at meeting carbon-neutral regulations.","kImp":"국적선사의 탈탄소 연료 공급망이 제도적으로 뒷받침되기 시작했다.","eImp":"Marks institutional progress in decarbonized fuel supply for Korean-flagged carriers.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147578"},{"code":"KR","title":"서울권 민간 전문가들, 해사법원 활성화 추진위 결성","src":"코리아쉬핑가제트","date":"2026-07-08","kSum":"2년 후 개원 예정인 해사국제상사법원을 앞두고 서울권 민간 전문가들이 활성화 추진위원회를 결성했다. 7월8일 대법원에서 첫 회의를 열고 향후 운영 방안을 논의했다.","eSum":"Private-sector experts in the Seoul area have formed a committee to promote the upcoming International Maritime and Commercial Court, which is set to open in two years. The committee held its first meeting at the Supreme Court on July 8.","kImp":"해사법원 설립이 국내 해사분쟁 해결 역량 강화로 이어질 수 있다.","eImp":"Establishment of a maritime court could strengthen Korea's capacity to resolve shipping disputes domestically.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147579"},{"code":"KR","title":"'美동안 두자릿수 상승' 컨운임지수 SCFI 3326.87","src":"코리아쉬핑가제트","date":"2026-07-09","kSum":"성수기에 접어든 북미항로 호조로 상하이컨테이너운임지수(SCFI)가 10주 연속 상승, 7월3일자 3326.87을 기록했다. 전주 대비 3% 오른 수치로 미 동안 노선이 두자릿수 상승세를 이끌었다.","eSum":"The Shanghai Containerized Freight Index (SCFI) rose for a tenth straight week to 3326.87 as of July 3, up 3% week-on-week, driven by double-digit gains on US East Coast routes amid peak season demand.","kImp":"글로벌 컨테이너 운임 강세가 한국 수출입 물류비에 직접 영향을 미친다.","eImp":"Sustained container rate strength directly affects Korean exporters' logistics costs.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147580"},{"code":"KR","title":"佛 CMA CGM, 오만 Sohar 복합물류터미널 개발 협력","src":"코리아쉬핑가제트","date":"2026-07-07","kSum":"프랑스 선사 CMA CGM이 오만 국영 물류기업 Asyad Group과 Sohar 복합물류터미널 개발을 위한 기본협약을 체결했다. 총 투자 규모는 약 4억달러다.","eSum":"French carrier CMA CGM has signed a preliminary agreement with Oman's state logistics firm Asyad Group to jointly develop a multipurpose logistics terminal in Sohar, with a total investment of about $400 million.","kImp":"중동 항만 인프라 투자 확대는 아시아-유럽 물류망 재편에도 영향을 줄 수 있다.","eImp":"Expanded Gulf port infrastructure investment could reshape Asia-Europe logistics networks relevant to Korean exporters.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147568"},{"code":"KR","title":"\"중동전쟁 끝나면 컨선·탱크선 시황 하락세 탈 것\"","src":"코리아쉬핑가제트","date":"2026-07-07","kSum":"한국해사포럼 조찬 세미나에서 윤민현 고문은 중동 사태가 진정되면 컨테이너선·탱크선 시황은 공급 증가로 약세, 벌크선은 재건 수요로 호조를 보일 것으로 전망했다. HMM 김민강 상무는 단기 재건 수요 효과에 무게를 뒀다.","eSum":"At a Korea Maritime Forum breakfast seminar, adviser Yoon Min-hyun forecast that once Middle East tensions ease, container and tanker markets will weaken on rising supply while bulk carriers benefit from reconstruction demand.","kImp":"한국 해운업계 전문가들의 중동사태 이후 시황 전망은 선사들의 선대 전략 수립에 직접적 참고자료가 된다.","eImp":"Korean shipping industry experts' post-crisis market outlook directly informs Korean carriers' fleet strategy.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147553"},{"code":"KR","title":"양밍해운, HD현대중공업서 3번째 LNG추진 컨테이너선 확보","src":"코리아쉬핑가제트","date":"2026-07-07","kSum":"대만 선사 양밍해운이 HD현대중공업 울산조선소에서 세 번째 1만5600TEU급 LNG추진 컨테이너선 명명식을 가졌다. 정기선 HD현대 회장 등이 참석했으며, 신조선은 아시아-북유럽 항로에 투입된다.","eSum":"Taiwan's Yang Ming held a naming ceremony for its third 15,600 TEU LNG-fueled containership at HD Hyundai Heavy Industries' Ulsan yard, attended by HD Hyundai chairman Chung Ki-sun. The new vessel will serve the Asia-North Europe route.","kImp":"국내 조선소의 친환경 대형선 수주·인도 실적이 이어지고 있음을 보여준다.","eImp":"Highlights continued momentum for Korean yards in delivering large eco-friendly newbuilds.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147546"}]},{"code":"INS","type":"news","kTitle":"Section 12. H&M","eTitle":"Section 12. H&M","items":[{"code":"INS","title":"호르무즈서 유조선 피격, 취약한 항행 재개에 시험대","src":"Splash247","date":"2026-07-07","kSum":"정체불명의 발사체가 오만 인근 Limah 동쪽 8해리 지점에서 남하 중이던 유조선을 강타해 화재가 발생했다. 사상자나 오염은 없었으나 6월 정전협정 이후 조심스럽게 재개되던 상선 통항에 다시 그림자가 드리웠다.","eSum":"An unidentified projectile struck a southbound tanker roughly eight nautical miles east of Limah, Oman, sparking a fire. No casualties or pollution were reported, but the attack renewed doubts over the fragile post-ceasefire recovery of commercial transits.","kImp":"선체·전쟁위험 보험료 재상승 압력이 커지면서 재보험사들의 관망세가 강화될 전망이다.","eImp":"Renewed attacks are likely to reignite upward pressure on hull war-risk premiums and reinsurer caution.","url":"https://splash247.com/projectile-strike-tests-fragile-hormuz-recovery/"},{"code":"INS","title":"Willis \"호르무즈 사태, 해상보험 구조 영구히 바꿀 것\"","src":"Lloyd's List","date":"2026-07-08","kSum":"대형 보험중개사 Willis의 선체(Hull) 부문 대표는 전쟁위험과 일반 담보의 경계가 더 이상 유효하지 않다고 진단했다. 용선 여부에 따라 전쟁위험료 부담 능력이 갈리는 현상이 고착화되고 있다는 설명이다.","eSum":"Willis' head of hull warned that the historic distinction between war risk and core marine cover is no longer valid after the Hormuz crisis. Affordability of war premiums increasingly depends on whether a vessel is on timecharter or trading spot.","kImp":"전쟁위험 담보 체계 자체가 재설계될 경우 선주 보험료 구조 전반에 장기적 영향이 예상된다.","eImp":"A structural redesign of war-risk cover would have lasting implications for shipowners' overall insurance costs.","url":"https://www.lloydslist.com/LL1157497/Hormuz-fallout-will-change-marine-insurance-permanently-argues-Willis"},{"code":"INS","title":"호르무즈발 계약분쟁, 해운·해상보험업계 최대 현안으로","src":"Lloyd's List","date":"2026-07-09","kSum":"용선주와 선주가 전쟁 중에도 항해를 이행할 수 있었는지를 두고 이견을 보이면서 계약분쟁이 급증하고 있다. 선주·용선주·보험자 간 이해관계 충돌이 큰 파장을 낳을 수 있다는 경고가 나온다.","eSum":"Contract disputes are surging as charterers argue owners could and should have performed fixtures despite the war, while owners resist. The clash of commercial interests among owners, charterers and underwriters could have a potentially colossal impact.","kImp":"분쟁이 장기화될 경우 해상보험 클레임 처리 지연과 소송 비용 급증이 우려된다.","eImp":"Prolonged disputes risk delaying claims settlement and driving up litigation costs across the marine insurance chain.","url":"https://www.lloydslist.com/LL1157735/Hormuz-contract-disputes-shaping-up-as-huge-issue-for-shipping-and-marine-insurance"},{"code":"INS","title":"일부 전쟁보험사, 공격 이후 호르무즈 항해 잠정 중단 권고","src":"Insurance Journal","date":"2026-07-08","kSum":"최근 상선 공격이 재발하자 일부 전쟁위험 보험자들이 선주들에게 호르무즈 해협 항해를 일시 중단하라고 권고한 것으로 알려졌다. 다른 보험자들은 보험조건 재검토에 들어갔다.","eSum":"Some war-risk underwriters have advised shipowners to pause Hormuz voyages following renewed attacks on commercial ships, sources say, while others are reviewing policy terms.","kImp":"보험자들의 소극적 대응이 통항 정상화 지연으로 이어질 가능성이 크다.","eImp":"Underwriter caution could further delay the normalisation of transits through the strait.","url":"https://www.insurancejournal.com/news/international/2026/07/08/876716.htm"},{"code":"INS","title":"런던 해상보험시장, 7년 만에 '연성 시장' 진입","src":"Cyprus Shipping News","date":"2026-07-02","kSum":"BMS 보고서에 따르면 2018년 이후 이어진 경성 시장이 끝나고 런던 해상보험시장이 매수자 우위의 연성 국면에 진입했다. 선체보험료는 최대 10%까지 하락 중이나 전쟁위험은 별도 사이클로 여전히 고공행진 중이다.","eSum":"A BMS report says the London marine market has entered a soft phase after roughly seven years of hard-market remediation, with hull and machinery rates down up to 10%, even as Persian Gulf war-risk premiums remain on a separate, elevated cycle.","kImp":"선주들은 2026/27 갱신을 앞당겨 유리한 조건의 장기계약을 확보할 기회로 활용할 수 있다.","eImp":"Shipowners have a window to lock in favourable long-term hull agreements before the soft cycle potentially reverses.","url":"https://cyprusshippingnews.com/2026/07/02/marine-insurance-london-market-outlook/"},{"code":"INS","title":"IUMI, 이란-미국 양해각서 환영하며 중동 해상보험 지속 지원 확인","src":"IUMI","date":"2026-06-24","kSum":"국제해상보험연맹(IUMI)은 이란과 미국 간 양해각서 및 이란-오만 공동실무그룹 출범을 환영하며, 갈등 발생 이후에도 호르무즈 해협을 통항하려는 선주들에게 담보를 지속 제공해왔다고 밝혔다.","eSum":"IUMI welcomed the Iran-US memorandum of understanding and the Iran-Oman joint working group, stating the marine insurance market has continued providing cover for shipowners transiting the Strait of Hormuz since the conflict began in February 2026.","kImp":"국제 보험업계의 공식 입장 표명은 향후 담보 정상화 협상의 기준점이 될 전망이다.","eImp":"IUMI's formal stance sets a reference point for future negotiations on normalising war-risk cover.","url":"https://iumi.com/news/press-release/iumi-statement-marine-insurance-in-the-middle-east-updated-24-june-2026/"},{"code":"INS","title":"Allianz, 걸프 억류 선박·화물 가치 1,250억달러 달해","src":"Seatrade Maritime News","date":"2026-06-24","kSum":"Allianz Commercial의 '2026 해상안전보고서'에 따르면 6월 15일 기준 아라비아 걸프에 발이 묶인 화물선이 1,150척, 선박·화물 가치는 약 1,250억달러에 달한다.","eSum":"Allianz Commercial's Safety and Shipping Review 2026 found around 1,150 cargo vessels worth roughly $125bn were stranded in the Arabian Gulf as of 15 June, even as 2025 incident numbers fell 16%, with political risk now the industry's top safety concern.","kImp":"장기 정박에 따른 기계손상·생물오손 위험 증가로 향후 선체보험 클레임 비용 상승이 예상된다.","eImp":"Extended idling raises machinery breakdown and biofouling risks, likely pushing up future hull and machinery claims costs.","url":"https://www.seatrade-maritime.com/insurance/-125bn-trapped-by-hormuz-overshadows-improving-ship-safety-record"},{"code":"INS","title":"Lloyd's 언더라이터, 호르무즈 재개통 대비 6대 우선과제 제시","src":"TradeWinds","date":"2026-06-19","kSum":"미국-이스라엘-이란 양해각서로 호르무즈 해협 재개 가능성이 커지자 Lloyd's Market Association(LMA)은 이란산 원유 선적 및 통행료 지급 문제 등에 대한 추가 명확화가 필요하다고 밝혔다.","eSum":"As the memorandum signed by the US and Israel raised prospects of the Strait of Hormuz reopening, the Lloyd's Market Association said further clarity is needed on Iranian oil shipments and toll payments before underwriters can fully reprice cover.","kImp":"제재 관련 불확실성이 해소되지 않으면 보험 갱신 지연과 담보 공백이 지속될 수 있다.","eImp":"Unresolved sanctions ambiguity could prolong renewal delays and coverage gaps for Gulf transits.","url":"https://www.tradewindsnews.com/insurance/lloyd-s-underwriters-outline-six-priorities-as-strait-of-hormuz-reopens/2-1-2006576"},{"code":"INS","title":"정제유 탱커, 호르무즈 재개 기대에도 보험비용 부담 여전","src":"TradeWinds","date":"2026-06-17","kSum":"호르무즈 해협 재개 가능성이 제기됐지만 정제유 운반 탱커들은 여전히 보험 문제와 역내 정유시설 피해 불확실성에 시달리고 있다고 TradeWinds가 전했다.","eSum":"Even as a reopening of the Strait of Hormuz loomed, product tanker owners continue to face insurance issues alongside uncertainty over damage to regional refineries, TradeWinds reported.","kImp":"정제유 시장은 원유 탱커보다 회복이 더딜 수 있어 관련 선주들의 보험 부담이 상대적으로 오래 지속될 전망이다.","eImp":"The product tanker segment may recover more slowly than crude, leaving affected owners exposed to elevated insurance costs for longer.","url":"https://www.tradewindsnews.com/tankers/insurance-costs-cloud-product-tanker-outlook-as-strait-of-hormuz-opening-looms/2-1-2005349"},{"code":"INS","title":"호르무즈 전쟁위험시장, '돈 버는 시장' 아니라는 평가","src":"Insurance Business UK","date":"2026-06-24","kSum":"일부에서는 전쟁위험 보험자들이 막대한 수익을 올리고 있다는 인식이 있지만, 실제로는 손해율 변동성과 재보험 비용 부담으로 순이익이 크지 않다는 분석이 나왔다.","eSum":"Contrary to perceptions that war-risk underwriters are printing money from the Hormuz crisis, analysis suggests volatile loss ratios and reinsurance costs are limiting actual profitability in the market.","kImp":"수익성에 대한 오해가 향후 보험료 책정과 재보험 협상에 영향을 줄 수 있다.","eImp":"Misconceptions about profitability could shape future rate-setting and reinsurance treaty negotiations.","url":"https://www.insurancebusinessmag.com/uk/news/marine/the-hormuz-war-risk-market-isnt-printing-money--here-is-what-it-is-doing-580426.aspx"},{"code":"INS","title":"호르무즈 전쟁위험시장, 정전 시계 다시 째깍이며 불안한 국면","src":"Insurance Business UK","date":"2026-07-02","kSum":"60일 정전 2주째인 7월 1일 호르무즈 해협 통항량은 하루 5척으로 위기 전 평균 100척을 크게 밑돌았다. 전쟁위험료는 위기 전 대비 약 8배 수준을 유지하고 있으며 중앙 항로에는 여전히 기뢰가 남아있다.","eSum":"Two weeks into the 60-day ceasefire, just five vessels transited the Strait of Hormuz on 1 July versus a pre-crisis daily average of over 100. War risk pricing remains around eight times pre-crisis levels, with the central transit corridor still mined.","kImp":"지속적인 무사고 통항 기록이 쌓여야 보험료가 유의미하게 하락할 것으로 보험자들은 보고 있다.","eImp":"Underwriters say rates are unlikely to fall meaningfully until a sustained record of incident-free transits is established.","url":"https://www.insurancebusinessmag.com/uk/news/marine/hormuz-war-risk-market-enters-fragile-new-phase-as-ceasefire-clock-ticks-581067.aspx"}]},{"code":"PNI","type":"news","kTitle":"Section 13. P&I 클럽","eTitle":"Section 13. P&I Clubs","items":[{"code":"PNI","title":"Japan P&I Club, 제630회 이사회 개최","src":"Japan P&I Club","date":"2026-06-19","kSum":"일본선주상호보험조합(Japan P&I Club)은 6월 19일 제630회 이사회를 열어 클럽 운영 현안을 논의했다. 7월 21일 Kaiun Club에서 열릴 제76회 정기총회 소집도 함께 승인됐다.","eSum":"Japan P&I Club's Board of Directors held its 630th meeting on 19 June 2026, also approving the convening of the Club's 76th Ordinary General Meeting at Kaiun Club, Tokyo on 21 July.","kImp":"이사회 결정사항은 하반기 클럽 재무정책과 회원 규정 변경의 방향을 가늠하는 지표가 된다.","eImp":"Board decisions signal the club's direction on financial policy and rule changes for the second half of the year.","url":"https://www.piclub.or.jp/en/news/44462"},{"code":"PNI","title":"Skuld, 남서태평양 니켈광 안전운송 서큘러 발표","src":"Cyprus Shipping News","date":"2026-06-29","kSum":"P&I·헐보험을 겸영하는 Skuld는 남서태평양 해역 니켈광 화물의 액상화 위험과 안전 운송 지침을 담은 서큘러를 회원사에 배포했다. Gard, Japan P&I 등 다른 클럽들도 유사한 공동 서큘러를 냈다.","eSum":"Skuld issued a circular to members on the safe carriage of nickel ore cargoes in the south-western Pacific Ocean, addressing liquefaction risk, in a coordinated release alongside similar circulars from Gard, Japan P&I and other clubs.","kImp":"니켈광 액상화 사고가 반복되는 만큼 클럽 공동 지침이 선사의 화물 인수 절차 강화로 이어질 전망이다.","eImp":"With recurring nickel ore liquefaction casualties, the joint club guidance is likely to tighten cargo acceptance procedures across operators.","url":"https://cyprusshippingnews.com/2026/06/29/skuld-announces-safe-carriage-of-nickel-ore-cargoes-in-the-south-western-pacific-ocean/"},{"code":"PNI","title":"NorthStandard, 2025/26 보험연도 보험료 수입 5.8% 증가","src":"NorthStandard","date":"2026-05-28","kSum":"NorthStandard는 연례 리뷰를 통해 2025/26 보험연도 총 보험료 수입이 전년 대비 5.8% 증가한 9억3,800만달러를 기록했다고 밝혔다. 자유준비금도 1억2,300만달러 늘어난 9억2,300만달러로 집계됐다.","eSum":"NorthStandard's 2026 Annual Review reported total premium income of $938m for the 2025/26 policy year, up 5.8% year-on-year, while free reserves rose by $123m to $923m, strengthening capital well above S&P 'A' requirements.","kImp":"견조한 재무실적은 향후 갱신 협상에서 클럽의 협상력을 뒷받침할 것으로 보인다.","eImp":"The strong financial results should bolster the club's negotiating position at future renewals.","url":"https://north-standard.com/insights-and-resources/resources/press-releases/northstandard-achieves-stronger-results-and-growth-amid-global-shipping-challenges"},{"code":"PNI","title":"NorthStandard, 이란 제재 관련 일반허가 X 발효 안내","src":"NorthStandard","date":"2026-06-24","kSum":"NorthStandard는 미국 OFAC이 6월 22일 발효한 이란산 원유·석유화학제품 거래 허용 일반허가 X의 내용을 회원사에 안내하면서도, EU·영국 제재는 별도로 적용돼 담보 범위에 실질적 변화가 없다고 설명했다.","eSum":"NorthStandard briefed members on OFAC's General License X, issued 22 June 2026 authorising Iranian crude and petrochemical trade, but cautioned that independent EU and UK sanctions mean the club's cover position is largely unchanged.","kImp":"제재 완화가 부분적이고 유동적이어서 회원사들은 개별 항차마다 신중한 컴플라이언스 점검이 필요하다.","eImp":"Because the relief is partial and fluid, members must continue voyage-by-voyage sanctions compliance checks.","url":"https://north-standard.com/insights-and-resources/resources/news/iran-sanctions-update"},{"code":"PNI","title":"제재-보험 순환 딜레마, 호르무즈 재개의 최대 걸림돌","src":"Windward","date":"2026-06-17","kSum":"미국-이란 양해각서가 발효된 가운데 NorthStandard 제재담당 책임자는 이란의 안전통항 보장이나 걸프해운청 수수료를 지급받는 선박은 OFAC 지침상 어떤 P&I 클럽이나 전쟁보험자도 담보할 수 없는 '제재-보험 순환 딜레마'에 빠진다고 경고했다.","eSum":"With the US-Iran MoU in effect, NorthStandard's Head of Sanctions Function warned that any vessel accepting an Iranian safe-passage guarantee or paying the Persian Gulf Shipping Authority fee becomes uninsurable by any P&I club or war-risk underwriter under current OFAC guidance.","kImp":"제재-보험 순환 딜레마가 해소되지 않으면 통항 재개 속도 자체가 늦춰질 수 있다.","eImp":"Unless this sanctions-insurance circularity is resolved, the pace of the strait's reopening itself could be constrained.","url":"https://windward.ai/blog/hormuz-reopens-what-marine-insurers-are-facing/"},{"code":"PNI","title":"Gard, 중동 정세 격화가 걸프 해운에 미치는 영향 지속 갱신","src":"Gard","date":"2026-06-25","kSum":"Gard는 이스라엘-이란 갈등이 걸프 해운에 미치는 영향을 담은 인사이트 페이지를 지속 갱신하고 있으며, 6월 25일 기준 호르무즈 해협은 열려 있으나 GPS·GNSS 교란이 계속 보고되고 있다고 밝혔다.","eSum":"Gard continues to update its insight page tracking how the escalating Israel-Iran conflict affects Gulf shipping, noting that as of 25 June the Strait remained open but vessels continued reporting GPS and GNSS interference.","kImp":"항법장비 교란이 지속되면 좌초·충돌 위험이 커져 관련 P&I 클레임이 늘어날 가능성이 있다.","eImp":"Persistent navigation interference raises grounding and collision risk, potentially increasing related P&I claims.","url":"https://gard.no/en/insights/escalating-israel-iran-conflict-threatens-gulf-shipping/"},{"code":"PNI","title":"Steamship Mutual, 호르무즈 해협 회원사 대상 업데이트 발표","src":"Steamship Mutual","date":"2026-06-18","kSum":"미-이란 양해각서 이후 호르무즈 해협 통항이 조심스럽게 재개되는 가운데, Steamship Mutual은 위협수준이 '보통'으로 하향됐지만 기뢰 위험이 남아 있어 오만 영해를 통과하는 남측 항로를 권고한다고 안내했다.","eSum":"Steamship Mutual advised members that following the US-Iran MoU the maritime security threat level was downgraded to 'Moderate,' but mine risk persists, recommending the southern route through Omani territorial waters and avoidance of the International Traffic Separation Scheme.","kImp":"항로 권고를 따르지 않을 경우 보험담보 조건에 영향을 줄 수 있어 회원사의 항해계획 준수가 중요하다.","eImp":"Deviating from the club's routing guidance could affect cover terms, making compliance critical for members' voyage planning.","url":"https://www.steamshipmutual.com/publications/articles/strait-hormuz-update-members"},{"code":"PNI","title":"호르무즈 억류 선원 1만1,000명 대규모 대피 작전 시작","src":"UN News","date":"2026-06-24","kSum":"IMO가 주도하는 대규모 대피 작전이 시작되며 호르무즈 해협에 수개월간 발이 묶여 있던 1만1,000명 이상의 선원 구출이 본격화됐다. 이는 이란-미국 양해각서 체결과 직접 연계된 조치다.","eSum":"A UN-backed mass evacuation operation began extracting more than 11,000 seafarers stranded for months in the Strait of Hormuz, a move directly tied to the recently signed Iran-US memorandum of understanding.","kImp":"선원 송환·복지 관련 비용은 P&I 클럽의 인적 클레임 부담을 크게 늘릴 것으로 예상된다.","eImp":"Repatriation and welfare costs from the evacuation are expected to significantly add to P&I clubs' crew-related claims burden.","url":"https://news.un.org/en/story/2026/06/1167794"},{"code":"PNI","title":"Skuld, 걸프·홍해 해상안보 업데이트 지속 발표","src":"Skuld","date":"2026-07-05","kSum":"Skuld는 걸프 지역과 홍해의 해상안보 상황을 담은 업데이트를 발표하며, 이란의 고속단정을 이용한 선박 나포 시도가 미사일·드론·기뢰·전자교란과 결합된 다층적 위협으로 진화하고 있다고 경고했다.","eSum":"Skuld's maritime security update on the Gulf and Red Sea warned that Iran's use of fast-boat swarms to seize vessels near Hormuz has become part of a layered threat set alongside missiles, drones, mines and electronic interference.","kImp":"복합적 위협 평가는 회원사의 항로 선정과 보험 담보 조건 협상에 직접 반영될 전망이다.","eImp":"The multi-layered threat assessment is expected to directly inform members' routing decisions and cover negotiations.","url":"https://www.skuld.com/topics/port/port-news/asia/maritime-security-update-gulf-region--strait-of-hormuz-and-red-sea/"}]},{"code":"VET","type":"news","kTitle":"Section 14. 선박심사(Vetting)","eTitle":"Section 14. Vetting","items":[{"code":"VET","title":"Port Hedland, 5월부터 신규 선박 검사 보고 요건 시행","src":"SAFETY4SEA","date":"2026-05-14","kSum":"호주 Port Hedland가 2026년 5월 1일부터 입항 선박에 대해 표준화된 안전 보증 프레임워크를 도입, Vessel Vetting Form과 터미널별 사전접안 체크리스트 사용을 의무화했다. 점검은 입항 최대 30일 전부터 가능하며 접안 24~48시간 전 제출이 요구된다.","eSum":"From 1 May 2026, Port Hedland in Australia introduced a harmonized safety assurance framework requiring all calling vessels to use two mandatory forms: the Port Hedland Vessel Vetting Form and terminal-specific pre-berthing checklists.","kImp":"주요 벌크 수출항의 자체 베팅 요건 강화로 선사·용선주의 사전 서류 준비 부담이 커질 전망이다.","eImp":"The tightened port-level vetting requirement adds pre-arrival documentation burden for owners and charterers at a major bulk export hub.","url":"https://safety4sea.com/cm-new-reporting-requirements-effective-in-port-hedland-from-may-2026/"},{"code":"VET","title":"RightShip, AI 기반 검사 심각도 분류·클로즈아웃 절차 개편 예고","src":"RightShip","date":"2026-05-12","kSum":"RightShip은 Posidonia 2026과 연계해 개최한 그리스 포럼에서 검사 프레임워크 개편 방향을 공개했다. 저심각도 지적사항에 대한 의무 클로즈아웃 절차를 완화하고, PSC 분석에 적용 중인 AI 기반 심각도 분류 모델을 검사 전반으로 확대할 계획이다.","eSum":"At its inaugural Greece Forum held alongside Posidonia 2026, RightShip outlined upcoming changes to its inspection framework, including relaxed mandatory closeout requirements for low-severity findings and the extension of AI-supported severity classification models into inspections.","kImp":"검사 관련 행정 부담 완화와 AI 활용 확대는 향후 RISQ 및 Safety Score 운영 방식에 실질적 변화를 예고한다.","eImp":"The changes signal a practical shift in how RISQ and Safety Score assessments will be administered.","url":"https://rightship.com/insights/rightship-greece-forum-2026-advancing-rightship-inspections"},{"code":"VET","title":"Bureau Veritas, 아테네에 원격검사기법(RIT) 센터 신설","src":"Smart Maritime Network","date":"2026-05-21","kSum":"Bureau Veritas Marine & Offshore가 그리스 아테네에 7번째 원격검사기법(RIT) 센터를 개설했다. RIT는 검사원이 드론과 무인기(UAV)를 활용해 밸러스트탱크·화물창 등 밀폐구역을 점검하는 방식으로, 인력의 직접 진입 위험을 60~70% 줄인다.","eSum":"Bureau Veritas Marine & Offshore has launched its latest Remote Inspection Technique (RIT) centre in Athens, Greece, its seventh such centre globally, using drone and UAV technology to inspect confined spaces and cut entry risk by 60-70%.","kImp":"드론·AI 기반 원격점검 확산으로 감사 가능한 디지털 검사기록 제공이 표준화되고 있다.","eImp":"Drone- and AI-assisted remote inspection is standardizing auditable digital inspection records for owners, charterers and insurers.","url":"https://smartmaritimenetwork.com/2026/05/21/bureau-veritas-launches-remote-inspection-centre-in-athens/"},{"code":"VET","title":"OCIMF 연례보고서 2026…SIRE 2.0 시행 1년, 문화적 변화로 자리잡아","src":"SAFETY4SEA","date":"2026-05-22","kSum":"OCIMF 연차보고서 2026에 따르면 SIRE 2.0 도입 1년 만에 2만4,000건 이상의 검사가 완료됐으며, 단순한 기술적 개편을 넘어 검사 문화 전반의 변화로 평가된다. 다만 완전 디지털 체제 전환 과정에서 통신 문제와 하드웨어 편차 등 어려움도 있었다.","eSum":"According to OCIMF's Annual Report 2026, more than 24,000 SIRE 2.0 inspections have been completed one year after launch, marking a broader cultural shift, though the transition tested the industry through connectivity issues and hardware variability.","kImp":"SIRE 2.0의 안착은 인적요소 평가와 검사원-선원 간 소통 방식을 근본적으로 바꾸고 있다.","eImp":"SIRE 2.0's embedding is fundamentally reshaping human-factor assessment and inspector-crew engagement.","url":"https://safety4sea.com/ocimf-annual-report-2026-sire-2-0-impact-is-becoming-clear/"},{"code":"VET","title":"Northern Marine, Kaiko Systems 디지털 검사보고 플랫폼 전 선대 도입","src":"Smart Maritime Network","date":"2026-06-17","kSum":"Stena Group 산하 Northern Marine Management가 성공적인 파일럿 이후 Kaiko Systems의 디지털 검사보고 플랫폼을 관리 선대 전체에 도입하기로 했다. 우선 육상 검사팀을 지원하는 'Shore Reports' 툴부터 적용한다.","eSum":"Northern Marine Management, part of the Stena Group, has agreed to roll out Kaiko Systems' digital inspection reporting platform fleet-wide following a successful pilot, beginning with the Shore Reports tool supporting shore-based inspection teams.","kImp":"검사·베팅 대응 역량 강화를 위한 디지털 리포팅 도구 도입이 선사 전반으로 확산되고 있다.","eImp":"The rollout reflects a broader trend of shipowners adopting digital reporting tools to strengthen inspection and vetting readiness.","url":"https://smartmaritimenetwork.com/2026/06/17/northern-marine-rolls-out-digital-inspection-reporting-platform/"},{"code":"VET","title":"2026 SAFETY4SEA 어워드 후보 발표…RightShip 'RightFLEET' 노미네이트","src":"SAFETY4SEA","date":"2026-06-19","kSum":"2026 SAFETY4SEA 어워드 최종 후보가 발표된 가운데, RightShip은 검사·PSC 결과·사고·운항 신호를 하나의 지능형 화면으로 연결하는 AI 기반 솔루션 'RightFLEET'로 노미네이트됐다. 온라인 투표는 7월 17일까지 진행된다.","eSum":"SAFETY4SEA announced the shortlisted nominees for its 2026 Awards, with RightShip nominated for RightFLEET, an AI-powered solution connecting inspections, PSC outcomes, incidents and operational signals into a single intelligent view.","kImp":"AI 기반 리스크 예측 툴이 업계 표준 검사·베팅 솔루션으로 부상하고 있다.","eImp":"AI-driven risk-prediction tools are emerging as industry-standard inspection and vetting solutions.","url":"https://safety4sea.com/shortlisted-nominees-announced-for-the-2026-safety4sea-awards/"},{"code":"VET","title":"Guide2Inspections 앱, 선박 검사를 상시 훈련 도구로 전환","src":"Splash247","date":"2026-07-02","kSum":"싱가포르 Navguide Solutions가 개발한 'Guide2Inspections' 앱은 선내 자체 감사, 역할별 체크리스트, 짧은 동영상·사진 가이드를 하나로 묶은 오프라인 검사 훈련 도구다. MOL, KOTC, Meadway Bulkers 등 다수 선사가 도입했으며 RightShip, SIRE 2.0, PSC 결과 개선을 목표로 한다.","eSum":"Singapore-based Navguide Solutions launched Guide2Inspections, an offline app combining onboard self-audits, role-based checklists and short video/photo guidance to turn ship inspections into point-of-work training, adopted by MOL, KOTC and Meadway Bulkers.","kImp":"검사 준비를 형식적 서류작업이 아닌 상시적 학습 활동으로 전환해 결함 재발과 억류 위험을 줄일 수 있다.","eImp":"Turning inspection prep into continuous point-of-work training could cut repeat deficiencies and detention risk.","url":"https://splash247.com/navguide-solutions-turning-ship-inspections-into-training/"},{"code":"VET","title":"RightShip, Pilbara Ports 전용 기계류 검사 5월부터 개시","src":"RightShip","date":"2026-05-01","kSum":"RightShip이 2026년 5월 1일부터 Port Hedland 등 Pilbara Ports 기항 선박을 대상으로 전용 기계류 검사를 시작한다고 발표했다. Pilbara Ports가 3월 발행한 해양안전공고(PH 02/26)에 따른 표준화된 벳팅 양식·입항전 체크리스트 의무화에 대응한 조치다.","eSum":"RightShip announced it will conduct Pilbara Ports-specific machinery inspections from 1 May 2026, responding to new mandatory vetting-form and pre-berthing checklist requirements under Pilbara Ports Marine Safety Bulletin PH 02/26. Inspections are initially available in Singapore, China and Korea.","kImp":"Pilbara Ports 기항선은 표준화된 벳팅 양식과 트리거 기반 기계류 검사에 사전 대비해야 한다.","eImp":"Vessels calling at Pilbara Ports must now prepare for standardized vetting forms and trigger-based machinery inspections.","url":"https://rightship.com/insights/press-release-rightship-commences-pilbara-ports-vessel-machinery-inspections-from-1-may-2026"},{"code":"VET","title":"\"RightShip 검사·선원복지 자가평가를 실질적 안전장벽으로\"","src":"All About Shipping","date":"2026-06-26","kSum":"MARIN Shipmanagement 교육총괄 Martina Meinders는 RightShip 검사와 선원복지 자가평가(Crew Welfare Self-Assessment)를 단순 서류작업이 아닌 실질적 안전장벽으로 봐야 한다고 강조했다. RISQ 준비도 점검과 선원복지 평가를 하나의 상시 리듬으로 결합할 것을 권고했다.","eSum":"Martina Meinders of MARIN Shipmanagement argues RightShip inspections and Crew Welfare Self-Assessments should be a practical regulatory shield rather than paperwork, urging operators to integrate RISQ readiness checks and welfare assessments into one continuous rhythm.","kImp":"검사 준비를 형식적 절차가 아닌 실질적 안전관리 체계로 통합해야 한다는 업계 조언이다.","eImp":"An industry call to fold inspection readiness into genuine safety management rather than a box-ticking exercise.","url":"https://allaboutshipping.co.uk/2026/06/26/regulatory-shield-turning-rightship-readiness-into-safer-vessels/"},{"code":"VET","title":"RiSK4SEA PSI 지수, 6월 전 세계 PSC 단속 환경 전반적 악화 신호","src":"SAFETY4SEA","date":"2026-06-11","kSum":"PSC 인텔리전스 플랫폼 RiSK4SEA가 발표한 6월 PSC 스트레스지수(PSI)에 따르면 벌크선·탱커·일반화물선 등 주요 선종이 동시에 '심각 위험 구간(PSI-9)'에 진입했다. 일반화물선은 검사 1,140건 중 85건 억류로 7.46%의 최고 억류율을 기록했다.","eSum":"RiSK4SEA's June PSC Stress Index shows bulkers, tankers and general cargo simultaneously entering the PSI-9 Critical Risk Zone, with general cargo posting the highest detention rate at 7.46% (85 of 1,140 inspections).","kImp":"벳팅·용선 담당자는 데이터 기반 PSC 스트레스지수를 활용해 선종별 단속 강도 변화에 선제 대응해야 한다.","eImp":"Vetting and chartering teams should use data-driven PSC stress indices to anticipate enforcement swings by vessel segment.","url":"https://safety4sea.com/cm-risk4sea-psi-outlook-of-june-2026-signals-broad-deterioration-in-global-psc-enforcement-climate/"}]},{"code":"CLASS","type":"news","kTitle":"Section 15. 선급","eTitle":"Section 15. Classification Societies","items":[{"code":"CLASS","title":"DNV, HD현대중공업 VLGC용 독자 Type B LPG 화물탱크 설계에 AiP","src":"Hellenic Shipping News","date":"2026-06-05","kSum":"DNV가 HD현대중공업이 개발한 9만㎥급 독자형 Type B LPG 화물창 설계에 기본승인(AiP)을 부여했다. Posidonia 2026에서 발표된 이번 승인은 초대형 가스운반선(VLGC) 시장의 기술 경쟁력 강화로 이어질 전망이다.","eSum":"DNV granted an Approval in Principle to HD Hyundai Heavy Industries for its new 90,000 cbm independent Type B LPG containment system for VLGCs, unveiled at Posidonia 2026.","kImp":"독자형 화물창 기술 확보는 HD현대중공업의 차세대 가스운반선 수주 경쟁력을 높일 것으로 기대된다.","eImp":"Securing independent tank technology should strengthen HD Hyundai's competitiveness in next-generation gas carrier orders.","url":"https://www.hellenicshippingnews.com/dnv-awards-aip-to-hd-hyundai-heavy-industries-for-independent-type-b-lpg-cargo-tank-design-for-vlgcs/"},{"code":"CLASS","title":"ABS, MIT 컨소시엄 통해 개발된 선박용 원자로 통합설계 승인","src":"ABS","date":"2026-06-05","kSum":"ABS가 MIT Maritime Consortium을 통해 HD한국조선해양·Capital Maritime과 공동 개발한 화물선 추진용 원자로 통합설계에 최초로 기본승인(AiP)을 발급했다.","eSum":"ABS issued its first Approval in Principle through the MIT Maritime Consortium for integrating a nuclear reactor into a cargo vessel propulsion system, developed with HD KSOE and Capital Maritime.","kImp":"상선용 원자력 추진 기술 승인은 장기적으로 탈탄소 대형선 추진체계의 새로운 선택지로 주목받을 수 있다.","eImp":"The approval marks a milestone that could position nuclear propulsion as a long-term decarbonisation option for large merchant vessels.","url":"https://pressreleases.eagle.org/news/abs-grants-approval-for-nuclear-reactor-integration-in-vessel-design-developed-through-mit-maritime-consortium"},{"code":"CLASS","title":"LR, Wison New Energies의 가혹환경용 내부터렛 FPSO에 AiP 부여","src":"Lloyd's Register","date":"2026-05-13","kSum":"Lloyd's Register(LR)가 Wison New Energies가 설계한 가혹환경용 내부터렛 계류 방식 FPSO 설계에 기본승인을 수여했다. 이번 승인은 휴스턴 OTC에서 발표됐다.","eSum":"Lloyd's Register awarded an Approval in Principle to Wison New Energies for a harsh-environment FPSO design featuring an internal turret mooring system, unveiled at OTC Houston.","kImp":"가혹해역용 FPSO 기술 확보는 극한 환경 해양생산설비 시장에서 경쟁우위를 제공할 것으로 보인다.","eImp":"The harsh-environment FPSO technology should provide a competitive edge in extreme-condition offshore production markets.","url":"https://www.lr.org/en/knowledge/press-room/press-listing/press-release/2026/lloyds-register-grants-aip-to-wison-new-energies-for-harsh-environment-internal-turret-fpso/"},{"code":"CLASS","title":"사이버보안 디지털트윈 CYTUR-MG, LR 승인 획득","src":"Smart Maritime Network","date":"2026-05-26","kSum":"해양 사이버보안 디지털트윈 플랫폼 CYTUR-MG가 Lloyd's Register의 'Digital Twin Ready' 기본승인을 받았다. IACS 통일요건 UR E26/E27 준수를 지원하는 것이 특징이다.","eSum":"The maritime cybersecurity digital-twin platform CYTUR-MG received a Lloyd's Register 'Digital Twin Ready' Approval in Principle, supporting compliance with IACS Unified Requirements E26/E27.","kImp":"IACS 사이버복원력 요건이 본격 시행되는 가운데 관련 인증 솔루션 수요가 늘어날 것으로 예상된다.","eImp":"Demand for certified cyber-resilience solutions is expected to grow as IACS requirements take full effect.","url":"https://smartmaritimenetwork.com/2026/05/26/cytur-cyber-security-digital-twin-gets-lr-approval/"},{"code":"CLASS","title":"ClassNK, 선체구조 평가 소프트웨어 'PrimeShip-HULL 2026.1' 출시","src":"The Maritime Executive","date":"2026-05-29","kSum":"ClassNK가 CSR-B&T(공통구조기준) 평가 기능을 단일 인터페이스로 통합한 'PrimeShip-HULL 2026.1'을 출시했다. 선체구조 평가 작업의 효율성을 높이는 것이 목표다.","eSum":"ClassNK released PrimeShip-HULL 2026.1, integrating CSR-B&T evaluation functions into a unified interface for hull structural assessment.","kImp":"설계 검증 소프트웨어 고도화로 조선소의 구조설계 검토 기간이 단축될 것으로 기대된다.","eImp":"The upgraded design-verification software should shorten structural review turnaround times for shipyards.","url":"https://maritime-executive.com/corporate/classnk-releases-primeship-hull-2026-1"},{"code":"CLASS","title":"ClassNK, 영국 ETS 대응 배출량모니터링계획 42일 제출기한 안내","src":"PortNews","date":"2026-05-20","kSum":"ClassNK는 기술정보 TEC-1376을 통해 7월 1일 영국 해운 배출권거래제(UK ETS) 시행에 맞춰 영국 항만에 첫 기항하는 선박은 기항 후 42일 이내에 배출량 모니터링계획을 제출해야 한다고 안내했다.","eSum":"ClassNK issued Technical Information TEC-1376 requiring an emissions monitoring plan to be submitted within 42 days of a ship's first qualifying UK port call, as the UK ETS for shipping takes effect on 1 July 2026.","kImp":"새 규제 기한을 놓치는 선사는 과태료 등 컴플라이언스 리스크에 노출될 수 있다.","eImp":"Operators missing the new deadline risk penalties and compliance exposure under the UK ETS regime.","url":"https://en.portnews.ru/news/391754/"},{"code":"CLASS","title":"HD현대중공업-Bureau Veritas, 컨테이너선 횡동요 저감 시스템 공동개발","src":"Smart Maritime Network","date":"2026-06-04","kSum":"HD현대중공업과 프랑스 선급 Bureau Veritas가 컨테이너선의 과도한 횡동요를 억제하는 실시간 선상 안내 시스템 개발을 위한 공동개발프로젝트(JDP)에 착수했다.","eSum":"HD Hyundai Heavy Industries and Bureau Veritas launched a Joint Development Project for a real-time onboard guidance system designed to curb excessive rolling on container ships.","kImp":"횡동요 저감 기술은 초대형 컨테이너선의 화물 안전성과 운항 효율을 동시에 개선할 것으로 기대된다.","eImp":"The anti-rolling technology is expected to improve both cargo safety and operational efficiency for ultra-large container ships.","url":"https://smartmaritimenetwork.com/2026/06/04/hd-hyundai-heavy-industries-and-bv-partner-on-container-ship-stability/"},{"code":"CLASS","title":"Bureau Veritas-Shenzhen Port Group, 녹색해운항로 구축 협력 강화","src":"SAFETY4SEA","date":"2026-06-29","kSum":"Bureau Veritas와 중국 Shenzhen Port Group이 선전에서 전략적 협력협정을 체결하고 녹색해운항로(그린 코리도) 개발을 가속화하기로 했다.","eSum":"Bureau Veritas and Shenzhen Port Group signed a strategic cooperation agreement in Shenzhen to accelerate the development of green shipping corridors.","kImp":"항만-선급 간 협력 확대는 아시아 역내 탈탄소 항로 구축 속도를 높일 수 있다.","eImp":"Expanded port-classification society cooperation could accelerate decarbonised shipping corridor development in Asia.","url":"https://safety4sea.com/shenzhen-port-group-and-bv-join-forces-to-advance-green-corridors/"},{"code":"CLASS","title":"RINA, 에너지 하베스팅 선박에 최초 기본승인 부여","src":"RINA","date":"2026-05-20","kSum":"이탈리아 선급 RINA가 영국 스타트업 Drift Energy가 개발한 에너지 하베스팅 선박 콘셉트에 최초로 기본승인(AiP)을 수여했다. 이 선박은 심해 해상풍력을 이용해 그린수소를 생산하도록 설계됐다.","eSum":"RINA granted its first Approval in Principle for an energy-harvesting vessel concept developed by UK startup Drift Energy, designed to generate green hydrogen at sea using deep-ocean wind.","kImp":"해상 그린수소 생산선 개념 승인은 신재생에너지 기반 해상 생산 플랫폼 시장 개척의 신호탄이 될 수 있다.","eImp":"The approval could be an early signal for a new market in renewable-powered offshore hydrogen production platforms.","url":"https://www.rina.org/en/media/press/2026/05/20/drift-energy-approval-in-principle"},{"code":"CLASS","title":"한국선급(KR), 런던서 제21차 유럽위원회 회의 개최","src":"Hellenic Shipping News","date":"2026-06-29","kSum":"한국선급(KR)이 런던에서 제21차 유럽위원회 회의를 열고 IACS 활동 현황, AI 기반 탈탄소화 연구개발, 위원장 교체 등 안건을 논의했다.","eSum":"Korean Register hosted its 21st European Committee meeting in London, covering IACS activities, AI-driven decarbonisation R&D, and a change of committee chairmanship.","kImp":"유럽 지역 위원회 활동 강화는 KR의 유럽 선사·조선소와의 협력 확대로 이어질 전망이다.","eImp":"Strengthened European committee activity is expected to expand KR's cooperation with European owners and shipyards.","url":"https://www.hellenicshippingnews.com/kr-hosts-21st-european-committee-meeting-in-london/"},{"code":"CLASS","title":"인도선급(IRClass), 인도 최초 국산 전밀폐형 구명정에 형식승인","src":"The Maritime Executive","date":"2026-07-05","kSum":"인도선급(IRClass)이 뭄바이 SHM Shipcare가 제작한 인도 최초의 국산 전밀폐형 구명정 두 종에 대해 형식승인을 완료했다. 각각 탱커용 120인승, 50인승 모델로 IMO/SOLAS 기준에 따라 설계 심사와 시제품 시험을 거쳤다.","eSum":"Indian Register of Shipping completed Type Approval Certification for two indigenously built totally enclosed lifeboats by SHM Shipcare Mumbai - a 120-person and a 50-person tanker version - following design appraisal and prototype testing to IMO/SOLAS requirements.","kImp":"인도의 해양안전장비 국산화 역량 확보는 수입 의존도를 낮추고 공급망을 다변화하는 계기가 될 것으로 보인다.","eImp":"The milestone in indigenous safety-equipment manufacturing should reduce import dependence and diversify the maritime safety supply chain.","url":"https://maritime-executive.com/corporate/indian-register-of-shipping-awards-type-approval-certificate-to-india-s-first-indigenously-built-totally-enclosed-lifeboats"}]},{"code":"COMM","type":"news","kTitle":"Section 16. 시황·상품","eTitle":"Section 16. Markets & Commodities","items":[{"code":"COMM","title":"Wallenius Wilhelmsen, 자동차운반선 Tirranna에 Oceanbird 윙세일 실증","src":"Seatrade Maritime News","date":"2026-07-03","kSum":"Wallenius Wilhelmsen이 자동차운반선 Tirranna호에 설치한 Oceanbird 풍력보조추진 날개의 실해역 시험을 진행하고 있다. 연료 절감과 탄소배출 저감 효과가 기대된다.","eSum":"Wallenius Wilhelmsen is conducting sea trials of an Oceanbird wind-assisted propulsion wing installed on the car carrier Tirranna, aiming to demonstrate fuel savings and emissions reductions.","kImp":"PCTC 선대의 풍력추진 도입 시험은 향후 탄소중립 규제 대응의 상용화 가능성을 가늠하는 시험대다.","eImp":"The trial is a bellwether for commercial viability of wind propulsion across the PCTC fleet under tightening carbon rules.","url":"https://www.seatrade-maritime.com/technology/wallenius-wilhelmsen-trials-oceanbird-wind-wing-on-car-carrier"},{"code":"COMM","title":"현대글로비스, 세계 최대급 PCTC 3척 시대…시장 지배력 확대","src":"해사신문","date":"2026-07-08","kSum":"현대글로비스가 세계 최대급 PCTC 3척을 운용하며 완성차운반선 시장 지배력을 넓히고 있다. 글로벌 자동차 수출 물동량 증가에 따라 선대 확충 전략을 지속하고 있다.","eSum":"Hyundai Glovis is expanding its dominance in the PCTC market by operating three of the world's largest pure car and truck carriers, continuing a fleet expansion strategy amid rising global vehicle export volumes.","kImp":"한국 물류기업의 PCTC 시장 지배력 확대는 글로벌 자동차 운송 운임 형성에 영향을 미친다.","eImp":"A Korean logistics giant's expanding PCTC dominance influences global vehicle freight rate formation.","url":"https://haesanews.com/news/articleView.html?idxno=149153"},{"code":"COMM","title":"PCTC 신조 인도, 완성차 해상물류 수요와 균형 찾아간다","src":"Automotive Logistics","date":"2026-06-30","kSum":"유럽자동차물류협회(AEVL)에 따르면 신조 인도 증가로 자동차운반선 선복 공급이 수요와 균형을 이루고 있으며, 2026년에는 일부 공급과잉 가능성도 제기된다.","eSum":"According to the Association of European Vehicle Logistics, increased newbuild deliveries are rebalancing PCTC capacity with demand for maritime finished-vehicle transport, with some risk of oversupply emerging in 2026.","kImp":"선복 공급 증가는 최근 사상 최고치를 기록한 자동차운반선 용선료의 조정 가능성을 시사한다.","eImp":"Rising capacity points to a potential correction in car carrier charter rates after recent record highs.","url":"https://www.automotivelogistics.media/vehicle-logistics/vessel-operators-are-bringing-in-more-capacity-for-maritime-finished-vehicle-shipments/212292"},{"code":"COMM","title":"Diana Shipping, 개선된 조건으로 kamsarmax 용선 계약","src":"Splash247","date":"2026-07-08","kSum":"Diana Shipping이 kamsarmax급 벌크선에 대해 개선된 조건의 정기용선 계약을 체결했다. 벌크선 시황 개선이 반영된 결과로 풀이된다.","eSum":"Diana Shipping has secured an improved time charter for one of its Kamsarmax bulk carriers as the vessel rolls off its current employment, reflecting a firmer dry bulk market.","kImp":"벌크선 용선료 개선은 최근 벌크 시황 반등을 뒷받침하는 신호다.","eImp":"Improved charter terms confirm the recent uptick in dry bulk market sentiment.","url":"https://splash247.com/diana-secures-improved-kamsarmax-deal/"},{"code":"COMM","title":"발틱운임지수(BDI), 2개월 최저 후 저점 확인","src":"Baird Maritime","date":"2026-07-01","kSum":"발틱운임지수(BDI)가 2개월 만에 최저치를 기록한 후 반등하며 안정세를 찾고 있다. 케이프사이즈 구간 수요 회복이 주요 요인으로 꼽힌다.","eSum":"The Baltic Dry Index has stabilized after hitting a two-month low, with recovering Capesize demand cited as the main driver behind the rebound.","kImp":"벌크선 시황 저점 통과 신호는 원자재 운송 비용 전망에 영향을 준다.","eImp":"Signs of a bulk market bottom affect outlooks for raw material shipping costs.","url":"https://www.bairdmaritime.com/shipping/dry-cargo/bulkers/baltic-dry-bulk-index-finds-its-footing-after-hitting-two-month-low"},{"code":"COMM","title":"중국 철광석 공급 타이트화, BDI 랠리 촉발","src":"Baird Maritime","date":"2026-07-02","kSum":"중국의 철광석 공급 타이트화가 발틱운임지수 상승을 견인하고 있다. 케이프사이즈 운임이 특히 강세를 보이고 있다.","eSum":"Tighter iron ore supply into China has sparked a rally in the Baltic Dry Index, with Capesize rates showing particular strength.","kImp":"중국 철광석 수급 변화는 케이프사이즈 시황의 단기 방향성을 좌우하는 핵심 변수다.","eImp":"Shifts in China's iron ore supply-demand balance remain a key driver of near-term Capesize market direction.","url":"https://www.bairdmaritime.com/shipping/dry-cargo/bulkers/tighter-iron-ore-supply-in-china-sparks-baltic-dry-bulk-index-rally"},{"code":"COMM","title":"BDI, 케이프사이즈 강세에 2주 최고치","src":"Baird Maritime","date":"2026-07-03","kSum":"발틱운임지수가 케이프사이즈 강세에 힘입어 2주 만에 최고치로 올랐다. 원자재 물동량 회복이 벌크선 시황을 지지하고 있다.","eSum":"The Baltic Dry Index climbed to a two-week high driven by gains in Capesize rates, supported by a recovery in raw material trade volumes.","kImp":"벌크선 운임 강세 지속은 철광석·석탄 등 원자재 수출입 비용에 직접 영향을 준다.","eImp":"Continued strength in bulk rates directly affects the cost of iron ore, coal, and other commodity trade.","url":"https://www.bairdmaritime.com/shipping/dry-cargo/bulkers/baltic-dry-bulk-index-climbs-to-two-week-high-on-capesize-gains"},{"code":"COMM","title":"중국, 호르무즈 '자유 통항' 촉구…통행료 논란 확산","src":"gCaptain","date":"2026-07-03","kSum":"중국이 호르무즈해협의 자유 통항 보장을 촉구하고 나섰다. 이란의 통항료 부과 가능성이 거론되는 가운데 원유 수입 의존도가 높은 중국의 우려가 반영됐다.","eSum":"China has urged unimpeded passage through the Strait of Hormuz as speculation mounts over potential Iranian transit fees, reflecting Beijing's concern given its heavy reliance on Gulf oil imports.","kImp":"주요 원유 수입국의 압박은 호르무즈해협 통항료 부과 여부와 유조선 시황에 영향을 줄 수 있다.","eImp":"Pressure from a major oil importer could influence whether Hormuz transit fees materialize, affecting tanker markets.","url":"https://gcaptain.com/china-urges-unimpeded-passage-of-hormuz-as-fee-chatter-mounts/"},{"code":"COMM","title":"美 \"호르무즈 통과 하루 1,000만 배럴이 이란 레버리지 약화\"","src":"gCaptain","date":"2026-07-02","kSum":"미국은 호르무즈해협을 통한 하루 1,000만배럴 원유 수송이 이란의 협상 레버리지를 약화시키고 있다고 평가했다. 대체 공급 경로 확대가 이란의 위협 효과를 상쇄하고 있다는 분석이다.","eSum":"The US assesses that roughly 10 million barrels per day still moving through the Strait of Hormuz is eroding Iran's negotiating leverage, as alternative supply routes offset the impact of Iranian threats.","kImp":"원유 물동량 데이터는 호르무즈 리스크가 실제 공급망에 미치는 영향을 가늠하는 핵심 지표다.","eImp":"Oil flow data through Hormuz is a key gauge of how much the crisis is actually disrupting supply chains.","url":"https://gcaptain.com/us-sees-10-million-barrels-via-hormuz-sapping-iran-oil-leverage/"},{"code":"COMM","title":"일본 중동산 원유 도입, 7월 회복 전망","src":"gCaptain","date":"2026-07-07","kSum":"호르무즈해협에 발이 묶였던 유조선들이 빠져나오면서 일본의 중동산 원유 도입량이 7월 들어 회복세를 보일 전망이다. MOL·NYK 등 일본 선사 관련 선박들이 대거 포함됐다.","eSum":"Japan's crude oil imports from the Middle East are set to rebound in July as tankers previously stranded in the Strait of Hormuz begin to exit, with vessels linked to MOL and NYK among those affected.","kImp":"주요 아시아 원유 수입국의 공급 정상화는 지역 유조선 시황 완화 신호로 해석된다.","eImp":"Normalizing supply to major Asian oil importers signals easing pressure on regional tanker markets.","url":"https://gcaptain.com/japans-mideast-crude-supply-to-rebound-in-july-as-stranded-vessels-exit-hormuz/"},{"code":"COMM","title":"주간 탱커·벌크선 정기용선료 동향 (7월 1일)","src":"Seatrade Maritime News","date":"2026-07-01","kSum":"주간 탱커·벌크선 정기용선료 동향에 따르면 호르무즈 리스크 속에서도 유조선 용선료는 견조하며 벌크선 용선료도 소폭 개선됐다.","eSum":"The weekly tanker and dry bulk time charter rate roundup shows tanker rates holding firm despite Hormuz-related risk, with dry bulk charter rates also showing modest improvement.","kImp":"주간 용선료 동향은 지정학적 리스크가 실제 운임 시장에 미치는 영향을 가늠하게 하는 지표다.","eImp":"Weekly charter rate data offers an ongoing gauge of how geopolitical risk is translating into actual freight market moves.","url":"https://www.seatrade-maritime.com/tankers/weekly-tanker-and-dry-bulk-time-charter-rates-1-july"}]},{"code":"GEO","type":"news","kTitle":"Section 17. 지정학","eTitle":"Section 17. Geopolitics","items":[{"code":"GEO","title":"카타르, 호르무즈 LNG선 피격 배후로 이란 지목","src":"The National","date":"2026-07-07","kSum":"카타르가 호르무즈해협 인근에서 LNG운반선 Al Rekayyat호 피격 사건의 배후로 이란을 지목했다. 7월 7일 재개된 공격으로 지역 긴장이 다시 고조되고 있다.","eSum":"Qatar has blamed Iran for an attack on the LNG tanker Al Rekayyat near the Strait of Hormuz, as renewed strikes on July 7 have reignited regional tensions after a brief lull.","kImp":"LNG선 피격은 카타르발 LNG 공급망 리스크를 부각시키며 글로벌 에너지 시장에 파장을 줄 수 있다.","eImp":"An LNG tanker attack spotlights supply chain risk from Qatar, with potential ripple effects across global energy markets.","url":"https://www.thenationalnews.com/gulf-news/qatar/2026/07/07/qatar-blames-iran-lng-tanker-hormuz/"},{"code":"GEO","title":"호르무즈서 피격된 CMA CGM 선박, 해체 처리 가능성","src":"gCaptain","date":"2026-07-04","kSum":"호르무즈해협에서 미사일 공격을 받은 CMA CGM 소속 선박이 손상 정도가 심해 해체(스크랩) 처리될 가능성이 제기됐다. 컨테이너선 피격 사례가 이어지며 보험업계의 부담도 커지고 있다.","eSum":"A CMA CGM vessel hit by a missile in the Strait of Hormuz may be sent for scrapping due to severe damage, as a growing string of containership strikes adds to mounting pressure on the marine insurance sector.","kImp":"컨테이너선의 전손 처리 가능성은 전쟁위험보험료 상승과 항로 회피 결정을 가속화할 수 있다.","eImp":"The prospect of a total-loss writeoff could accelerate rising war-risk premiums and further route avoidance.","url":"https://gcaptain.com/cma-cgm-ship-hit-by-missile-in-hormuz-strait-may-go-for-scrapping/"},{"code":"GEO","title":"호르무즈 셔틀 운항으로 수백만 달러 버는 탱커 선주들","src":"Bloomberg","date":"2026-07-05","kSum":"일부 탱커 선주들이 호르무즈해협 리스크 프리미엄을 활용한 셔틀 운항으로 막대한 수익을 올리고 있다는 보도가 나왔다. 위험을 감수한 소규모 선사들이 반사이익을 누리는 모습이다.","eSum":"A report details how certain tanker owners are earning outsized profits from high-risk shuttle runs through the Strait of Hormuz, capitalizing on war-risk premiums that larger, more risk-averse operators avoid.","kImp":"위험 프리미엄을 노린 틈새 운항 전략은 유조선 시장의 양극화를 심화시키고 있다.","eImp":"Niche high-risk shuttle strategies are deepening polarization within the tanker market.","url":"https://www.bloomberg.com/news/features/2026-07-05/the-tanker-tycoon-making-millions-on-hormuz-shuttle-runs"},{"code":"GEO","title":"우크라이나, 러시아 '그림자 선단' 유조선 8척 공격","src":"The Washington Times","date":"2026-07-07","kSum":"우크라이나가 러시아의 제재 회피용 '그림자 선단' 유조선 8척을 겨냥한 공격을 감행했다고 밝혔다. 러시아 원유 수출 차단을 위한 압박이 강화되고 있다.","eSum":"Ukraine says it targeted eight tankers belonging to Russia's sanctions-evading 'shadow fleet,' as Kyiv escalates pressure aimed at disrupting Russian oil exports.","kImp":"그림자 선단에 대한 직접 공격은 러시아 원유 수출 물류에 새로운 리스크 요인으로 부상하고 있다.","eImp":"Direct strikes on the shadow fleet introduce a new risk factor for Russian oil export logistics.","url":"https://www.washingtontimes.com/news/2026/jul/7/ukraine-targets-eight-russian-shadow-fleet-tanker/"},{"code":"GEO","title":"우크라이나 당국, 그림자 선단 유조선 8척 타격 공식 발표","src":"US News & World Report","date":"2026-07-07","kSum":"우크라이나 당국이 러시아 그림자 선단 소속 유조선 8척에 대한 타격을 공식 발표했다. 서방 제재를 우회해온 러시아산 원유 수송망에 직접적 타격이 가해진 사례다.","eSum":"Ukrainian authorities have officially announced strikes on eight tankers belonging to Russia's shadow fleet, marking a direct hit on the network Moscow has used to circumvent Western sanctions on oil exports.","kImp":"제재 회피 선단에 대한 군사적 대응은 러시아산 원유 물류의 안전성과 보험 조건에 즉각적 영향을 미친다.","eImp":"Military action against the sanctions-evasion fleet has immediate implications for the safety and insurability of Russian oil logistics.","url":"https://www.usnews.com/news/world/articles/2026-07-07/ukraine-strikes-eight-russian-shadow-fleet-tankers-kyiv-says"},{"code":"GEO","title":"美의 중국산 선박 입항료, 독일 조선·해운에 반사이익 가능성","src":"93.3 The Drive","date":"2026-07-08","kSum":"미국이 추진 중인 중국산 선박 대상 입항료 부과 정책이 독일 조선·해운업계에 반사이익을 줄 수 있다는 분석이 나왔다. 선사들의 선대 조달 전략 변화가 예상된다.","eSum":"Analysts say Germany could benefit from planned US port fees targeting China-built vessels, as shipowners may shift newbuilding and chartering strategies away from Chinese-built tonnage.","kImp":"미중 해운 갈등이 조선·해운 공급망 재편을 촉발하는 흐름을 보여준다.","eImp":"Highlights how the US-China shipping standoff is beginning to reshape global shipbuilding and fleet-sourcing patterns.","url":"https://933thedrive.com/germany-could-gain-from-planned-us-port-fees-on-china-built-ships/"},{"code":"GEO","title":"호르무즈, 유조선 피격에 美 공습 촉발되며 다시 위기 국면","src":"Splash247","date":"2026-07-08","kSum":"호르무즈해협이 잇단 유조선 피격 이후 미국의 이란 표적 공습으로 다시 위기 국면에 진입했다. 6월 17일 정전 양해각서 이후 유지되던 긴장 완화 흐름이 무너졌다.","eSum":"The Strait of Hormuz has returned to crisis mode after a series of tanker attacks triggered fresh US strikes on Iranian targets, unraveling the fragile de-escalation that had followed the June 17 ceasefire memorandum.","kImp":"휴전 체제의 붕괴 조짐은 해운업계에 항로 재우회와 보험료 재상승 압박을 가한다.","eImp":"Signs of the ceasefire unraveling pressure shipping to resume rerouting and drive war-risk premiums higher again.","url":"https://splash247.com/hormuz-returns-to-crisis-mode-after-tanker-attacks-trigger-us-strikes/"},{"code":"GEO","title":"중동 해상위기 장기화…IMO \"걸프 해역에 선원 6,000명 고립\"","src":"해사신문","date":"2026-07-09","kSum":"국제해사기구(IMO)가 걸프 해역에 약 6,000명의 선원이 고립돼 있다고 밝히며 중동 해상위기 장기화에 우려를 표했다. 국제사회의 공동 대응 필요성이 제기되고 있다.","eSum":"The International Maritime Organization (IMO) has warned that around 6,000 seafarers remain stranded in Gulf waters as the Middle East maritime crisis drags on, calling for coordinated international action.","kImp":"IMO의 공식 경고는 중동 해상위기가 장기 구조적 문제로 굳어지고 있음을 시사한다.","eImp":"The IMO's formal warning suggests the Middle East maritime crisis is hardening into a prolonged structural problem.","url":"https://haesanews.com/news/articleView.html?idxno=149196"},{"code":"GEO","title":"JMIC, 호르무즈 해협 위협등급 '심각'으로 상향","src":"Seatrade Maritime News","date":"2026-07-07","kSum":"합동해상정보센터(JMIC)가 호르무즈해협의 위협 수준을 '심각' 단계로 상향 조정했다. 최근 며칠간 이어진 공격이 평가 상향의 배경으로 꼽힌다.","eSum":"The Joint Maritime Information Center (JMIC) has raised its threat assessment for the Strait of Hormuz to 'severe,' citing the recent string of attacks on commercial vessels in the waterway.","kImp":"공식 위협등급 상향은 선사들의 항로 회피와 전쟁위험보험료 재산정을 촉발할 수 있다.","eImp":"The formal threat-level escalation could prompt further route avoidance and a fresh repricing of war-risk insurance.","url":"https://www.seatrade-maritime.com/security/jmic-raises-strait-of-hormuz-threat-level-to-severe"}]},{"code":"TW","type":"news","kTitle":"Section 18. TradeWinds","eTitle":"Section 18. TradeWinds","items":[{"code":"TW","title":"D'Amico International, 2년 초고수익 탱커 용선 계약 체결","src":"TradeWinds","date":"2026-07-06","kSum":"D'Amico International Shipping(DIS)이 MR2 탱커를 2년간 '매우 수익성 높은' 요율로 용선 계약했다. 이번 계약으로 2026년 하반기 가용 선복의 53%가 평균 TCE 약 2만3,700달러로 확보됐다.","eSum":"D'Amico International Shipping fixed an MR2 product tanker for two years at what it called a highly profitable rate. The fixture lifts the company's 2026 period coverage to 53% at an average TCE of about $23,700 per day.","kImp":"탱커 시장 강세 속 선사들이 장기 계약으로 수익을 선제적으로 확보하고 있음을 보여준다.","eImp":"The deal underscores how tanker owners are locking in strong rates through period charters amid a firm market.","url":"https://www.tradewindsnews.com/tankers/d-amico-international-fixes-tanker-for-two-years-at-highly-profitable-rate/2-1-2013739"},{"code":"TW","title":"전 세계 분쟁에 휘말린 해운업, 선원 사망자 수 공개","src":"TradeWinds","date":"2026-07-06","kSum":"TradeWinds가 우크라이나·러시아, 호르무즈 해협 등 각지 분쟁으로 인한 선원 사상자 집계를 공개했다. IMO에 따르면 2월 28일 이후 호르무즈 인근에서 46건의 상선 공격이 발생해 최소 14명이 사망했다.","eSum":"TradeWinds reported that shipping has been increasingly dragged into global conflicts, with the IMO confirming 46 attacks on shipping around the Strait of Hormuz since 28 February resulting in at least 14 seafarer deaths.","kImp":"상선과 선원이 지정학적 분쟁의 직접적 표적이 되는 추세가 심화하고 있다.","eImp":"The report highlights the growing exposure of merchant seafarers to direct harm from geopolitical conflict.","url":"https://www.tradewindsnews.com/people/shipping-dragged-into-global-wars-as-seafarer-death-toll-revealed/2-1-2012797"},{"code":"TW","title":"ADNOC, 글로벌 LNG 마케팅·트레이딩 플랫폼 출범","src":"TradeWinds","date":"2026-07-06","kSum":"아부다비국영석유공사(ADNOC)가 ADGM에 ADNOC Gas와 XRG의 마케팅 기능, ADNOC Trading의 트레이딩 역량을 통합한 글로벌 LNG 마케팅·트레이딩 플랫폼을 출범했다. 2035년까지 연간 4,700만톤 판매를 목표로 한다.","eSum":"ADNOC has launched an integrated global LNG marketing and trading platform in ADGM, combining ADNOC Gas and XRG's marketing activities with ADNOC Trading, targeting 47 million tonnes per year of marketable LNG by 2035.","kImp":"아부다비를 글로벌 에너지 트레이딩 허브로 키우려는 전략의 핵심 축이다.","eImp":"The move is central to Abu Dhabi's push to become a leading global LNG trading hub.","url":"https://www.tradewindsnews.com/gas/adnoc-launches-new-lng-marketing-and-trading-platform/2-1-2013499"},{"code":"TW","title":"BW LNG, 세계 최초 3탱크 대형 LNG선 4척 발주","src":"TradeWinds","date":"2026-07-06","kSum":"BW LNG가 세계 최초로 3개 화물창을 갖춘 대형 LNG선 신조 4척을 발주했다. GTT가 탱크 설계를 맡았으며, 탱크 용적을 늘려 적재량을 17만4,000㎥에서 17만7,000㎥로 확대했다. 인도는 2028년 4분기부터 시작된다.","eSum":"BW LNG has ordered the world's first large-scale three-cargo-tank LNG carriers, with GTT designing tanks that boost capacity by 3,000 cbm to 177,000 cbm versus the standard four-tank 174,000-cbm design, with deliveries starting Q4 2028.","kImp":"LNG선 설계 혁신이 화물 효율성과 운영비 절감 경쟁을 촉발하고 있다.","eImp":"The design shift signals intensifying competition on cargo efficiency in LNG newbuildings.","url":"https://www.tradewindsnews.com/gas/lng-carriers-four-tanks-good-three-tanks-even-better-bw-lng-says/2-1-2012992"},{"code":"TW","title":"Capital Tankers, Frontline 대비 NAV 할인폭 '과도' - Arctic Securities","src":"TradeWinds","date":"2026-07-06","kSum":"Arctic Securities가 Marinakis가 이끄는 Capital Tankers의 순자산가치(NAV) 대비 주가 할인폭이 경쟁사 Frontline과 비교해 지나치게 크다고 평가했다. VLCC 부문에서의 밸류에이션 격차가 투자 매력도를 높인다는 분석이다.","eSum":"Arctic Securities said Capital Tankers' share price discount to net asset value is too wide compared with Frontline, highlighting a valuation gap in the VLCC segment for the Marinakis-backed owner.","kImp":"탱커 상장사 간 밸류에이션 격차가 투자자들의 관심을 끌고 있다.","eImp":"The valuation gap between listed tanker owners is drawing renewed investor attention.","url":"https://www.tradewindsnews.com/tankers/capital-tankers-nav-discount-too-wide-to-frontline-arctic-says/2-1-2013483"},{"code":"TW","title":"EGPN Bulk, 첫 컨테이너선 진출…피더선 2척 발주","src":"TradeWinds","date":"2026-07-07","kSum":"벌커 선사 EGPN Bulk가 CSSC Huangpu Wenchong 조선소에 1,900TEU급 피더 컨테이너선 2척을 발주하며 처음으로 컨테이너선 부문에 진출했다.","eSum":"Bulker owner EGPN Bulk has entered the feeder container ship segment for the first time, ordering two 1,900-teu feeder boxships from CSSC Huangpu Wenchong Shipbuilding.","kImp":"벌커 전업 선사들의 컨테이너선 다각화 움직임이 확산하고 있다.","eImp":"The order reflects a wider trend of dry-bulk owners diversifying into container shipping.","url":"https://www.tradewindsnews.com/containers/egpn-bulk-makes-debut-container-ship-move/2-1-2013895"},{"code":"TW","title":"상반기 LNG선 발주 60척 육박, 시장 예상 뛰어넘어","src":"TradeWinds","date":"2026-07-01","kSum":"2026년 상반기 LNG선 신조 발주가 60척에 육박하며 시장 예상을 크게 웃돌았다. 하반기 발주 전망은 상대적으로 불확실하다는 평가다.","eSum":"LNG carrier newbuilding orders surprised on the upside in the first half of 2026 with a near 60-ship haul, though the outlook for ordering in the second half remains less certain.","kImp":"LNG 운반선 발주 호황이 조선업 수주 잔량을 계속 밀어올리고 있다.","eImp":"The LNG carrier ordering boom continues to swell shipyard orderbooks globally.","url":"https://www.tradewindsnews.com/gas/lng-carrier-newbuildings-surprise-with-near-60-ship-haul-in-first-six-months/2-1-2011601"},{"code":"TW","title":"그리스 선주, 이라크 원유 선구적 선적용 탱커 예약설 부인","src":"TradeWinds","date":"2026-07-07","kSum":"한 그리스 선주가 이라크산 원유의 선구적 선적을 위해 탱커를 예약했다는 보도를 부인했다. 호르무즈 해협 관련 긴장 속에서 이라크발 원유 물류 재편 가능성이 시장의 관심을 끌고 있다.","eSum":"A Greek shipowner has denied reports that a tanker was booked for pioneering Iraqi crude loading, as market attention focuses on potential shifts in Iraqi crude logistics amid Strait of Hormuz tensions.","kImp":"호르무즈 불확실성이 이라크발 원유 물류 재편 가능성까지 시장에 파장을 일으키고 있다.","eImp":"Hormuz uncertainty is rippling into speculation over new Iraqi crude export logistics.","url":"https://www.tradewindsnews.com/tankers/greek-owner-denies-tanker-booked-for-pioneering-iraqi-crude-loading/2-1-2014269"},{"code":"TW","title":"Hayfin, 11척 오프쇼어 선단 매각","src":"TradeWinds","date":"2026-07-08","kSum":"Hayfin Capital Management가 앵커핸들링 예인공급선 등 11척 규모 오프쇼어 선단을 대형 해운 투자자들에게 매각했다. 오프쇼어 지원선 시장의 자산 재편이 이어지고 있다.","eSum":"Hayfin Capital Management has sold an 11-vessel offshore support fleet, including anchor handling tug supply vessels, to leading shipping investors, in the latest asset reshuffling in the offshore segment.","kImp":"오프쇼어 지원선 시장에서 자산 매각과 투자 유입이 활발해지고 있다.","eImp":"The sale reflects continued asset churn and fresh investor interest in the offshore support vessel market.","url":"https://www.tradewindsnews.com/offshore/hayfin-sells-11-vessel-offshore-fleet-to-leading-shipping-investors/2-1-2014616"},{"code":"TW","title":"Baltic Exchange, VLCC 요율 갈등에 존립 위협받나","src":"TradeWinds","date":"2026-07-05","kSum":"VLCC 운임 산정을 둘러싼 논란이 격화하며 Baltic Exchange 지수의 신뢰성에 대한 의문이 제기되고 있다. 시장 참여자들 사이에서 벤치마크 방법론을 둘러싼 갈등이 커지는 모습이다.","eSum":"A row over VLCC rate assessments is raising questions about the credibility of Baltic Exchange indices, as market participants clash over benchmark methodology.","kImp":"벤치마크 신뢰성 논란은 탱커 시장 계약 관행 전반에 영향을 줄 수 있다.","eImp":"The credibility dispute could have wider implications for tanker market contracting practices.","url":"https://www.tradewindsnews.com/tankers/is-the-baltic-facing-existential-damage-from-vlcc-rate-row-/2-1-2012972"},{"code":"TW","title":"멕시코 Energia Costa Azul 터미널, 첫 LNG 수출 화물 선적","src":"TradeWinds","date":"2026-07-07","kSum":"멕시코 태평양 연안의 Energia Costa Azul LNG 터미널에서 첫 수출용 LNG 화물이 선적됐다. Sempra Infrastructure와 TotalEnergies가 관여한 프로젝트다.","eSum":"An LNG carrier has loaded the first export cargo from the Energia Costa Azul terminal in Mexico, a Sempra Infrastructure and TotalEnergies project, marking a milestone in North American LNG export diversification.","kImp":"태평양 연안 LNG 수출 터미널 가동은 아시아향 수출 경로 다변화에 기여한다.","eImp":"The Pacific-coast LNG terminal's startup helps diversify export routes toward Asian buyers.","url":"https://www.tradewindsnews.com/gas/lng-carrier-loads-first-export-cargo-from-energia-costa-azul-terminal/2-1-2014348"}]},{"code":"HOT","type":"news","kTitle":"Section 19. 호르무즈 위기","eTitle":"Section 19. Strait of Hormuz Crisis","items":[{"code":"HOT","title":"카타르 LNG선 호르무즈서 피격, 美-이란 협상 시험대","src":"gCaptain","date":"2026-07-07","kSum":"카타르 LNG선이 호르무즈 해협을 빠져나오던 중 오만 인근에서 발사체에 피격됐다. 이번 공격으로 미국-이란 간 정전 합의의 실효성이 시험대에 올랐으며, 선사들의 불안이 고조되고 있다.","eSum":"A laden Qatari LNG carrier was hit by a projectile near the Omani coast while exiting the Strait of Hormuz, testing a fragile US-Iran agreement meant to halt attacks and rattling shipowners.","kImp":"정전 합의 이후에도 공격이 계속되며 호르무즈 항행 안전에 대한 신뢰가 흔들리고 있다.","eImp":"Continued attacks despite the ceasefire are eroding confidence in the safety of Hormuz transits.","url":"https://gcaptain.com/qatari-lng-ship-struck-in-strait-of-hormuz-testing-us-talks/"},{"code":"HOT","title":"호르무즈 기뢰제거 임무 차질, 유럽 소해작전 위태","src":"gCaptain","date":"2026-07-08","kSum":"영국·프랑스가 오만의 허가를 받아 추진하던 호르무즈 해협 남부항로 기뢰제거 작전이 최근 공격으로 차질을 빚고 있다. 유럽 해군의 소해 임무 지속 여부가 불투명해졌다.","eSum":"UK and French plans to de-mine the southern Strait of Hormuz route, recently approved by Oman, have been set back by fresh attacks on shipping, clouding the outlook for the European de-mining mission.","kImp":"기뢰제거 작전 지연은 안전 항로 복구를 더욱 늦출 수 있다.","eImp":"Delays to the de-mining effort could further postpone the restoration of safe transit corridors.","url":"https://gcaptain.com/hormuz-strikes-threaten-progress-on-europes-de-mining-mission/"},{"code":"HOT","title":"오만 인근서 상선 2척 추가 피격","src":"Seatrade Maritime News","date":"2026-07-07","kSum":"오만 인근 호르무즈 해협에서 상선 2척이 각각 별도의 공격을 받았다. 한 척은 정체불명 발사체에, 다른 한 척은 무인기(UAV)에 피격돼 경미한 구조적 손상을 입었다.","eSum":"Two commercial ships were attacked off the coast of Oman in the Strait of Hormuz, one hit by an unknown projectile and the other struck by an uncrewed aerial vehicle, sustaining minor structural damage.","kImp":"무인기까지 동원된 공격 양상은 위협의 다변화를 보여준다.","eImp":"The use of a UAV in one of the attacks signals a diversification of the threat facing merchant ships.","url":"https://www.seatrade-maritime.com/security/two-more-tankers-attacked-in-hormuz-off-oman"},{"code":"HOT","title":"호르무즈 공격에 유조선들 잇단 회항","src":"MarineLink","date":"2026-07-08","kSum":"최소 4척의 유류·가스 탱커가 호르무즈 해협 통과를 시도하다 회항한 것으로 선박 추적 데이터에서 확인됐다. 잇단 공격에 선사들이 항로 진입을 재검토하고 있다.","eSum":"At least four oil and gas tankers have turned back from attempting to transit the Strait of Hormuz, ship-tracking data showed, as owners reassess route entry following the latest attacks.","kImp":"회항 선박 증가는 호르무즈 통항 위험에 대한 시장의 실질적 반응을 보여준다.","eImp":"The rising number of tanker U-turns reflects the market's practical response to Hormuz transit risk.","url":"https://www.marinelink.com/news/vessel-attacks-force-hormuz-tanker-uturns-541017"},{"code":"HOT","title":"일본 관련 선박 10척, 호르무즈 해협 탈출","src":"MarineLink","date":"2026-07-06","kSum":"일본과 연계된 선박 10척이 이란 전쟁 여파로 인한 통항 차질을 뒤로하고 호르무즈 해협을 빠져나갔다. 사우디산 원유를 실은 초대형유조선도 함께 통과했다.","eSum":"A fleet of 10 Japan-linked vessels exited the Strait of Hormuz, along with a supertanker carrying Saudi crude, moving past disruptions caused by the Iran war.","kImp":"주요 수입국 연계 선박들의 통항 재개는 부분적 물류 정상화 신호로 해석된다.","eImp":"The transit of vessels linked to major importing nations signals a partial normalization of logistics.","url":"https://www.marinelink.com/news/ten-japanlinked-vessels-exit-hormuz-iran-540921"},{"code":"HOT","title":"美, 이란 항구·군사기지에 추가 공습","src":"The Maritime Executive","date":"2026-07-08","kSum":"미 중부사령부가 이란 내 항구 및 군사기지에 대한 새로운 공습을 개시했다고 발표했다. 이란 혁명수비대의 상선 공격 능력을 저지하려는 목적이라고 밝혔다.","eSum":"US Central Command announced fresh airstrikes on Iranian ports and military bases, aiming to blunt the Revolutionary Guard's ability to continue attacking merchant shipping in the Strait of Hormuz.","kImp":"군사적 확전은 호르무즈를 지나는 상선들의 리스크를 한층 높이고 있다.","eImp":"The military escalation further raises the risk profile for merchant vessels transiting Hormuz.","url":"https://maritime-executive.com/article/photos-u-s-hits-iranian-ports-and-military-bases-in-new-wave-of-strikes"},{"code":"HOT","title":"트럼프 \"정전 끝났다\"…이란, 호르무즈 봉쇄 채비","src":"Seatrade Maritime News","date":"2026-07-08","kSum":"트럼프 대통령이 이란과의 정전이 끝났다고 선언했으며, 이란은 호르무즈 해협 봉쇄에 나설 태세를 갖추고 있는 것으로 전해졌다. 상선 운항 리스크가 다시 최고조에 달하고 있다.","eSum":"President Trump declared the ceasefire with Iran is over as Iran reportedly readies to close the Strait of Hormuz, pushing shipping risk back toward its highest levels.","kImp":"정전 붕괴 선언은 호르무즈 전면 봉쇄 우려를 다시 키우고 있다.","eImp":"The collapse of the ceasefire is reviving fears of a full Hormuz closure.","url":"https://www.seatrade-maritime.com/security/trump-says-ceasefire-is-over-as-iran-readies-for-hormuz-closure"},{"code":"HOT","title":"IMO \"2월 28일 이후 호르무즈 인근 상선 공격 46건, 14명 사망\"","src":"TradeWinds","date":"2026-07-06","kSum":"IMO 집계에 따르면 2월 28일 이후 호르무즈 해협 인근에서 46건의 상선 공격이 발생해 최소 14명의 선원이 사망했다. 상선이 전례 없이 전쟁의 최전선에 서게 됐다는 우려가 커지고 있다.","eSum":"IMO data shows 46 attacks on shipping around the Strait of Hormuz since 28 February have killed at least 14 seafarers, raising concerns that merchant vessels are unprecedentedly on the front line of war.","kImp":"공격 건수와 인명피해 집계는 해운업계의 위험 프리미엄 산정에 직접 반영된다.","eImp":"The attack and fatality tally directly feeds into how the industry prices risk premiums.","url":"https://www.tradewindsnews.com/people/shipping-dragged-into-global-wars-as-seafarer-death-toll-revealed/2-1-2012797"},{"code":"HOT","title":"호르무즈 전쟁위험료, 위기 전 대비 8배 수준 유지","src":"Insurance Business UK","date":"2026-07-02","kSum":"60일 정전 2주째인 7월 1일 호르무즈 해협 통항량은 하루 5척으로 위기 전 평균 100척을 크게 밑돌았다. 전쟁위험료는 위기 전 대비 약 8배 수준을 유지하고 있으며 중앙 항로에는 여전히 기뢰가 남아있다.","eSum":"Two weeks into the 60-day ceasefire, just five vessels transited the Strait of Hormuz on 1 July versus a pre-crisis daily average of over 100. War risk pricing remains around eight times pre-crisis levels, with the central transit corridor still mined.","kImp":"통항량 회복 없이는 보험료 정상화도 요원하다는 것이 보험자들의 판단이다.","eImp":"Underwriters judge that premium normalisation depends on a sustained recovery in transit volumes.","url":"https://www.insurancebusinessmag.com/uk/news/marine/hormuz-war-risk-market-enters-fragile-new-phase-as-ceasefire-clock-ticks-581067.aspx"},{"code":"HOT","title":"중국, 호르무즈 자유 통항 촉구…통행료 부과설 확산","src":"gCaptain","date":"2026-07-03","kSum":"중국이 호르무즈해협의 자유 통항 보장을 촉구하고 나섰다. 이란의 통항료 부과 가능성이 거론되는 가운데 원유 수입 의존도가 높은 중국의 우려가 반영됐다.","eSum":"China has urged unimpeded passage through the Strait of Hormuz as speculation mounts over potential Iranian transit fees, reflecting Beijing's concern given its heavy reliance on Gulf oil imports.","kImp":"주요 소비국의 외교적 개입이 통항료 제도화 여부를 좌우할 변수로 부상했다.","eImp":"Diplomatic pressure from major consumers has become a key variable in whether transit fees are institutionalised.","url":"https://gcaptain.com/china-urges-unimpeded-passage-of-hormuz-as-fee-chatter-mounts/"},{"code":"HOT","title":"IMO 주도 대피작전, 호르무즈 억류 선원 1만1,000명 구출 착수","src":"UN News","date":"2026-06-24","kSum":"IMO가 주도하는 대규모 대피 작전이 시작되며 호르무즈 해협에 수개월간 발이 묶여 있던 1만1,000명 이상의 선원 구출이 본격화됐다.","eSum":"A UN-backed mass evacuation operation began extracting more than 11,000 seafarers stranded for months in the Strait of Hormuz, a move directly tied to the recently signed Iran-US memorandum of understanding.","kImp":"선원 대피는 위기의 인도주의적 측면을 국제사회 의제로 끌어올렸다.","eImp":"The evacuation has elevated the humanitarian dimension of the crisis onto the international agenda.","url":"https://news.un.org/en/story/2026/06/1167794"}]},{"code":"SYS","type":"news","kTitle":"Section 20. 시스템·앱","eTitle":"Section 20. Systems & Apps","items":[{"code":"SYS","title":"Veson Nautical, IMOS·AI·데이터 통합한 'Veson Platform' 출시","src":"The Digital Ship","date":"2026-07-01","kSum":"Veson Nautical이 기존 IMOS 운영체계에 AI 어시스턴트 CoCaptain, AI 기반 메일, 신규 데이터 서비스인 Vessel Insights·Bunker Insights를 하나의 인터페이스로 통합한 'Veson Platform'을 출시했다. 6.5만척 이상 선박에 대한 300여 개 데이터 필드를 제공한다.","eSum":"Veson Nautical launched the Veson Platform, unifying its IMOS operating system with AI assistant CoCaptain, AI-powered Mail, and new Vessel Insights and Bunker Insights data products into a single interface. Vessel Insights covers 300+ data fields across 65,000+ vessels.","kImp":"용선·항해 플랫폼 시장에서 AI 통합 경쟁이 본격화되고 있음을 보여준다.","eImp":"Signals intensifying AI-integration competition among chartering and voyage platform vendors.","url":"https://thedigitalship.com/news/maritime-software/veson-nautical-brings-ai-data-and-collaboration-into-single-maritime-platform/"},{"code":"SYS","title":"Stena Line, 32척 전 선대에 Telko 전자기록부 시스템 도입 완료","src":"The Digital Ship","date":"2026-07-08","kSum":"Stena Line이 RoPax 선대 32척 전체에 Telko의 TELSCOPE 전자기록부(Electronic Record Book) 시스템 도입을 완료했다. 종이 기반 기록을 디지털로 전환해 규정 준수와 운항 효율성을 높인다는 목표다.","eSum":"Stena Line has completed the rollout of Telko's TELSCOPE Electronic Record Book system across all 32 vessels in its RoPax fleet, replacing paper-based logs to improve compliance and operational efficiency.","kImp":"대형 페리 선사의 전면 페이퍼리스 전환 사례로 ERP·PMS 디지털화 흐름을 뒷받침한다.","eImp":"A major ferry operator's fleet-wide paperless rollout underscores the ERP/PMS digitalization trend.","url":"https://thedigitalship.com/news/maritime-software/stena-line-completes-32-vessel-paperless-rollout-with-telko-electronic-record-system/"},{"code":"SYS","title":"ABS, 컨테이너선 적재 결정 지원하는 'Eagle CRoute' 공개","src":"The Digital Ship","date":"2026-07-03","kSum":"ABS가 항로별 라싱(고박) 조건을 반영한 컨테이너선 적재 의사결정 툴 'Eagle CRoute'를 공개했다. 항로에 따라 달라지는 라싱 요건을 신속히 반영해 적재 계획 수립 속도를 높인다.","eSum":"ABS unveiled Eagle CRoute, a route-specific lashing tool that helps containership operators make faster, safer loading decisions by factoring in route-dependent lashing requirements.","kImp":"ABS Nautical Systems 계열의 선박관리 소프트웨어가 컨테이너선 운항 의사결정 영역까지 확장되고 있다.","eImp":"Shows ABS Nautical Systems-linked software expanding into containership operational decision support.","url":"https://thedigitalship.com/news/maritime-software/abs-targets-faster-containership-loading-decisions-with-eagle-croute-route-specific-lashing-tool/"},{"code":"SYS","title":"MOL·IBM Japan, 선박 운항 의사결정 지원 AI 플랫폼 가동","src":"MarineLink","date":"2026-07-01","kSum":"Mitsui O.S.K. Lines(MOL)와 IBM Japan이 공동 개발한 AI 기반 선박 운항 지원 플랫폼이 7월 1일 가동을 시작했다. MOL의 안전운항지원센터(SOSC)를 중심으로 기상·해상·지정학 정보를 통합해 실시간 리스크를 파악하는 생성형 AI 어시스턴트를 탑재했다.","eSum":"MOL and IBM Japan launched an AI-powered platform, live from July 1, that integrates weather, sea condition, vessel operation and geopolitical data through MOL's Safety Operation Supporting Center, with a generative AI assistant flagging real-time operational risks.","kImp":"일본 대형 선사가 생성형 AI를 안전운항 의사결정에 실전 투입한 대표 사례다.","eImp":"A leading example of a major Japanese carrier deploying generative AI directly into safety operations decision-making.","url":"https://www.marinelink.com/news/mol-ibm-japan-launch-ai-platform-vessel-540811"},{"code":"SYS","title":"UniSea, 독일 AI 검사 스타트업 Kaiko Systems 인수","src":"Smart Maritime Network","date":"2026-06-02","kSum":"노르웨이 선대관리 소프트웨어 업체 UniSea가 독일의 AI 기반 현장 점검·컴플라이언스 업체 Kaiko Systems를 인수했다. 이번 인수로 4,000척 이상 선박을 지원하는 해양 소프트웨어 그룹으로 확장된다.","eSum":"Norwegian fleet management software firm UniSea has acquired German AI-powered frontline inspection and compliance company Kaiko Systems, creating a combined maritime software group supporting more than 4,000 vessels.","kImp":"선대관리 소프트웨어 업계에서 AI 검사 스타트업 인수합병이 가속화되고 있다.","eImp":"Reflects accelerating M&A activity as fleet management software vendors acquire AI inspection startups.","url":"https://smartmaritimenetwork.com/2026/06/02/unisea-acquires-kaiko-systems/"},{"code":"SYS","title":"NAPA·삼성중공업, 항해최적화·디지털트윈 기술협력 MOU","src":"Smart Maritime Network","date":"2026-06-30","kSum":"NAPA와 삼성중공업이 연료효율 선박 설계·운항 고도화를 위한 MOU를 체결했다. NAPA의 항해최적화 솔루션을 삼성 자율운항선박(SAS) 플랫폼에 연동하고, SAVER Wing 등 장비 디지털트윈을 구축해 실제 성능을 예측한다.","eSum":"NAPA and Samsung Heavy Industries signed an MOU to integrate NAPA's Voyage Optimization tool with SHI's Samsung Autonomous Ship platform and build digital twins of equipment such as SAVER Wing to predict real-world performance.","kImp":"항해최적화 소프트웨어와 조선사 자율운항 플랫폼 간 결합이 본격화되고 있다.","eImp":"Marks deepening integration between voyage-optimization software and shipbuilder autonomous-ship platforms.","url":"https://smartmaritimenetwork.com/2026/06/30/samsung-heavy-industries-and-napa-partner-on-fuel-efficient-ship-design/"},{"code":"SYS","title":"Nexcade, AI 포워딩 자동화로 600만달러 시드 투자 유치","src":"Splash247","date":"2026-07-08","kSum":"런던 소재 화물운송 AI 스타트업 Nexcade가 Project A Ventures 주도로 600만달러 시드 투자를 유치했다. 포워더의 견적·주문입력·고객소통을 자동화하는 AI 에이전트와 데이터 분석툴 'Atlas'를 공개했다.","eSum":"London-based freight tech startup Nexcade raised $6 million in seed funding led by Project A Ventures, unveiling Atlas, a data analytics tool alongside its AI agents that automate freight forwarding quotations, orders and communications.","kImp":"해운·포워딩 분야 AI 에이전트 스타트업에 대한 투자 유치가 이어지고 있다.","eImp":"Continues the trend of funding rounds for AI agent startups targeting freight forwarding and shipping operations.","url":"https://splash247.com/nexcade-raises-6m-to-automate-freight-forwarding-with-ai/"},{"code":"SYS","title":"신생 해양기술기업 Kyma Technologies, Posidonia서 공식 출범","src":"Splash247","date":"2026-06-11","kSum":"새로운 해양 커넥티비티·IT 기업 Kyma Technologies가 Posidonia 2026에서 공식 출범을 알렸다. 선박 커넥티비티, 온보드 IT·네트워크 인프라, 원격 기술지원을 중심 사업으로 내세웠다.","eSum":"New maritime connectivity and IT company Kyma Technologies officially launched at Posidonia 2026, focusing on vessel connectivity, onboard IT/network infrastructure and remote technical support for shipowners and managers.","kImp":"해운 IT 인프라 시장에 신규 플레이어가 잇따라 진입하며 경쟁이 심화되고 있다.","eImp":"Illustrates growing competitive entry of new players into the maritime IT infrastructure market.","url":"https://splash247.com/new-maritime-technology-player-kyma-technologies-enters-market/"},{"code":"SYS","title":"NYK, Microsoft와 디지털전환 전략 협약 체결","src":"Splash247","date":"2026-07-08","kSum":"일본우선(NYK)이 Microsoft Japan과 클라우드 인프라, 데이터플랫폼, 생성형 AI, 사이버보안 강화를 골자로 한 디지털전환 전략협약을 체결했다. AI 에이전트 활용 확대와 디지털 인재 육성도 병행한다.","eSum":"NYK signed a strategic digital transformation agreement with Microsoft Japan covering cloud infrastructure, data platforms, generative AI systems and cybersecurity, alongside plans to expand AI agent use and build digital talent.","kImp":"대형 선사와 빅테크 간 전사적 디지털전환 파트너십이 확산되고 있다.","eImp":"Shows expanding enterprise-wide digital transformation partnerships between major carriers and big tech firms.","url":"https://splash247.com/nyk-signs-digital-transformation-deal-with-microsoft/"},{"code":"SYS","title":"AI 아바타 면접 플랫폼 'COMPETIQ' 출시, 해기사 부족난 대응","src":"AJOT","date":"2026-07-02","kSum":"글래스고 소재 해양기술기업 The World Yacht가 실시간 AI 아바타 면접관으로 다수 지원자를 동시 면접하는 채용 플랫폼 'COMPETIQ'를 출시했다. 신원·자격 검증을 자동화해 3만9,100명 규모 해기사 부족 문제 대응을 지원한다.","eSum":"Glasgow-based maritime tech firm The World Yacht launched COMPETIQ, a live AI avatar interviewer platform that can screen large numbers of seafarer candidates simultaneously while automating identity and qualification verification, addressing a 39,100-officer shortfall.","kImp":"승선 인력난 심화 속 크루잉 소프트웨어에 생성형 AI 채용 도구가 도입되고 있다.","eImp":"Reflects the introduction of generative-AI recruitment tools into crewing software amid a worsening officer shortage.","url":"https://www.ajot.com/news/new-competiq-a-live-avatar-interviewer-recruitment-platform-launched-as-merchant-shipping-faces-growing-officer-recruitment-crisis"},{"code":"SYS","title":"OceanScore 'PortView', 항만 30여곳으로 도입 확산","src":"AJOT","date":"2026-07-08","kSum":"OceanScore의 항만 배출량 인텔리전스 플랫폼 'PortView'가 유럽 항만을 중심으로 30여개 항만에 도입됐다. EU 항만전략 발표 이후 항만의 환경성과 측정·보고 수요가 늘며 채택이 확산되고 있다.","eSum":"OceanScore's port emissions intelligence platform PortView has been adopted by more than 30 ports, mostly in Europe, with adoption accelerating after the EU Ports Strategy raised expectations for measurable environmental reporting.","kImp":"항만 대상 배출량 관리 SaaS 시장이 규제 강화에 힘입어 빠르게 성장하고 있다.","eImp":"Highlights fast growth of port-focused emissions-management SaaS driven by tightening EU regulation.","url":"https://www.ajot.com/news/oceanscore-sees-growing-port-adoption-of-portview"},{"code":"SYS","title":"IDsure, 디지털 선원신원증명 인프라 확장에 60만유로 시드 유치","src":"The Maritime Executive","date":"2026-05-20","kSum":"해양업계 디지털 신원 인프라 스타트업 IDsure가 60만유로 규모 시드 투자를 유치했다. SITA와 협력한 항공급 신원인증과 Concordium 블록체인 기반 위변조방지 자격증명을 Bahamas Maritime Authority·Columbia Shipmanagement 등과 시범 운영 중이다.","eSum":"Maritime digital identity infrastructure startup IDsure closed a EUR 600,000 seed round to scale aviation-grade identity verification (with SITA) and blockchain-secured, tamper-proof credentials, with pilots underway at the Bahamas Maritime Authority and Columbia Shipmanagement.","kImp":"선원 디지털 신원증명 인프라 스타트업에 대한 초기 투자가 이어지고 있다.","eImp":"Continues early-stage investment momentum in digital seafarer identity infrastructure startups.","url":"https://maritime-executive.com/corporate/idsure-closes-600k-seed-round-to-scale-digital-certificate-infrastructure"},{"code":"SYS","title":"바하마해사청, 블록체인 기반 디지털 선원기록부(DSRB) 도입","src":"IndexBox","date":"2026-06-01","kSum":"Bahamas Maritime Authority가 종이 선원기록부를 대체하는 블록체인 기반 디지털 선원기록부(DSRB)를 6월 1일부로 도입했다. 국가 등록 선대 전체의 승선경력·자격증명을 위변조 불가능한 디지털 방식으로 관리한다.","eSum":"The Bahamas Maritime Authority launched a blockchain-secured Digital Seafarer Record Book (DSRB) on June 1, replacing paper sea-service records with tamper-proof digital credentials across its entire national registry.","kImp":"주요 기국이 선원 디지털 신원증명을 국가 등록시스템에 공식 도입한 사례다.","eImp":"A major flag state formally adopting digital seafarer identity into its national registry system.","url":"https://www.indexbox.io/blog/bahamas-maritime-authority-launches-blockchain-secured-digital-seafarer-record-book/"},{"code":"SYS","title":"Quartermaster, 선박을 해양센서망으로 전환하는 사업에 4,300만달러 시리즈A","src":"TechCrunch","date":"2026-05-20","kSum":"해양 인텔리전스 스타트업 Quartermaster가 4,300만달러 규모 시리즈A를 유치했다. 선박 마스트에 장착하는 센서 패키지 'SmartMast'를 통해 600여척, 25개국에서 실시간 해양 데이터를 수집하는 네트워크를 운영 중이다.","eSum":"Maritime intelligence startup Quartermaster raised a $43 million Series A to expand its SmartMast sensor package, which turns commercial vessels into a real-time ocean sensing network already covering more than 600 active vessels across 25 countries.","kImp":"선박 기반 해양데이터 인프라 스타트업에 대형 자금이 유입되고 있다.","eImp":"Signals significant capital flowing into vessel-based maritime data infrastructure startups.","url":"https://techcrunch.com/2026/05/20/quartermaster-is-building-a-maritime-hive-mind"},{"code":"SYS","title":"AI 해운 플랫폼 오션스마트, 한국투자액셀러레이터로부터 시드 투자 유치","src":"머니투데이","date":"2026-06-04","kSum":"AI 기반 해운 플랫폼 스타트업 오션스마트가 한국투자액셀러레이터로부터 시드 투자를 유치했다. 한진해운·싸이버로지텍 출신 유창현 대표가 항로계획·선복배정·스케줄 조정 등 핵심 의사결정을 디지털화하는 'AI 네이티브 해운 플랫폼' 구축을 목표로 한다.","eSum":"Korean AI-native shipping platform startup Ocean Smart raised seed funding from Korea Investment Accelerator, led by CEO Yoo Chang-hyun, a veteran of Hanjin Shipping and Cyberlogitec, aiming to digitize route planning, capacity allocation and schedule coordination.","kImp":"한국 해운 IT 창업 생태계에서 AI 네이티브 플랫폼에 대한 투자가 시작되고 있다.","eImp":"Marks early-stage investment into AI-native shipping platforms within Korea's maritime IT startup ecosystem.","url":"https://www.mt.co.kr/amp/future/2026/06/04/2026060408565972291"},{"code":"SYS","title":"HJ중공업, HD현대 아비커스와 자율운항 선박 기술협력","src":"글로벌이코노믹","date":"2026-06-08","kSum":"HJ중공업이 HD현대 아비커스와 자율운항 선박 기술 협력을 위한 업무협약을 체결했다. HJ중공업이 건조하는 선박에 아비커스의 자율운항 솔루션 'HiNAS Control'을 적용하는 방안을 추진한다.","eSum":"HJ Shipbuilding signed an MOU with HD Hyundai's Avikus for autonomous navigation technology cooperation, under which HJ will apply Avikus's HiNAS Control autonomous navigation solution to vessels it builds.","kImp":"한국 자율운항 솔루션 업체의 조선사 파트너십이 확대되며 상용화 속도가 빨라지고 있다.","eImp":"Shows Korean autonomous-navigation software expanding its shipbuilder partnerships and accelerating commercialization.","url":"https://www.g-enews.com/article/Industry/2026/06/202606082149175324debea800_1"},{"code":"SYS","title":"Benefit Software, Posidonia 2026서 ERP·bHive·Polus AI 플랫폼 호응","src":"Container News","date":"2026-06-20","kSum":"Benefit Software가 Posidonia 2026에서 해운 ERP, 커넥티비티 허브 bHive, 의사결정지원 AI Polus를 통합한 플랫폼을 선보이며 강한 관심을 끌었다고 밝혔다.","eSum":"Benefit Software reported strong engagement at Posidonia 2026 for its integrated platform combining Benefit ERP, the bHive connectivity hub and the Polus AI decision-support layer, generating a pipeline of new discussions with international shipping companies.","kImp":"해운 ERP·커넥티비티·AI를 결합한 통합 플랫폼 수요가 확인되고 있다.","eImp":"Confirms growing demand for integrated maritime ERP, connectivity and AI decision-support platforms.","url":"https://container-news.com/benefit-software-attracts-strong-interest-at-posidonia-2026/"},{"code":"SYS","title":"ClassNK, 선박 설계데이터 공유 디지털 마켓플레이스 출시","src":"Container News","date":"2026-06-15","kSum":"ClassNK가 조선소·설계사·소프트웨어업체 등이 3D 모델과 설계 데이터를 검색·비교·이용할 수 있는 'ClassNK Design Data Marketplace'를 출시했다. 디지털트윈 프로젝트의 일환으로 데이터 공유 생태계 확대를 노린다.","eSum":"ClassNK launched the ClassNK Design Data Marketplace, a closed-membership platform connecting shipyards, design firms and software providers to search, compare and access 3D models and ship design data, part of its wider Digital Twin Project.","kImp":"선급이 설계데이터 유통을 위한 디지털 인프라를 직접 구축하며 업계 데이터 생태계를 재편하고 있다.","eImp":"A classification society building its own digital marketplace infrastructure to reshape data-sharing across the shipbuilding value chain.","url":"https://container-news.com/classnk-launches-digital-marketplace-for-maritime-design-data/"}]},{"code":"SMGR","type":"news","kTitle":"Section 21. 선박관리사","eTitle":"Section 21. Ship Managers","items":[{"code":"SMGR","title":"Anglo-Eastern, 2026 '선원의 날' 맞아 전 세계 선원 헌신 기려","src":"Anglo-Eastern","date":"2026-06-25","kSum":"Anglo-Eastern이 2026년 '선원의 날(Day of the Seafarer)'을 맞아 전 세계 관리 선단에서 근무하는 선원들의 헌신과 노고를 기리는 캠페인을 진행했다. 회사는 선원 복지 프로그램과 지원 체계를 강조했다.","eSum":"Anglo-Eastern marked the 2026 Day of the Seafarer by honouring the dedication of seafarers across its globally managed fleet, highlighting its welfare programmes and support systems.","kImp":"세계 최대 선박관리사 중 하나가 선원 복지를 핵심 가치로 재확인했다는 점에서 업계에 긍정적 신호를 준다.","eImp":"Reinforces one of the world's largest ship managers' commitment to seafarer welfare as a core value.","url":"https://www.angloeastern.com/news-and-insights/day-of-the-seafarer-2026/"},{"code":"SMGR","title":"Anglo-Eastern Leisure Management, 복수 크루즈 선사의 '백본' 역할 부각","src":"Cruise Industry News","date":"2026-06-01","kSum":"Anglo-Eastern Leisure Management가 여러 크루즈 선사에 기술관리, 승무원 배치, 케이터링, 호텔 운영 등 통합 선박관리 서비스를 제공하며 업계의 핵심 파트너로 자리매김하고 있다는 평가를 받았다.","eSum":"Anglo-Eastern Leisure Management was highlighted as a backbone partner for multiple cruise operators, providing end-to-end vessel management including technical, crewing, catering and hotel operations.","kImp":"크루즈 선박관리 시장에서 Anglo-Eastern의 입지가 넓어지고 있음을 보여준다.","eImp":"Signals Anglo-Eastern's expanding footprint in the cruise ship management market.","url":"https://cruiseindustrynews.com/cruise-news/2026/06/anglo-eastern-backbone-supporting-multiple-cruise-operators/"},{"code":"SMGR","title":"V.Ships, 그리스 Silk Searoad 벌크·탱커 8척 기술관리 수주","src":"MarineLink","date":"2026-02-25","kSum":"V.Group 산하 V.Ships가 그리스 선사 Silk Searoad Maritime과 신규 파트너십을 체결, 벌크선 5척과 탱커 3척 등 총 8척의 기술관리를 맡게 됐다. 그리스 사무소를 통해 장기 관리 및 성과 모니터링을 수행할 예정이다.","eSum":"V.Ships has been appointed by Greek owner Silk Searoad Maritime to provide technical management for its fleet of eight vessels, comprising five bulk carriers and three tankers, managed out of V.'s Greek office.","kImp":"신규 선주 수주를 통해 V.Group의 그리스 시장 내 선단 관리 규모가 확대됐다.","eImp":"Expands V.Group's managed fleet in the Greek market through a new shipowner contract.","url":"https://www.marinelink.com/news/silk-searoad-appoints-v-bulk-tanker-fleet-536066"},{"code":"SMGR","title":"V.Group, MOL과 전략적 파트너십…V.Ships France 지분 인수","src":"LNG Industry","date":"2026-03-11","kSum":"V.Group이 일본 Mitsui O.S.K. Lines(MOL)와 전략적 파트너십을 체결, MOL이 V.Ships France 지분 25%를 인수하기로 했다. V.Ships France는 2027년 인도 예정인 LNG 운반선 2척의 전체 기술관리를 담당한다.","eSum":"V.Group announced a strategic partnership with Mitsui O.S.K. Lines (MOL), under which MOL will acquire a 25% stake in V.Ships France. V.Ships France will take full technical management of two newbuild LNG carriers to be delivered to INEOS in 2027.","kImp":"일본 대형 해운사와의 지분 파트너십으로 V.Group의 LNG 부문 사업이 강화됐다.","eImp":"Strengthens V.Group's LNG shipping business through an equity partnership with a major Japanese carrier.","url":"https://www.lngindustry.com/lng-shipping/11032026/mol-and-vgroup-sign-strategic-partnership/"},{"code":"SMGR","title":"Bernhard Schulte Offshore, 메탄올 대응 CSOV 4척 시리즈 마지막 선박 인도","src":"Offshore Wind","date":"2026-07-03","kSum":"Bernhard Schulte Offshore(BSO)가 신조 CSOV 시리즈의 네 번째이자 마지막 선박 'Windea Clarke'를 인도받았다. 하이브리드 배터리 추진과 메탄올 대응 설계를 갖춘 이 선박은 영국 해상풍력 프로젝트에 즉시 투입된다.","eSum":"Bernhard Schulte Offshore has taken delivery of Windea Clarke, the fourth and final vessel in its newbuild CSOV series, featuring hybrid battery propulsion and a methanol-ready design, immediately starting its first UK offshore wind charter.","kImp":"BSM의 해상풍력 지원선단이 7척으로 확대되며 친환경 오프쇼어 사업이 강화됐다.","eImp":"Expands BSM's offshore wind support fleet to seven vessels, reinforcing its green offshore energy business.","url":"https://www.offshorewind.biz/2026/07/03/bernhard-schulte-offshore-takes-delivery-of-fourth-csov-in-newbuild-series/"},{"code":"SMGR","title":"BSM, 필리핀 해사청(MARINA)과 MOU 체결","src":"Manila Times","date":"2026-03-25","kSum":"Bernhard Schulte Shipmanagement(BSM)가 필리핀 해사청(MARINA)과 양해각서를 체결하며 필리핀 해사 산업 발전을 위한 협력을 강화했다. 필리핀 선원 인력 양성과 표준 향상을 위한 공동 노력이 포함된다.","eSum":"BSM formalized a memorandum of understanding with the Philippines' Maritime Industry Authority (MARINA), reinforcing collaboration to advance the country's maritime sector, including joint efforts on Filipino seafarer training and standards.","kImp":"필리핀 선원 인력의 최대 공급국 지위를 뒷받침하는 국가 차원의 협력이 강화됐다.","eImp":"Strengthens national-level cooperation supporting the Philippines' position as the world's top seafarer supply country.","url":"https://www.manilatimes.net/2026/03/25/business/maritime/bsm-leads-charge-for-ph-maritime-excellence/2306173/"},{"code":"SMGR","title":"Wilhelmsen Ship Management, 선박 수명주기 전문기업 'Cyclus Marine' 출범","src":"Wilhelmsen","date":"2026-04-15","kSum":"Wilhelmsen Ship Management가 신조 감독, 도크 작업, 개조, 재활용 등 선박 전 수명주기를 아우르는 전문기업 'Cyclus Marine'을 싱가포르에서 공식 출범했다. 50년 이상의 선박관리 노하우를 기반으로 한다.","eSum":"Wilhelmsen Ship Management officially launched Cyclus Marine in Singapore, a dedicated vessel lifecycle company covering newbuildings, drydocking, retrofits, conversions and recycling, building on more than 50 years of expertise.","kImp":"Wilhelmsen이 선박 수명주기 관리 전문성을 별도 법인으로 독립시켜 사업 포트폴리오를 다각화했다.","eImp":"Diversifies Wilhelmsen's portfolio by spinning off vessel lifecycle expertise into a dedicated company.","url":"https://www.wilhelmsen.com/media-news-and-events/press-releases/2026/wilhelmsen-ship-management-launches-dedicated-vessel-lifecycle-company-cyclus-marine/"},{"code":"SMGR","title":"Wilhelmsen-MPC Capital, 선박 IT 합작사 'Waterway IT' 공식 출범","src":"Splash247","date":"2026-04-01","kSum":"MPC Capital과 Wilhelmsen Ship Management가 50대50 지분의 선박 IT 합작사 'Waterway IT'를 공식 출범시켰다. 출범 당시 약 400척, 70개 고객사를 대상으로 함부르크, 오슬로, 쿠알라룸푸르 등 거점에서 서비스를 제공한다.","eSum":"MPC Capital and Wilhelmsen Ship Management launched Waterway IT, a 50/50 joint venture providing onboard vessel IT systems, supporting around 400 vessels and 70 customers from hubs including Hamburg, Oslo and Kuala Lumpur.","kImp":"선박 디지털·사이버보안 수요 증가에 대응한 전문 IT 합작법인이 새롭게 탄생했다.","eImp":"Creates a dedicated maritime IT joint venture addressing rising demand for onboard digitalisation and cybersecurity.","url":"https://splash247.com/mpc-capital-and-wilhelmsen-launch-vessel-it-venture/"},{"code":"SMGR","title":"Synergy Marine, 양밍 LNG 이중연료 신조선 2척 기술관리 개시","src":"LNG Industry","date":"2026-02-12","kSum":"Synergy Marine Group이 대만 양밍해운의 1만5,500TEU급 LNG 이중연료 신조 컨테이너선 2척 'YM Willpower'와 'YM Worthiness'의 기술관리를 맡게 됐다.","eSum":"Synergy Marine Group has assumed technical management of YM Willpower and YM Worthiness, two 15,500 TEU LNG dual-fuel newbuilds delivered to Yang Ming, supporting the liner's fleet renewal strategy.","kImp":"대형 컨테이너 선사의 친환경 신조선단 관리를 맡으며 Synergy Marine의 LNG 이중연료 운영 역량이 입증됐다.","eImp":"Validates Synergy Marine's LNG dual-fuel operational expertise through management of a major liner's newbuild fleet.","url":"https://www.lngindustry.com/small-scale-lng/12022026/synergy-marine-group-assumes-technical-management-of-yang-mings-lng-dual-fuel-newbuilds/"},{"code":"SMGR","title":"Synergy Marine, Maersk 메탄올 이중연료 컨테이너선 'Finisterre' 관리 개시","src":"Container News","date":"2026-02-26","kSum":"Synergy Marine Group 산하 Synergy Pacific이 메탄올 이중연료 추진 시스템을 갖춘 5,915TEU 컨테이너선 'Maersk Finisterre'의 기술관리를 새롭게 맡았다. 이 선박은 Maersk에 장기 용선된 상태다.","eSum":"Synergy Pacific, part of Synergy Marine Group, has taken on technical management of the 5,915 TEU methanol dual-fuel container vessel Maersk Finisterre, which is on long-term charter to Maersk.","kImp":"친환경 대체연료 선박 관리 포트폴리오가 확대되며 Synergy Marine의 탈탄소 대응 역량이 강화됐다.","eImp":"Expands Synergy Marine's alternative-fuel vessel portfolio, reinforcing its decarbonisation capabilities.","url":"https://container-news.com/synergy-marine-group-takes-management-of-maersk-finisterre/"},{"code":"SMGR","title":"Columbia Group, 그리스 관리 선단 100척 육박…현지 입지 확대","src":"Manila Times","date":"2026-06-10","kSum":"Columbia Group이 그리스 시장에서 빠르게 성장하며 아테네 자회사 CSM Greece를 통해 관리 선단을 100척에 근접하는 규모로 늘렸다. Posidonia 2026을 앞두고 현지 선주와의 관계 강화를 강조했다.","eSum":"Columbia Group is rapidly expanding in the Greek maritime market, with its fleet under local management via Athens-based CSM Greece climbing to nearly 100 vessels, CEO Andreas Hadjipetrou said ahead of Posidonia 2026.","kImp":"그리스 선주 시장에서 Columbia의 존재감이 크게 확대되고 있음을 보여준다.","eImp":"Demonstrates Columbia's significantly growing presence in the Greek shipowner market.","url":"https://www.manilatimes.net/2026/06/10/business/maritime/columbia-group-nears-100-managed-greek-vessels/2361869/"},{"code":"SMGR","title":"Columbia Shipmanagement, SITA·IDsure와 선원 디지털 신원인증 파일럿","src":"Smart Maritime Network","date":"2026-03-25","kSum":"Columbia Shipmanagement가 SITA, IDsure와 함께 선원 자격증을 디지털화하는 '디지털 선원 수첩' 파일럿을 시작했다. 종이 서류와 수작업 확인을 대체해 항만 검사 시간을 크게 단축할 것으로 기대된다.","eSum":"Columbia Shipmanagement launched a digital identity pilot with SITA and IDsure, digitalising seafarer certificates into a secure digital seafarer handbook that replaces paper documents, cutting port-call tasks from hours to minutes.","kImp":"항공업계의 디지털 신원인증 기술을 해운업에 접목한 사례로 업계 디지털 전환을 선도한다.","eImp":"Pioneers aviation-grade digital identity technology in shipping, leading industry-wide digital transformation.","url":"https://smartmaritimenetwork.com/2026/03/25/columbia-idsure-and-sita-launch-digital-identity-pilot-for-seafarers/"},{"code":"SMGR","title":"OSM Thome, LS마린솔루션 초대형 해저케이블 부설선 프로젝트 착수","src":"MarineLink","date":"2026-07-06","kSum":"OSM Thome가 튀르키예 Tersan 조선소에서 건조 중인 한국 LS마린솔루션의 초대형 해저케이블 부설선에 대한 도면 승인 및 건조 감독 업무를 맡았다. 6월 5일 강재 절단식이 열렸으며 2028년 인도 예정이다.","eSum":"OSM Thome has taken on drawing approval and construction supervision for LS Marine Solution's next-generation ultra-large cable-laying vessel being built at Tersan Shipyard in Turkiye, with steel cutting on 5 June and delivery targeted for 2028.","kImp":"아시아 최대급 해저케이블 부설선 프로젝트 참여로 OSM Thome의 신조 감독 전문성이 재확인됐다.","eImp":"Reaffirms OSM Thome's newbuild supervision expertise through involvement in Asia's largest cable-laying vessel project.","url":"https://www.marinelink.com/news/south-koreas-largest-cable-layer-starts-540933"},{"code":"SMGR","title":"Fleet Management, 지정학적 긴장 속 '조용한 전문가' 선원들 조명","src":"Zawya","date":"2026-06-25","kSum":"Fleet Management가 '선원의 날'을 맞아 지정학적 긴장 속에서도 임무를 수행하는 '조용한 전문가' 선원들에 대한 글로벌 차원의 인식 제고를 촉구했다. 자사 관리 선원 약 600명을 포함한 위험 지역 항해 현황도 공유했다.","eSum":"Fleet Management called for greater global recognition of the silent professionals keeping supply chains moving amid rising geopolitical tensions, noting around 600 of its seafarers have navigated volatile waters since February.","kImp":"지정학적 위기 속 선원 처우 문제에 대한 업계의 관심을 환기시켰다.","eImp":"Raises industry awareness of seafarer welfare amid ongoing geopolitical crises.","url":"https://www.zawya.com/en/economy/global/fleet-management-champions-silent-seafarers-navigating-rising-geopolitical-tensions-qnmost26"},{"code":"SMGR","title":"Fleet Management, 선원 지원 앱 'Pulse' 출시","src":"Splash247","date":"2026-06-30","kSum":"Fleet Management가 '선원의 날'에 맞춰 선원들에게 지속적인 실질적 지원을 제공하는 신규 앱 'Pulse'를 출시했다. 서류·건강 지원 등을 한곳에 모아 2만7,000명 규모의 선원 커뮤니티에 디지털 생명선 역할을 한다.","eSum":"Fleet Management launched Pulse, a new seafarer app providing continuous, practical support at sea, bringing documents and 24/7 health support into one place for its 27,000-strong seafaring community.","kImp":"선원 복지를 위한 디지털 툴 도입으로 선원 지원 서비스 수준이 한 단계 높아졌다.","eImp":"Elevates seafarer support services through the introduction of a dedicated digital welfare tool.","url":"https://splash247.com/fleet-management-unveils-seafarer-app/"},{"code":"SMGR","title":"Caravel Group, 5번째 연례 ESG 보고서 발간…탈탄소 목표 초과 달성","src":"Manila Times","date":"2026-06-17","kSum":"Fleet Management의 모회사 Caravel Group이 5번째 연례 지속가능성 보고서 'Encompass'를 발간했다. 2008년 대비 관리 선박 온실가스 배출집약도를 42% 감축해 2030년 목표치 30%를 이미 초과 달성했다고 밝혔다.","eSum":"The Caravel Group, parent of Fleet Management, published its fifth annual sustainability report, Encompass, reporting a 42% reduction in managed-fleet GHG emission intensity from its 2008 baseline, exceeding its 2030 target of 30%.","kImp":"업계 평균을 상회하는 탈탄소 성과로 Caravel Group의 ESG 리더십이 부각됐다.","eImp":"Highlights the Caravel Group's ESG leadership with decarbonisation performance exceeding industry targets.","url":"https://www.manilatimes.net/2026/06/17/tmt-newswire/media-outreach-newswire/the-caravel-groups-5th-annual-esg-report-outlines-strategic-resilience-in-global-shipping/2367163/"},{"code":"SMGR","title":"Northern Marine, Kaiko Systems 디지털 검사보고 플랫폼 전 선대 도입","src":"Smart Maritime Network","date":"2026-06-17","kSum":"Stena Group 산하 Northern Marine Management가 파일럿 성공 후 Kaiko Systems의 디지털 검사보고 플랫폼을 관리 선대 전체로 확대 적용하기로 했다. 검사보고서 작성 시간이 크게 단축된 것으로 나타났다.","eSum":"Northern Marine Management, part of the Stena Group, agreed to roll out Kaiko Systems' digital inspection reporting platform fleet-wide after a successful pilot showed reduced inspection report completion times.","kImp":"선박관리사의 디지털 검사 도구 도입이 검사·베팅 대응 역량 강화로 이어지고 있다.","eImp":"Ship managers' adoption of digital inspection tools is strengthening inspection and vetting readiness.","url":"https://smartmaritimenetwork.com/2026/06/17/northern-marine-rolls-out-digital-inspection-reporting-platform/"},{"code":"SMGR","title":"Marlow Navigation, Green Marine과 대체연료 선원 훈련 파트너십","src":"Marlow Navigation","date":"2025-11-13","kSum":"Marlow Navigation이 Green Marine과 전략적 파트너십을 맺고 메탄올을 비롯한 대체연료 취급을 위한 선원 훈련을 강화한다. 필리핀과 유럽에서 대면·시뮬레이터 교육을 제공하며 IGF 코스 인증기관 자격도 확보했다.","eSum":"Marlow Navigation entered a strategic partnership with Green Marine to enhance crew training on alternative fuels including methanol, enabling face-to-face and simulator-based training in the Philippines and Europe, and gaining IGF course provider accreditation.","kImp":"대체연료 전환 시대에 대비한 선원 훈련 역량이 한층 강화됐다.","eImp":"Strengthens crew training capability in preparation for the industry's shift to alternative fuels.","url":"https://marlow-navigation.com/en/newsdetails/Marlow-and-Green-Marine-Team-Up"}]}]};